window.NOTES_SEARCH_INDEX = [{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"accessibility-title","heading":"","text":"Accessibility Foundations","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-7d43965ea6e9","heading":"","text":"Build and verify semantic, named, keyboard-operable interfaces with predictable focus and feedback.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-aef5322528f0","heading":"","text":"Semantic HTML & the accessibility tree","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f2f82b8c5faa","heading":"","text":"Accessible names, descriptions & states","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-8cb8955b8216","heading":"","text":"Keyboard navigation & focus ownership","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f1d6615fe8d1","heading":"","text":"Dynamic updates, errors & live regions","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-ccf8cfe09411","heading":"","text":"WCAG, zoom & practical verification","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-c25ec6d47dcd","heading":"","text":"Interview review: demonstrate a usable task","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-tree","heading":"Semantic HTML & the accessibility tree","text":"Semantic HTML & the accessibility tree","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-tree-definition","heading":"Semantic HTML & the accessibility tree","text":"Browsers expose an accessibility tree derived from DOM semantics, state, and rendering. Assistive technologies use it to understand roles, names, values, and relationships. It is related to the DOM but is not a one-to-one copy.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-028089693ae1","heading":"Semantic HTML & the accessibility tree","text":"Example: A native button exposes role and state plus built-in keyboard behavior. A div with role=button changes exposed semantics but still needs focusability and keyboard activation. ARIA describes semantics; it does not implement missing behavior.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-5a0bffd8d469","heading":"Semantic HTML & the accessibility tree","text":"Use: Start with native headings, landmarks, links, buttons, labels, and form controls. Inspect the accessibility tree when markup appears correct but a control is unnamed or misrepresented. Use ARIA to fill a real semantic gap, not to override valid native behavior.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-30d528191335","heading":"Semantic HTML & the accessibility tree","text":"Pitfalls: aria-hidden hides a subtree from assistive technology but does not itself prevent keyboard focus. Do not hide a focused control or ancestor. Decorative icons can be hidden; interactive content needs an operable and understandable contract. See component accessibility guarantees.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-names","heading":"Accessible names, descriptions & states","text":"Accessible names, descriptions & states","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-names-definition","heading":"Accessible names, descriptions & states","text":"An accessible name identifies a control; an accessible description supplies additional guidance. Browsers compute names from sources such as associated labels, aria-labelledby, aria-label, and element content according to the element’s naming rules.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-a60d59395a2f","heading":"Accessible names, descriptions & states","text":"\u003clabel for=\"email\">Email address\u003c/label> \u003cinput id=\"email\" name=\"email\" type=\"email\" aria-describedby=\"email-hint\"> \u003cp id=\"email-hint\">Used for receipts.\u003c/p> \u003cbutton type=\"button\" aria-label=\"Close dialog\">×\u003c/button>","kind":"Code"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-fff4e3898b2d","heading":"Accessible names, descriptions & states","text":"Use: Prefer visible labels that match the accessible name; use aria-labelledby to reference visible text. aria-label can override a name that would otherwise come from content, so adding it casually can create a mismatch. Placeholder text is not a replacement for a persistent label.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-2064a78d8e15","heading":"Accessible names, descriptions & states","text":"State: Expose expanded, selected, checked, disabled, and invalid states through native controls or the correct ARIA attributes. aria-disabled communicates state but does not block clicks or submissions; implement the behavior. Use useId for stable label/description relationships, not as a domain identifier.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-86a9c67dfd79","heading":"Accessible names, descriptions & states","text":"Alternative: If native semantics already express the contract, avoid redundant ARIA. For validation, connect descriptive error text to the field and follow the form feedback model.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-focus","heading":"Keyboard navigation & focus ownership","text":"Keyboard navigation & focus ownership","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-focus-definition","heading":"Keyboard navigation & focus ownership","text":"Focus order should follow a meaningful reading and task sequence. Tab generally moves between controls; composite widgets can use arrow keys internally according to their interaction model. DOM order, visual layout, and focus behavior must work together.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f82a6351e5ea","heading":"Keyboard navigation & focus ownership","text":"Example: Opening a modal moves focus appropriately, keeps interaction in the modal while it is active, and returns focus to the invoking control after close when that control still exists. Native dialog.showModal supplies important browser behavior; choose an initial focus target based on the task.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-c235657e3d8f","heading":"Keyboard navigation & focus ownership","text":"Use: Prefer natural document order and tabindex=0 for elements that truly require focus. tabindex=-1 allows programmatic focus without adding a normal tab stop. Avoid positive tabindex values that create a second, brittle ordering system.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-d0f5a39b9001","heading":"Keyboard navigation & focus ownership","text":"Composite widgets: Roving tabindex moves DOM focus among items; aria-activedescendant keeps focus on a container/input while identifying the active item. They are different implementations and require correct roles, IDs, and keyboard behavior. Virtualization must keep the active descendant available.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-f1fbf8279356","heading":"Keyboard navigation & focus ownership","text":"Pitfalls: A focusable element is not necessarily understandable or operable. Prevent focus traps, preserve visible focus indicators, and handle unmounted targets during navigation. See compound widgets and default-action cancellation.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-announcements","heading":"Dynamic updates, errors & live regions","text":"Dynamic updates, errors & live regions","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-announcements-definition","heading":"Dynamic updates, errors & live regions","text":"A visual DOM update is not always announced to a screen-reader user. Live regions communicate important updates without moving focus. role=status provides polite status semantics; role=alert is assertive and should be reserved for appropriate urgent feedback.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-ac78be92fbec","heading":"Dynamic updates, errors & live regions","text":"Example: Keep a status region mounted and update it with “3 results found” after a search completes. Announcing every keystroke or every streamed token overwhelms the user. A submission failure may need an error summary and intentional focus rather than only a live announcement.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-e807cdaafa51","heading":"Dynamic updates, errors & live regions","text":"Use: Announce meaningful outcomes, maintain focus for ordinary background refreshes, and avoid replacing the focused control unnecessarily. Mark a changing region busy where appropriate and clear the state when updates finish.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-3cc68c6e058f","heading":"Dynamic updates, errors & live regions","text":"Alternatives and limits: Focus movement is appropriate when the task context changes, such as opening a dialog or navigating to an error summary. Live-region behavior varies by browser/assistive-technology combination; verify the actual task with a screen reader rather than assuming every announcement is guaranteed.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-validation","heading":"WCAG, zoom & practical verification","text":"WCAG, zoom & practical verification","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-validation-definition","heading":"WCAG, zoom & practical verification","text":"WCAG organizes accessibility requirements around perceivable, operable, understandable, and robust experiences. Conformance is broader than passing an automated scan; each criterion has applicability and exceptions.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-13ec0e87a0a8","heading":"WCAG, zoom & practical verification","text":"Practical baseline: Check text contrast (generally 4.5:1 for ordinary text, 3:1 for large text), meaningful non-text contrast, visible focus, meaningful link names, alternative text, reflow, zoom, keyboard access, and errors that do not rely on color alone. Target WCAG 2.2 criteria as relevant, including target size and focus not being obscured.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-59ce39f363ec","heading":"WCAG, zoom & practical verification","text":"Verify a task: Navigate only with the keyboard; inspect names/roles/states in the accessibility tree; test zoom and a narrow viewport; enable reduced motion; use a screen reader to submit and recover from an invalid form. Automated tools help find missing labels and some contrast issues but cannot judge a logical workflow or good alternative text.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"search-208e1bcf2004","heading":"WCAG, zoom & practical verification","text":"Tradeoffs: Custom controls and highly dynamic layouts increase the behavior you must implement. Prefer established accessible primitives when they fit. Accessibility is part of the component contract, not a final visual polish pass.","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-review","heading":"Interview review: demonstrate a usable task","text":"Interview review: demonstrate a usable task","kind":"Notes"},{"page":"accessibility.html","topic":"Accessibility Foundations","anchor":"a11y-review-definition","heading":"Interview review: demonstrate a usable task","text":"Explain semantics, naming, keyboard interaction, focus ownership, status/error feedback, and verification together. Show how an autocomplete or dialog works for keyboard and screen-reader users, including asynchronous results and recovery. Correct role names alone are not a complete implementation.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-title","heading":"","text":"Application Design Patterns","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fd9fe876709f","heading":"","text":"Make behavior replaceable, protect application boundaries, evolve implementations, and contain dependency failures. Choose patterns by the problem they solve.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3867005e12f1","heading":"","text":"Choose a pattern by the pressure it resolves","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d6056822f69e","heading":"","text":"Strategy: make a behavior interchangeable","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-67931e0f91d3","heading":"","text":"Adapter: translate an external contract","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5522282479ab","heading":"","text":"Dependency injection: supply dependencies explicitly","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b7a8cb8ca6e2","heading":"","text":"Facade: expose a cohesive workflow","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-194b3637874e","heading":"","text":"Ports and adapters: protect business rules","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8722755198f8","heading":"","text":"Backend for Frontend: shape a server boundary for a client","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d0e94bf7ec65","heading":"","text":"Incremental replacement: Strangler Fig & branch by abstraction","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ca8e5fff18ae","heading":"","text":"Failure containment: circuit breakers & bulkheads","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-784e9e130b0b","heading":"","text":"Interview review: explain the seam and the cost","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-selection","heading":"Choose a pattern by the pressure it resolves","text":"Choose a pattern by the pressure it resolves","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-93ad3e6d998a","heading":"Choose a pattern by the pressure it resolves","text":"Design patterns describe recurring solutions and their tradeoffs. Architectural patterns organize larger boundaries; principles guide decisions. Use the smallest mechanism that makes ownership, behavior, and failure handling explicit. A function or module is often enough; naming a pattern does not require classes or a framework.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-49c9116078f6","heading":"Choose a pattern by the pressure it resolves","text":"PressureStart withRelated alternative","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-750267b44d86","heading":"Choose a pattern by the pressure it resolves","text":"Interchangeable algorithmsStrategyA direct conditional for a small fixed choice.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c7bc0b9bdc31","heading":"Choose a pattern by the pressure it resolves","text":"Mismatched external contractAdapterUse the original API directly when its coupling is acceptable.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b61c18152222","heading":"Choose a pattern by the pressure it resolves","text":"Hard-coded dependenciesDependency injectionDirect imports for stable, pure helpers.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6681b3e397f4","heading":"Choose a pattern by the pressure it resolves","text":"A complicated subsystemFacadeDirect calls when the workflow is already simple.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-0aa0aab26741","heading":"Choose a pattern by the pressure it resolves","text":"Business rules coupled to infrastructurePorts and adaptersModules with explicit boundaries for small applications.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-14341e9426d0","heading":"Choose a pattern by the pressure it resolves","text":"Client-specific API compositionBFFA shared API or framework server route when sufficient.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fb934a7742cc","heading":"Choose a pattern by the pressure it resolves","text":"Risky replacementStrangler Fig / branch by abstractionA direct replacement for small, easily verified changes.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2a7b1b30a581","heading":"Choose a pattern by the pressure it resolves","text":"Dependency failures spreadingCircuit breaker / bulkheadTimeouts and bounded concurrency as a baseline.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1aa9f22ff2ac","heading":"Choose a pattern by the pressure it resolves","text":"For messages and state transitions, use the existing commands, events, and actions, unidirectional data flow, and state-machine sections. This page focuses on application code and integration boundaries.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-strategy","heading":"Strategy: make a behavior interchangeable","text":"Strategy: make a behavior interchangeable","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cd1cd9096c3b","heading":"Strategy: make a behavior interchangeable","text":"Purpose: Encapsulate alternative algorithms behind one contract. The caller chooses a strategy without knowing its implementation. In JavaScript, an injected function is often simpler than a class hierarchy.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4597b3b4e6d8","heading":"Strategy: make a behavior interchangeable","text":"Use when: A product list supports several ranking policies, or an export feature supports different formatters. Each policy varies independently of the calling workflow.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8cfd2f2fa082","heading":"Strategy: make a behavior interchangeable","text":"type Product = { price: number; rating: number }; type Ranking = (a: Product, b: Product) => number; const byPrice: Ranking = (a, b) => a.price - b.price; const byRating: Ranking = (a, b) => b.rating - a.rating; function rank(products: Product[], strategy: Ranking) { return [...products].sort(strategy); // Preserve caller-owned data. } const ranked = rank([{ price: 20, rating: 4 }, { price: 10, rating: 3 }], byPrice);","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8486f5e73e94","heading":"Strategy: make a behavior interchangeable","text":"Benefits and tradeoffs: Policies are independently testable and replaceable, but extra indirection makes a tiny workflow harder to follow. Strategies must honor the same semantics, including mutation, errors, and ordering guarantees.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4415ccf222c8","heading":"Strategy: make a behavior interchangeable","text":"When not to use: For one stable algorithm or two trivial local branches, use a function or conditional. A data lookup table suits constants; Strategy suits executable behavior.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-532ea4427b04","heading":"Strategy: make a behavior interchangeable","text":"Compare: Strategy selects how to perform work; the State pattern changes behavior according to lifecycle state. An Adapter translates an incompatible contract rather than selecting an algorithm. A React render prop may inject a rendering strategy; see composition patterns.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-adapter","heading":"Adapter: translate an external contract","text":"Adapter: translate an external contract","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a51ad6b430c5","heading":"Adapter: translate an external contract","text":"Purpose: Convert an existing interface or data model into the one your application expects. Keep vendor naming, serialization, and error formats at the boundary instead of spreading them through components.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-868fc8ab03f0","heading":"Adapter: translate an external contract","text":"Example: A provider returns { payment_id, amount_cents, currency_code }; a payment adapter maps it into your Payment model. Do not silently guess currency precision: money units are part of the contract.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-17d46c9d0e3f","heading":"Adapter: translate an external contract","text":"type ProviderPayment = { payment_id: string; amount_cents: number; currency_code: 'USD' }; type Payment = { id: string; amountMinor: number; currency: 'USD' }; function adaptPayment(raw: ProviderPayment): Payment { return { id: raw.payment_id, amountMinor: raw.amount_cents, currency: raw.currency_code }; }","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-94b82493cf24","heading":"Adapter: translate an external contract","text":"Use when: Integrating a vendor, migrating APIs, or connecting a form library to an input contract. Validate untrusted JSON at runtime before adapting it; TypeScript annotations do not validate a network response.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1f48404e2597","heading":"Adapter: translate an external contract","text":"Benefits and tradeoffs: Isolates external changes and makes application models consistent. Mapping code and error translation need maintenance; a lowest-common-denominator interface can hide essential provider capabilities.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fd4d1452f7de","heading":"Adapter: translate an external contract","text":"When not to use: Do not wrap every utility in a pass-through adapter. Use a stable API directly if there is no meaningful mismatch or boundary to protect.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-666632bcf9ac","heading":"Adapter: translate an external contract","text":"Compare: Adapter translates a contract; Facade simplifies a subsystem; Strategy swaps behavior. An anti-corruption layer is a broader domain boundary that prevents another system’s concepts from distorting your model, often using adapters. See component and form adapters.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-di","heading":"Dependency injection: supply dependencies explicitly","text":"Dependency injection: supply dependencies explicitly","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3ee3567a59d8","heading":"Dependency injection: supply dependencies explicitly","text":"Purpose: Let an application function receive its collaborators instead of locating or constructing them internally. This separates policy from dependency creation and enables deterministic testing.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6392eaa9414e","heading":"Dependency injection: supply dependencies explicitly","text":"type Clock = () => number; type Session = { expiresAt: number }; function isExpired(session: Session, now: Clock): boolean { return now() >= session.expiresAt; } isExpired({ expiresAt: 2000 }, () => 1000); // Deterministic: false. isExpired({ expiresAt: 2000 }, Date.now); // Production clock.","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-1a5319ebf3c2","heading":"Dependency injection: supply dependencies explicitly","text":"Use when: Time, network clients, storage, or feature policies need to vary by environment or test. Construct them at a composition root—the application’s setup boundary—and inject through parameters, constructors, or a scoped provider.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a6c6fdda213e","heading":"Dependency injection: supply dependencies explicitly","text":"Benefits and tradeoffs: Dependencies become visible and replaceable. Too many parameters can reveal an oversized responsibility; a DI container can hide the dependency graph and introduce lifetime mistakes.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-58b72951b00c","heading":"Dependency injection: supply dependencies explicitly","text":"When not to use: Stable pure helpers usually work as direct imports. Prefer explicit parameters before introducing a container. A service locator asks a registry for dependencies inside business code; it hides requirements that injection makes explicit.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-78b701a99369","heading":"Dependency injection: supply dependencies explicitly","text":"Compare: React Context can distribute an injected service, but Context is a delivery mechanism, not dependency injection itself. Keep service identity stable when appropriate and scope personalized services per request/session; a global singleton can leak SSR user data. Ports define contracts; injection supplies implementations.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-facade","heading":"Facade: expose a cohesive workflow","text":"Facade: expose a cohesive workflow","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4073d07054af","heading":"Facade: expose a cohesive workflow","text":"Purpose: Give callers a small interface over a complex subsystem. A facade hides coordination details while exposing outcomes the caller needs.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-fbebeb8e35ba","heading":"Facade: expose a cohesive workflow","text":"Example: checkout.submit(draft) coordinates validation, an order API, and confirmation mapping. The React form knows about pending, success, and actionable failure rather than every SDK involved.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-f9aa17c7f835","heading":"Facade: expose a cohesive workflow","text":"Use when: Several callers repeat the same sequence or must obey the same integration rules. Return explicit domain outcomes and preserve enough error information for recovery.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e42431e4ea32","heading":"Facade: expose a cohesive workflow","text":"Benefits and tradeoffs: Reduces coupling and centralizes orchestration. An expanding facade can become a god object; keep it scoped to a cohesive capability. Calling several APIs through one method does not make the workflow atomic—handle partial failure explicitly.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-87fd7f979091","heading":"Facade: expose a cohesive workflow","text":"When not to use: One clear operation rarely needs another wrapper. If the concern is only translating one provider’s contract, use an Adapter. If business orchestration is substantial, use an application service with injected collaborators.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-241a8779cd05","heading":"Facade: expose a cohesive workflow","text":"Compare: A facade can be a local module. A BFF is a server boundary and may expose facade-like endpoints. A proxy preserves an interface while controlling access or remote invocation; a facade intentionally simplifies the interface.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-ports","heading":"Ports and adapters: protect business rules","text":"Ports and adapters: protect business rules","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4facf7101cfd","heading":"Ports and adapters: protect business rules","text":"Purpose: In hexagonal architecture, the application core defines the capabilities it needs through ports. Infrastructure implements those ports through adapters. Source-code dependencies point toward the core’s contracts; the core does not import React, a database driver, or a payment SDK.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2e84c0af4e53","heading":"Ports and adapters: protect business rules","text":"Example: A place-order use case accepts a PaymentGateway port and an OrderRepository port. An HTTP handler is a driving adapter that invokes the use case; a payment SDK adapter is a driven adapter used by it. A composition root wires them together through dependency injection.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-20638e230883","heading":"Ports and adapters: protect business rules","text":"// Core contract: owned by the application, not a vendor SDK. interface OrderRepository { findById(id: string): Promise\u003c{ id: string; totalMinor: number } | null>; } function makeLoadOrder(orders: OrderRepository) { return (id: string) => orders.findById(id); } // An HTTP or database adapter implements the port; the use case stays unchanged.","kind":"Code"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-cc65d0d159b3","heading":"Ports and adapters: protect business rules","text":"Use when: Business rules are meaningful, several entry points share them, or infrastructure changes independently. In a frontend, keep pricing rules or workflow decisions in framework-independent modules, while hooks adapt those rules to React lifecycles.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4340b113bf93","heading":"Ports and adapters: protect business rules","text":"Benefits and tradeoffs: Supports focused tests and replaceable infrastructure. Interfaces and mappings add indirection; a port for every CRUD getter can merely duplicate a library API.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8a67e20f56cc","heading":"Ports and adapters: protect business rules","text":"When not to use: A small UI with minimal business logic may need only feature modules and a clear API client. Extract boundaries when a real dependency or policy needs isolation.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8f3012211614","heading":"Ports and adapters: protect business rules","text":"Compare: A layered architecture can also enforce inward dependencies; folder names alone do not guarantee this. An Adapter is one building block, while hexagonal architecture governs relationships across the application. Keep authoritative rules on the server even if shared client logic improves UX; see server authorization.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-bff","heading":"Backend for Frontend: shape a server boundary for a client","text":"Backend for Frontend: shape a server boundary for a client","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-571ed61971e1","heading":"Backend for Frontend: shape a server boundary for a client","text":"Purpose: A BFF provides APIs tailored to one frontend experience. It can aggregate upstream responses, adapt payloads, and keep upstream credentials on the server.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-df62cfedcd6c","heading":"Backend for Frontend: shape a server boundary for a client","text":"Example: A product page calls GET /web/product-page/42; its BFF fetches product and availability data, authorizes the user, and returns a view-oriented response. Reviews may remain independently loaded so a slow optional dependency does not block the page.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-681c646bb3b5","heading":"Backend for Frontend: shape a server boundary for a client","text":"Use when: Web and mobile have materially different data needs, browser-to-service orchestration is complex, or a server-managed session fits the credential threat model. Framework route handlers can implement this boundary without a separate service.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ce110f42efa4","heading":"Backend for Frontend: shape a server boundary for a client","text":"Benefits and tradeoffs: Reduces client coupling and can reduce request waterfalls, but adds server operations, latency, cache policies, and another failure boundary. Enforce resource authorization; avoid an unbounded pass-through proxy or aggregation endpoint.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-47c09b950c56","heading":"Backend for Frontend: shape a server boundary for a client","text":"When not to use: If a shared API already fits, use it directly. Use an API gateway for shared routing, authentication infrastructure, or quotas; use a BFF for client-specific composition. GraphQL offers a query contract and execution model and can be used within a BFF—it is not automatically an alternative deployment boundary.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b60ce3b1d288","heading":"Backend for Frontend: shape a server boundary for a client","text":"Compare: Server Components govern component execution and can call server-side services; a BFF governs the browser-facing API/session boundary. A single framework application can contain both. Protect upstream work with timeouts and failure containment.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-migrations","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Incremental replacement: Strangler Fig & branch by abstraction","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-74eb67721de3","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Purpose: Replace a legacy implementation in controlled steps while keeping the product usable. These approaches reduce the amount of behavior changed at once.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3d4c7f82ea8e","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"ApproachMechanismExample","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-4500ade6df24","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Strangler FigRoute selected capabilities to the new implementation while the legacy implementation serves the rest.Move product routes to a new frontend, then checkout, then remove the old frontend.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c875f74e2c2d","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Branch by abstractionIntroduce a stable interface, implement old and new variants behind it, and migrate callers before removing the old variant.A storage port switches from localStorage to IndexedDB without rewriting each feature simultaneously.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d5fb4b932f98","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Use when: A design-system, framework, API, or persistence migration is too broad for a safe direct replacement. Define the seam, behavior contracts, verification metrics, rollout cohorts, and rollback path before moving traffic.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7e94f3dfeada","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Example plan: Adapt the legacy implementation behind the interface; add the new implementation; switch a small cohort with a feature flag; compare errors and user outcomes; expand; remove the flag and old code. For data/schema changes, use backward-compatible expand-and-contract steps. Rolling code back may not undo already-written data.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-699986c37cba","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Benefits and tradeoffs: Smaller releases and explicit rollback come with temporary duplication and compatibility work. Assign an owner and removal criteria so the transition does not become permanent.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-7af4137ea697","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"When not to use: Prefer a direct replacement for a small, well-tested change. A feature flag is a routing tool, not a migration architecture. Avoid casually dual-writing both systems: divergent writes need an explicit consistency and recovery policy.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c67627210a41","heading":"Incremental replacement: Strangler Fig & branch by abstraction","text":"Compare: Strangler Fig moves capability boundaries; branch by abstraction moves implementations behind a contract. Adapters translate old/new interfaces; production performance measurements help verify a migration’s actual outcome.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-resilience","heading":"Failure containment: circuit breakers & bulkheads","text":"Failure containment: circuit breakers & bulkheads","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5f970f6088d8","heading":"Failure containment: circuit breakers & bulkheads","text":"Purpose: Protect application capacity when dependencies slow down or fail. These patterns are most relevant in your backend/BFF; a browser can degrade its UI but cannot enforce service-wide protection.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-circuit-breaker","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"Circuit breaker: stop repeatedly calling a failing dependency","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-360f9512aaf5","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"A breaker monitors configured failure/timeout rates. In closed state it allows calls; in open state it rejects quickly for a cooldown; in half-open state it permits limited probes to decide whether to recover. Scope breakers to the dependency/operation that fails rather than disabling unrelated work.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-e41010846f68","heading":"Failure containment: circuit breakers & bulkheads › Circuit breaker: stop repeatedly calling a failing dependency","text":"Example: After repeated recommendation-service timeouts, return a clearly degraded product page without recommendations. A breaker needs minimum sample sizes, suitable thresholds, bounded probes, and observability. It does not repair the dependency.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-bulkhead","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Bulkhead: isolate capacity so failures cannot consume everything","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-6d162cddd3d9","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"A bulkhead gives operations separate bounded resources, such as concurrency limits, connection pools, or queues. If image processing saturates its allocation, checkout still has capacity. Bound waiting queues and reject or degrade when capacity is exhausted.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-a685f114d79f","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Use when: A shared process calls unreliable services or handles workloads with different criticality. Breakers reduce futile work; bulkheads limit how far resource exhaustion spreads. They complement each other.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-33d4655a025e","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Benefits and tradeoffs: Better failure isolation costs configuration and capacity planning. Isolated pools can leave capacity unused; a breaker can block a recovering dependency if poorly tuned. Per-instance breakers do not automatically coordinate across a fleet.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-b5ac3b3da400","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"When not to use: Start with request deadlines, bounded concurrency, cancellation where supported, and actionable errors. Add breakers where repeated failures are a demonstrated risk; avoid placing every browser fetch behind a homegrown global breaker.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-051c1f3526ca","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"MechanismPrimary question","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-c166f05027ab","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Timeout/deadlineHow long may this operation occupy resources?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3272d5911b27","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Retry with exponential backoff and jitterIs a bounded additional attempt likely to succeed safely?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-d48f5f467c67","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Circuit breakerShould we attempt this dependency now?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-ddd1a30a2b3e","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"BulkheadHow much isolated capacity may this workload consume?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-2d26c294e76c","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Rate limitingHow frequently may requests enter?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-16ce94c66231","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"React error boundaryWhich UI subtree should show a fallback after a rendering failure?","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-3841dbbf9fe7","heading":"Failure containment: circuit breakers & bulkheads › Bulkhead: isolate capacity so failures cannot consume everything","text":"Retry safely: Retry only suitable transient failures within an overall deadline and attempt budget. Use backoff/jitter to avoid synchronized retry storms; respect server guidance. Mutations need idempotency semantics, and aborting a browser fetch does not guarantee upstream work stopped. Rate limiting protects admission; error boundaries isolate UI failures rather than dependency capacity.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"patterns-review","heading":"Interview review: explain the seam and the cost","text":"Interview review: explain the seam and the cost","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-8da07886fb50","heading":"Interview review: explain the seam and the cost","text":"Start with a concrete pressure: changing policy, an external contract, hidden dependencies, repeated orchestration, migration risk, or failure propagation. Identify who owns the contract, show the smallest implementation, and describe how it fails and is tested. Explain the simpler alternative and why the current complexity earns its cost.","kind":"Notes"},{"page":"application-patterns.html","topic":"Application Design Patterns","anchor":"search-5481d021ca2e","heading":"Interview review: explain the seam and the cost","text":"Practice: Design a replaceable payment client (Adapter + injection), keep checkout rules independent (ports), hide coordination behind a focused facade, and explain why that does not make payment and order persistence atomic. For frontend state, connect these decisions to command handlers and pure reducers.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-programming-title","heading":"","text":"Promises & Async Programming","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-346134525704","heading":"","text":"Coordinate work with explicit dependencies, failure semantics, concurrency bounds, and cancellation.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-0e6877c664e3","heading":"","text":"Promises, async/await & error propagation","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-0a4601ff589a","heading":"","text":"Choose a Promise combinator by failure semantics","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-73e0f341b54c","heading":"","text":"Sequential, parallel & bounded concurrency","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a3d5f39cc04a","heading":"","text":"Cancellation, deadlines & stale results","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-af59ef29645f","heading":"","text":"Async iteration & backpressure","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-2cb4d027c138","heading":"","text":"Interview review: define ownership and outcome","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-promises","heading":"Promises, async/await & error propagation","text":"Promises, async/await & error propagation","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-promises-definition","heading":"Promises, async/await & error propagation","text":"A Promise represents an eventual fulfillment or rejection. Its executor runs synchronously; registered reactions run as microtasks after the current stack completes. async functions always return a promise, and await suspends that function’s continuation, not the JavaScript thread.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-9ae1d0900193","heading":"Promises, async/await & error propagation","text":"async function readJson(url, signal) { const response = await fetch(url, { signal }); if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json(); } try { const profile = await readJson('/api/me'); console.log(profile); } catch (error) { console.error('Profile unavailable', error); }","kind":"Code"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-d17f44b461b9","heading":"Promises, async/await & error propagation","text":"Mechanism: Returning a promise from a then callback adopts its eventual result; throwing rejects the next promise. A catch handler that returns normally converts rejection into fulfillment. Return or await work whose failure the caller must observe; “fire and forget” needs an explicit rejection handler.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a59c40fe8cc0","heading":"Promises, async/await & error propagation","text":"Pitfalls: Fetch usually fulfills for HTTP 4xx/5xx, so inspect status. try/catch catches an awaited rejection, not an unrelated promise you start without awaiting. Avoid async promise executors: their returned promise is ignored by the Promise constructor. See task and microtask scheduling.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-combinators","heading":"Choose a Promise combinator by failure semantics","text":"Choose a Promise combinator by failure semantics","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-combinators-definition","heading":"Choose a Promise combinator by failure semantics","text":"Combinators coordinate promises; they do not create threads, impose concurrency limits, or cancel underlying operations. Constructing an array with async calls usually starts all those operations before the combinator observes them.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-0b07d9eeec7b","heading":"Choose a Promise combinator by failure semantics","text":"APIResultGood fit / pitfall","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-7e96874f90e0","heading":"Choose a Promise combinator by failure semantics","text":"Promise.allAll values in input order; rejects when an input rejects.Independent required reads. Other requests continue after rejection.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-6c5bb3412526","heading":"Choose a Promise combinator by failure semantics","text":"Promise.allSettledAll outcomes after every input settles.Optional widgets or batch reporting; inspect each outcome.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-e7419a70049b","heading":"Choose a Promise combinator by failure semantics","text":"Promise.raceFirst settlement, success or failure.Competing outcomes; a timeout race does not cancel the request.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-277662eca62b","heading":"Choose a Promise combinator by failure semantics","text":"Promise.anyFirst fulfillment; AggregateError if all reject.Equivalent redundant sources where any success suffices. Losers continue.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-dae1eda96e8c","heading":"Choose a Promise combinator by failure semantics","text":"Example: Fetch profile and permissions with Promise.all if the page needs both. Use allSettled for independent dashboard widgets that can fail separately. Do not issue duplicate payments with Promise.any to “make them faster.” Empty inputs also differ: all/allSettled fulfill, any rejects, race stays pending.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-3d0f2d5886b3","heading":"Choose a Promise combinator by failure semantics","text":"Alternative: Use sequential awaits when operation B depends on A, or when a deliberate ordering/rate constraint requires it. For many independent operations, use bounded concurrency rather than an unbounded Promise.all.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-concurrency","heading":"Sequential, parallel & bounded concurrency","text":"Sequential, parallel & bounded concurrency","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-concurrency-definition","heading":"Sequential, parallel & bounded concurrency","text":"Concurrency means operations are in progress during overlapping periods. Parallelism means execution happens simultaneously. Network concurrency does not imply parallel JavaScript execution; CPU-heavy work may need a worker.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a4cc0cce63ad","heading":"Sequential, parallel & bounded concurrency","text":"// Independent requests overlap; returned values retain input order. const [profile, settings] = await Promise.all([ readJson('/api/profile'), readJson('/api/settings') ]); // Simple bounded batches, assuming readJson above and an array of URLs. const results = []; for (let index = 0; index \u003c urls.length; index += 4) { results.push(...await Promise.all(urls.slice(index, index + 4).map(url => readJson(url)))); }","kind":"Code"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-1bafb15b8ec0","heading":"Sequential, parallel & bounded concurrency","text":"Use: Bound concurrency for bulk imports, uploads, or upstream API calls to avoid exhausting memory or connection capacity. Batches are simple but wait for the slowest member before starting the next batch; a worker pool or maintained limiter keeps capacity utilized.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-eaf53c0166be","heading":"Sequential, parallel & bounded concurrency","text":"Choose failure behavior: The example stops starting further batches after failure, but already-started requests continue. Decide whether to collect failures or cancel siblings where supported. forEach(async ...) does not await callbacks; use for/of, map with a combinator, or a limiter.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-a3e41d2db8b9","heading":"Sequential, parallel & bounded concurrency","text":"Comparison: Concurrency limits bound simultaneous work; rate limits bound frequency. Bulkheads isolate capacity between workloads.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-cancellation","heading":"Cancellation, deadlines & stale results","text":"Cancellation, deadlines & stale results","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-cancellation-definition","heading":"Cancellation, deadlines & stale results","text":"Cancellation is an operation’s agreement to stop unnecessary work, not a property of every promise. Use AbortController/AbortSignal for supporting APIs and a request/version guard before committing a result that may now be obsolete.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-45ac359a9048","heading":"Cancellation, deadlines & stale results","text":"Example: Query A starts, then B starts; B finishes first. Cancel A if possible and ensure only the current request updates the display. In a mutation, cancellation cannot prove the server did not commit the write.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-9b75c3b662b0","heading":"Cancellation, deadlines & stale results","text":"Use deadlines: Bound total user-visible time, including retries and queueing. Promise.race can stop waiting but leaves the losing work running; a timeout signal can request cancellation. Clear manually created timers in cleanup.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-d70577c671cb","heading":"Cancellation, deadlines & stale results","text":"When not to retry: Validation errors, authorization failures, and unsafe duplicate effects need resolution, not blind repetition. Use bounded backoff/jitter and idempotency policies where appropriate. See failure containment.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-iteration","heading":"Async iteration & backpressure","text":"Async iteration & backpressure","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-iteration-definition","heading":"Async iteration & backpressure","text":"An async iterable supplies values through promises; for await...of consumes them one at a time. It fits paginated sources and streams that produce values over time. Pull-based consumption can provide backpressure when the producer respects demand; an unbounded push buffer does not become safe merely because it exposes an async iterator.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-c328a4c4904e","heading":"Async iteration & backpressure","text":"async function* pages(loadPage) { let cursor; do { const page = await loadPage(cursor); yield page.items; cursor = page.nextCursor; } while (cursor != null); } for await (const items of pages(loadPage)) { await saveBatch(items); // Illustrative application functions. }","kind":"Code"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-50386357663a","heading":"Async iteration & backpressure","text":"Use: Incremental processing without loading everything into memory. Handle stream errors, cancellation, and resource release; breaking a for-await loop invokes the iterator’s return method when available. A stream reader may still need explicit cancellation/release through its own API.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"search-f8cfa960b3bb","heading":"Async iteration & backpressure","text":"Alternatives: A normal array and loop are simpler for already-loaded data. Use streams for continuous or large transfers; use a bounded task pool when processing items concurrently is safe. Respect pagination contracts rather than assuming every API uses the same cursor rules.","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-review","heading":"Interview review: define ownership and outcome","text":"Interview review: define ownership and outcome","kind":"Notes"},{"page":"async-programming.html","topic":"Promises & Async Programming","anchor":"async-review-definition","heading":"Interview review: define ownership and outcome","text":"For each asynchronous workflow, explain its dependencies, concurrency bound, failure policy, cancellation owner, stale-result guard, and cleanup. Distinguish a task that failed from a response that never reached the client. Connect those decisions to command handlers and outcome events.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"backend-api-title","heading":"","text":"Backend & API Fundamentals","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-ca451eb993b0","heading":"","text":"Implement trustworthy endpoints with explicit validation, error contracts, pagination, database behavior, and resource bounds.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-e17d4b1af7ea","heading":"","text":"Request handlers, middleware & application services","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-e19978172493","heading":"","text":"Validate input & enforce authorization at the server","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-98cb38dc310e","heading":"","text":"Error contracts, retries & ambiguous outcomes","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-e324983c15e0","heading":"","text":"Pagination: offset, keyset & cursor contracts","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-a39372c8ab79","heading":"","text":"Indexes, transactions & connection pools","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-685effc9aae0","heading":"","text":"N+1 queries, batching & request-scoped caching","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-6ab6e821f51c","heading":"","text":"Interview review: make the endpoint’s guarantees explicit","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-request-lifecycle","heading":"Request handlers, middleware & application services","text":"Request handlers, middleware & application services","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-request-lifecycle-definition","heading":"Request handlers, middleware & application services","text":"A request pipeline typically parses and bounds the request, establishes identity, validates input, authorizes the operation, invokes application logic, and serializes the result. Middleware handles cross-cutting concerns; domain rules belong in explicit services/use cases rather than an opaque chain of hooks.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-0753f8a8ce0a","heading":"Request handlers, middleware & application services","text":"Example: PATCH /projects/42 runs through a body-size limit, session validation, schema validation, project-specific permission checks, an update transaction, and a response serializer. Generate a request/correlation ID and propagate it to downstream calls and logs.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-3f6903f5168e","heading":"Request handlers, middleware & application services","text":"Use: Keep transport handlers thin and return well-defined outcomes. Order middleware deliberately: an error handler must cover the relevant downstream work, and logging must not expose tokens or sensitive payloads. Bound time, body size, and queued work.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-30661e236096","heading":"Request handlers, middleware & application services","text":"Alternatives: A small endpoint can be a clear function rather than many layers. Introduce a facade or ports and adapters when dependencies and rules justify them. GraphQL resolvers are another transport/application entry point, not permission to bypass these boundaries.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-validation","heading":"Validate input & enforce authorization at the server","text":"Validate input & enforce authorization at the server","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-validation-definition","heading":"Validate input & enforce authorization at the server","text":"Input validation checks shape, types, ranges, allowed combinations, and business constraints at a trust boundary. Authorization checks whether this principal may perform this operation on this resource. Client types and validation improve UX but cannot establish either server guarantee.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-49bf52d97320","heading":"Validate input & enforce authorization at the server","text":"Example: A create-order endpoint accepts product IDs and quantities, derives trusted prices on the server, validates availability, and checks the account’s permissions. It must not trust a price or tenant owner supplied by the browser.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-a35e62ca4080","heading":"Validate input & enforce authorization at the server","text":"Implementation: Parse into a validated input model, allowlist writable fields to prevent mass assignment, enforce object/tenant scope in data access, and use parameterized queries and output defenses. JSON/schema validation is distinct from HTML sanitisation and SQL parameter binding.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-b4982aeee299","heading":"Validate input & enforce authorization at the server","text":"Tradeoffs: Shared schemas can reduce drift, but server business rules may exceed what the client can know. Avoid duplicating authorization in every UI component as if that protected the endpoint; use server-enforced object-level checks.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-errors","heading":"Error contracts, retries & ambiguous outcomes","text":"Error contracts, retries & ambiguous outcomes","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-errors-definition","heading":"Error contracts, retries & ambiguous outcomes","text":"An API error contract gives clients a stable machine-readable code plus safe details. HTTP status describes the protocol-level outcome; application codes identify recoverable cases without requiring clients to parse human wording.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-4131ba7d9c3e","heading":"Error contracts, retries & ambiguous outcomes","text":"{ \"type\": \"https://example.com/problems/validation\", \"title\": \"Validation failed\", \"status\": 422, \"errors\": [{ \"field\": \"quantity\", \"code\": \"OUT_OF_RANGE\" }], \"requestId\": \"req-42\" }","kind":"Code"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-2512b01177e4","heading":"Error contracts, retries & ambiguous outcomes","text":"Example: Use a documented Problem Details representation or another consistent contract. Expose safe field errors; keep stack traces, credentials, and internal database details out of the response. Log diagnostic context with the same request ID.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-06d8e0074deb","heading":"Error contracts, retries & ambiguous outcomes","text":"Choose recovery: Validation failures need corrected input; forbidden actions need permission changes; transient overload may permit a bounded retry. A 202 acceptance needs a status/polling contract. A lost response after a write is ambiguous: use an idempotency/result lookup policy rather than assuming rollback.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-13e376bd0416","heading":"Error contracts, retries & ambiguous outcomes","text":"Alternatives: A simple API can use a small explicit error union. Do not return 200 with an undocumented failure-shaped body for ordinary REST errors. GraphQL has a separate data-plus-errors execution model. See HTTP status semantics.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-pagination","heading":"Pagination: offset, keyset & cursor contracts","text":"Pagination: offset, keyset & cursor contracts","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-pagination-definition","heading":"Pagination: offset, keyset & cursor contracts","text":"Pagination bounds work and data transfer. Offset pagination skips a count of rows; keyset pagination continues after an ordered key. A cursor is a continuation contract and may encode keyset position, snapshot information, or another server token.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-fe6c9ad10105","heading":"Pagination: offset, keyset & cursor contracts","text":"-- Keyset example for a descending feed; parameter syntax is PostgreSQL. SELECT id, created_at, title FROM posts WHERE tenant_id = $1 AND (created_at, id) \u003c ($2, $3) ORDER BY created_at DESC, id DESC LIMIT $4;","kind":"Code"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-1f0f6db30ada","heading":"Pagination: offset, keyset & cursor contracts","text":"Use: Keyset pagination fits large feeds with deterministic sorting; a matching index such as (tenant_id, created_at, id) can help. Include a unique tiebreaker and bound page size. Offset is simpler for small datasets or page-number navigation but can become expensive and shift under insertions/deletions.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-83f8a89c82e0","heading":"Pagination: offset, keyset & cursor contracts","text":"Contract: Validate cursor format and relevant filter/order scope; an opaque cursor is not authorization. Return next-cursor/has-more information. Pagination alone does not promise a consistent snapshot across changing data; define whether duplicates/gaps are acceptable or snapshot semantics are required.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-ca6949897c75","heading":"Pagination: offset, keyset & cursor contracts","text":"Comparison: GraphQL connection-style edges/pageInfo describe one pagination schema, not a mandatory database algorithm. Frontend virtualization bounds rendered nodes; pagination bounds data retrieval. Use both when needed.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-database","heading":"Indexes, transactions & connection pools","text":"Indexes, transactions & connection pools","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-database-definition","heading":"Indexes, transactions & connection pools","text":"An index accelerates suitable lookup/order operations at the cost of write overhead and storage. A transaction groups database changes under atomicity and isolation rules. A connection pool reuses a bounded number of database connections; it does not create unlimited database capacity.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-77d81e9e01bd","heading":"Indexes, transactions & connection pools","text":"Example: Creating an order and its line items belongs in a transaction so partial writes do not become a valid order. Keep transactions short; a payment provider call is not automatically included in the database transaction. Design explicit recovery for external side effects.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-f2bc1e24009e","heading":"Indexes, transactions & connection pools","text":"Measure: Use query plans and representative data to check index use and actual scans. Composite-column order, selectivity, filtering, and sort requirements matter. Avoid adding indexes to every column without evidence.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-147802fcc319","heading":"Indexes, transactions & connection pools","text":"Concurrency: Isolation levels allow different anomalies. Use atomic conditional updates, constraints, or locks for correctness instead of an unchecked read-then-write. Handle deadlocks/serialization failures with a suitable retry policy. See optimistic concurrency control.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-b52a350238c6","heading":"Indexes, transactions & connection pools","text":"Pool limits: Account for all service instances, bound queue wait and request time, and release connections in finally/managed scopes. Serverless scaling can exhaust a database even when each instance has a small pool. Increasing pool size can increase contention rather than throughput.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-n-plus-one","heading":"N+1 queries, batching & request-scoped caching","text":"N+1 queries, batching & request-scoped caching","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-n-plus-one-definition","heading":"N+1 queries, batching & request-scoped caching","text":"N+1 describes fetching a collection once and then making an additional request/query per item or relation. It occurs in REST handlers, ORM code, and GraphQL resolvers; GraphQL does not cause or automatically solve it.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-1b471d143ea4","heading":"N+1 queries, batching & request-scoped caching","text":"Example: Load 30 orders, then load each customer separately: up to 31 queries. Use an appropriate join/eager load, or collect customer IDs and batch the lookup. Preserve authorization scope and input/output ordering.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-45f880bf7fbc","heading":"N+1 queries, batching & request-scoped caching","text":"Use: Trace database/upstream call counts for representative operations. A request-scoped batch loader can deduplicate repeated entity IDs during one operation; do not share personalized loader caches across users. GraphQL resolver batching shows the integration point.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"search-b2645cc39a2a","heading":"N+1 queries, batching & request-scoped caching","text":"Tradeoffs: Large joins can multiply rows and transfer unnecessary data; batches need limits and per-key failure semantics. Request-local deduplication is not a shared cache invalidation strategy. Choose based on query shape and measured execution, not endpoint style.","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-review","heading":"Interview review: make the endpoint’s guarantees explicit","text":"Interview review: make the endpoint’s guarantees explicit","kind":"Notes"},{"page":"backend-api.html","topic":"Backend & API Fundamentals","anchor":"api-review-definition","heading":"Interview review: make the endpoint’s guarantees explicit","text":"Describe validation, authorization, status/error semantics, pagination, query cost, transaction scope, and bounded resources. Explain what happens when a write succeeds but its response is lost. Prefer clear application contracts over transport-specific magic.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"browser-apis-title","heading":"","text":"Browser APIs: Observation, Workers & Storage","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-5011a6ae043a","heading":"","text":"Choose APIs for cancellation, observation, background computation, persistence, and cross-tab coordination. Define the lifecycle, failure behavior, and data owner before using each mechanism.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-cf38a8dbea93","heading":"","text":"Use browser-managed observation for visibility and size changes, and cooperative cancellation for obsolete asynchronous work. These APIs avoid repeated polling and make resource cleanup explicit.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-b3f5ba84a709","heading":"","text":"AbortController & AbortSignal: cancel obsolete work","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-2e181423707c","heading":"","text":"Intersection Observer: observe visibility boundaries","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-88c75e94f836","heading":"","text":"Resize Observer: observe element dimensions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-2e0a8d1edb04","heading":"","text":"Web Workers: move computation off the main thread","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-9ee8a7949309","heading":"","text":"Browser storage: choose by data and lifetime","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-ab75b3b08f12","heading":"","text":"Cross-tab synchronization: notifications are not transactions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-4de4a9f54004","heading":"","text":"Choosing the right API","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-abort","heading":"AbortController & AbortSignal: cancel obsolete work","text":"AbortController & AbortSignal: cancel obsolete work","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-6287dc1e24d1","heading":"AbortController & AbortSignal: cancel obsolete work","text":"AbortController owns the cancellation action: call abort(). Its AbortSignal communicates cancellation to supporting operations through the signal option, the aborted flag, and an abort event. This is cooperative cancellation, not a way to forcibly stop arbitrary JavaScript or any Promise.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-70f5a0e3a538","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Use it for: Aborting an obsolete search, canceling a fetch when a React component unmounts, or removing event listeners registered with a signal. It complements debouncing and request deduplication; those reduce different kinds of work.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-b51e9a972d8c","heading":"AbortController & AbortSignal: cancel obsolete work","text":"// Inside a Client Component: useEffect(() => { const controller = new AbortController(); const { signal } = controller; async function load() { try { const response = await fetch( '/api/search?q=' + encodeURIComponent(query), { signal } ); if (!response.ok) throw new Error('HTTP ' + response.status); const results = await response.json(); // Guard the state update if cancellation occurred meanwhile. if (!signal.aborted) setResults(results); } catch (error) { if (!signal.aborted) setError(error); } } load(); return () => controller.abort(); // Query changes or unmount. }, [query]);","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-b73ea1b07712","heading":"AbortController & AbortSignal: cancel obsolete work","text":"One-shot lifecycle: An aborted signal stays aborted. Create a new controller for a new operation; a shared signal intentionally cancels all operations listening to it.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-4f716bc23e09","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Error handling: Default abort() cancellation causes fetch to reject with an AbortError. Custom abort reasons and timeout signals can produce other reasons, so do not assume every cancellation has that name.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-8460662c7308","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Timeouts & composition: Where supported, AbortSignal.timeout(ms) provides a timeout signal and AbortSignal.any([...]) combines signals, aborting when the first input aborts. Distinguish user cancellation from timeouts when presenting errors.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-9eed67f276a6","heading":"AbortController & AbortSignal: cancel obsolete work","text":"Correctness boundary: Aborting a request does not guarantee server-side processing stops or undo a completed mutation. Prevent obsolete results from committing to state as well; use a request identity when multiple operations can overlap beyond one effect lifecycle. The state-machine example shows a request-ID transition guard.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-956f4b06b200","heading":"AbortController & AbortSignal: cancel obsolete work","text":"To package these lifecycles as reusable behavior, follow the custom hook contracts; choose effect timing using effects and synchronization.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-intersection","heading":"Intersection Observer: observe visibility boundaries","text":"Intersection Observer: observe visibility boundaries","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-be90ba9111ad","heading":"Intersection Observer: observe visibility boundaries","text":"Intersection Observer asynchronously reports when an element’s intersection with a viewport or scroll container crosses configured thresholds. It replaces many scroll handlers that repeatedly measure element geometry.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-d27752ce70e8","heading":"Intersection Observer: observe visibility boundaries","text":"root: The viewport by default (null), or an ancestor scroll container.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-397401e52856","heading":"Intersection Observer: observe visibility boundaries","text":"rootMargin: Expands or shrinks the observation boundary. A positive bottom margin can trigger prefetching before an element enters the viewport.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-05d4c88cdc9c","heading":"Intersection Observer: observe visibility boundaries","text":"threshold: Intersection-ratio boundaries between 0 and 1. A threshold of 0.5 reports crossings around 50% intersection; it does not promise continuous position updates.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-817a739a35bb","heading":"Intersection Observer: observe visibility boundaries","text":"Use it for: Infinite-scroll sentinels, prefetching upcoming content, or starting work when a section approaches the viewport. For ordinary offscreen images, prefer native loading=\"lazy\" when it meets your needs.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-0afe19728675","heading":"Intersection Observer: observe visibility boundaries","text":"// Prefetch a section shortly before it enters the viewport. const observer = new IntersectionObserver(entries => { for (const entry of entries) { if (!entry.isIntersecting) continue; observer.unobserve(entry.target); // One-time trigger. prefetchSection(entry.target.dataset.section); } }, { root: null, rootMargin: '0px 0px 300px 0px', threshold: 0 }); observer.observe(section); // On teardown: observer.disconnect();","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-357b248c75bb","heading":"Intersection Observer: observe visibility boundaries","text":"Important limits: Geometric intersection does not prove the user actually saw an element; overlays or a background tab can affect visibility. Impression tracking may also need page-visibility checks and a minimum exposure duration. For infinite scrolling, guard against concurrent loads and stop observing when no more data remains.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-resize","heading":"Resize Observer: observe element dimensions","text":"Resize Observer: observe element dimensions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-7cf1b8fad4c8","heading":"Resize Observer: observe element dimensions","text":"Resize Observer reports changes to an element’s observed box size, even when the browser window stays the same size. For example, opening a sidebar can resize a chart without firing a window.resize event.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-5aa0b342b0bc","heading":"Resize Observer: observe element dimensions","text":"Use it for: Resizing charts or canvases, measuring variable-height virtualized rows, or informing JavaScript widgets of container-size changes. For purely visual responsive styles, prefer CSS container queries when possible.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-ad1ee3e47bf7","heading":"Resize Observer: observe element dimensions","text":"// A chart needs an explicit width when its container changes size. const observer = new ResizeObserver(entries => { for (const entry of entries) { chart.resize({ width: entry.contentRect.width }); } }); observer.observe(chartContainer); // Content box by default. // On teardown: observer.disconnect();","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-954a2400c2e3","heading":"Resize Observer: observe element dimensions","text":"Box model: Choose content-box, border-box, or device-pixel-content-box as appropriate. contentRect reports content-box dimensions; the size properties provide the corresponding box measurements.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-93c6e4ce2b54","heading":"Resize Observer: observe element dimensions","text":"Resize feedback loops: Changing the observed element’s size inside the callback can trigger more resize notifications. Avoid circular dependencies; compare expected dimensions before writing. Scheduling writes with requestAnimationFrame() can defer them, but does not fix a logically endless resize loop.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-e7b15441405b","heading":"Resize Observer: observe element dimensions","text":"Scope: This API observes size, not position or viewport intersection. Keep callback work small; expensive callbacks still consume rendering time. See layout thrashing for the cost of interleaving geometry reads and DOM writes.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-workers","heading":"Web Workers: move computation off the main thread","text":"Web Workers: move computation off the main thread","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-d82aa677ac98","heading":"Web Workers: move computation off the main thread","text":"A dedicated Web Worker runs JavaScript in a separate execution context and thread, keeping CPU-heavy parsing, indexing, or transformations from blocking input. It cannot access the DOM. Ordinary async functions and React transitions do not move calculations to another thread.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-1c8c5e8b0c60","heading":"Web Workers: move computation off the main thread","text":"// main.js — initialize once per owner, not on every render. const worker = new Worker(new URL('./sum-worker.js', import.meta.url), { type: 'module' }); let latestId = 0; worker.onmessage = ({ data }) => { if (data.id === latestId) console.log('Current sum:', data.sum); }; function calculate(values) { worker.postMessage({ id: ++latestId, values }); } // On teardown: worker.terminate(); // sum-worker.js — a separate file. self.onmessage = ({ data: { id, values } }) => { const sum = values.reduce((total, value) => total + value, 0); self.postMessage({ id, sum }); };","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f7a27669e9f6","heading":"Web Workers: move computation off the main thread","text":"Communication: postMessage normally uses structured cloning. Transfer large ArrayBuffer values through a transfer list to avoid copying; the sender’s buffer becomes detached. Functions and DOM nodes cannot be cloned.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-cdd00a44a5ad","heading":"Web Workers: move computation off the main thread","text":"Ownership: Track request IDs, handle error/messageerror, and terminate when the owner is disposed. A cancel message cannot interrupt a worker’s long synchronous function; chunk work so it can process messages, or terminate the worker when losing all its tasks is acceptable.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-63db4cd9dc6f","heading":"Web Workers: move computation off the main thread","text":"Tradeoff: Startup, serialization, and communication add overhead. Use a worker for substantial independent CPU work, not small calculations or ordinary network fetching. Measure the main-thread bottleneck first.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-92f579bf47de","heading":"Web Workers: move computation off the main thread","text":"Different workers: A Service Worker is an event-driven network/offline intermediary with a browser-managed lifetime; it is not a permanently running computation worker.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-storage","heading":"Browser storage: choose by data and lifetime","text":"Browser storage: choose by data and lifetime","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-10b9c8f9ae19","heading":"Browser storage: choose by data and lifetime","text":"StorageSuitable useMechanism and tradeoffs","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-82058133f189","heading":"Browser storage: choose by data and lifetime","text":"localStorageSmall preferences such as a theme.Synchronous string key/value API, generally scoped by origin. JSON serialization is manual. Blocking operations make it unsuitable for large datasets. JavaScript can read it.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-39b96cdba8df","heading":"Browser storage: choose by data and lifetime","text":"sessionStorageTemporary tab-specific drafts.Synchronous, scoped by origin and top-level browsing context; survives reloads but is not a shared cross-tab store.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-fa3ee5a08c69","heading":"Browser storage: choose by data and lifetime","text":"IndexedDBStructured offline data, larger datasets, blobs.Asynchronous transactional object stores with indexes. Handle schema upgrades and blocked upgrades from other open tabs; a wrapper can simplify its event-based API.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-0f6dd945d332","heading":"Browser storage: choose by data and lifetime","text":"CookiesSmall server-facing values, especially session identifiers.Attached automatically to matching HTTP requests, adding request overhead. Server-set HttpOnly cookies are inaccessible to JavaScript. Scope, expiration, Secure, and SameSite affect security.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-46138658f264","heading":"Browser storage: choose by data and lifetime","text":"Decision: Keep temporary state in memory, shareable navigation in the URL, small preferences in localStorage, and substantial offline records in IndexedDB. Storage persists a snapshot; it does not make that snapshot authoritative or current. For credentials, follow the token storage threat model.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-storage-quotas","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Storage quotas, eviction & recovery","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f1d88382a98d","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Quota and eviction policies vary by browser, storage type, device, and browsing mode. Origin storage is often best-effort; users or the browser can remove it. Do not promise a universal capacity or treat local persistence as a backup.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f515546960de","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Estimate: await navigator.storage.estimate() returns approximate usage/quota for managed origin storage. It is not a guarantee that the next write succeeds and does not replace each API’s limits.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-a75763e8d7b8","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Persist deliberately: navigator.storage.persist() requests protection against automatic storage-pressure eviction; check its boolean result. It does not stop users clearing data.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-0c18874ad491","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"Handle failures: Catch QuotaExceededError, transaction aborts, blocked access, and malformed stored JSON. Evict expendable cached data, bound cache size, and provide an in-memory fallback. Keep irreplaceable drafts recoverable or synchronize them to a server.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-522832fc234c","heading":"Browser storage: choose by data and lifetime › Storage quotas, eviction & recovery","text":"SSR boundary: Browser storage is unavailable during server rendering. Read it in an appropriate client lifecycle and avoid hydration mismatches from different initial values.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-cross-tab","heading":"Cross-tab synchronization: notifications are not transactions","text":"Cross-tab synchronization: notifications are not transactions","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-51eeda065863","heading":"Cross-tab synchronization: notifications are not transactions","text":"Use BroadcastChannel for messages between eligible same-origin contexts in the same storage partition, or the storage event for localStorage changes. A localStorage change notifies other eligible documents, not the document performing the write. Neither mechanism supplies durable event history.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-9ad2a045c489","heading":"Cross-tab synchronization: notifications are not transactions","text":"const channel = new BroadcastChannel('app-session'); channel.onmessage = ({ data }) => { if (data?.type === 'session-changed') { // Application-owned: recheck session, then refresh/clear identity-scoped data. revalidateSession(); } }; // Publish a notification, never a credential. channel.postMessage({ type: 'session-changed' }); // On teardown: channel.close();","kind":"Code"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-f403140ef906","heading":"Cross-tab synchronization: notifications are not transactions","text":"Practical contracts: Update the sending tab locally, validate message shape, and re-read authoritative state after a notification. Recheck on focus/resume because a closed or suspended tab can miss messages. For atomic shared data updates use IndexedDB transactions; read-modify-write through localStorage or BroadcastChannel is not atomic. Version records and define conflict behavior. Cross-tab logout improves UX, while server invalidation supplies the security boundary.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"api-review","heading":"Choosing the right API","text":"Choosing the right API","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-8c9f2691955d","heading":"Choosing the right API","text":"“Is this section approaching the viewport?” Use Intersection Observer.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-44761b09b900","heading":"Choosing the right API","text":"“Did this chart’s container change size?” Use Resize Observer.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-2d6b7df86f37","heading":"Choosing the right API","text":"“Is this request still relevant?” Use AbortController with a supporting operation and guard stale updates.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-8b864ed21ce6","heading":"Choosing the right API","text":"For CPU work, choose a Web Worker; for persistence, choose by data size and lifetime; for multi-tab coordination, use notifications with explicit recovery.","kind":"Notes"},{"page":"browser-apis.html","topic":"Browser APIs: Observation, Workers & Storage","anchor":"search-e30b93635463","heading":"Choosing the right API","text":"Resource lifecycle: Use unobserve(element) to stop observing one target, or disconnect() for all targets. In React, set up observers in an effect and disconnect them in its cleanup; create controllers within each effect execution so cleanup and StrictMode replay remain safe.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-93241791d1af","heading":"","text":"DOM Events, Scheduling & Delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3393809d5ce7","heading":"","text":"Start with how work is scheduled, then follow an event through the DOM. From there, control its behavior, manage listener lifetime, and handle component boundaries.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-5b782fdd3dd4","heading":"","text":"Event loop & scheduling","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4f2068a35997","heading":"","text":"Event flow & delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-c63f7c15b9d0","heading":"","text":"Default actions & cancellation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b268b8072f07","heading":"","text":"Listener lifecycle","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-796439747bf7","heading":"","text":"Shadow DOM boundaries","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-ad251098ada8","heading":"","text":"Interview review","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-scheduling","heading":"Event loop & scheduling","text":"Event loop & scheduling","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-86825dacc9d2","heading":"Event loop & scheduling","text":"The browser coordinates JavaScript execution, input, and rendering through the event loop. JavaScript on a given main thread runs to completion: a handler cannot be interrupted by another handler halfway through its synchronous work.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-c898f9af8e67","heading":"Event loop & scheduling","text":"Tasks (often called macrotasks): Include timer callbacks and event dispatch for user interactions. There are multiple task queues; do not assume one global FIFO order across all task sources.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3d303af5f258","heading":"Event loop & scheduling","text":"Microtasks: Include Promise reactions, continuations after await, and queueMicrotask() callbacks. At a microtask checkpoint, the browser drains the queue, including newly added microtasks, before continuing. An endless chain causes microtask starvation, delaying input and rendering.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-71db6c2a80df","heading":"Event loop & scheduling","text":"Rendering opportunities: The browser may update rendering between tasks when a frame is due. It does not paint after every task. requestAnimationFrame() callbacks run before the associated rendering update paints, making them suitable for visual updates; heavy callback work still delays the frame.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a386fed38ab6","heading":"Event loop & scheduling","text":"Timers are not deadlines: setTimeout(fn, 0) schedules a future task after an applicable minimum delay; current work, microtasks, and throttling can postpone it. It neither executes immediately nor guarantees a paint first.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-7b66d338e69d","heading":"Event loop & scheduling","text":"console.log('A'); setTimeout(() => console.log('timer'), 0); Promise.resolve().then(() => console.log('promise')); queueMicrotask(() => console.log('microtask')); console.log('B'); // For this standalone example: // A → B → promise → microtask → timer","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-605f7eacc0d2","heading":"Event loop & scheduling","text":"Practical diagnosis: If typing is delayed while a large filter runs, changing an event handler to async does not move the calculation off the main thread. await Promise.resolve() only yields to microtasks, not to a rendering opportunity. Split work and yield via a task boundary, such as scheduler.yield() where supported, or move suitable computation to a Web Worker. See long tasks and execution measurement.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4bb95b1163d9","heading":"Event loop & scheduling","text":"For promise composition, rejection propagation, and bounded parallel requests, see Promises and asynchronous programming. The event loop explains scheduling; combinators define outcome policy.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-254ea6b34db2","heading":"Event propagation, bubbling & delegation","text":"Event propagation, bubbling & delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-f23eeaafa353","heading":"Event propagation, bubbling & delegation","text":"How the event travels through the DOM tree.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-d425058d6f06","heading":"Event propagation, bubbling & delegation","text":"The phase in which an event travels upward from its target toward ancestors.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a1556644705a","heading":"Event propagation, bubbling & delegation","text":"Where we choose to handle the event: at a common ancestor rather than each child.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-propagation","heading":"Event propagation, bubbling & delegation › Event propagation","text":"Event propagation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-341313821bb0","heading":"Event propagation, bubbling & delegation › Event propagation","text":"Event propagation describes the path a DOM event takes. For a typical click, it has three phases: capturing (ancestors down toward the target), target (the element where the event occurred), and bubbling (back up through ancestors). Not every event bubbles.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-7f59522e66aa","heading":"Event propagation, bubbling & delegation › Event bubbling","text":"Event bubbling","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-8a021011916e","heading":"Event propagation, bubbling & delegation › Event bubbling","text":"When a user clicks a nested element, a bubbling click can be observed by listeners on its ancestors. For example, a click on a \u003cbutton> can also reach its enclosing \u003cli> and \u003cul>. Propagation control is separate from default-action cancellation; see Default actions & cancellation for the precise method contracts.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-e46bd5b35a98","heading":"Event propagation, bubbling & delegation › Event delegation","text":"Event delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4af385fa7feb","heading":"Event propagation, bubbling & delegation › Event delegation","text":"Delegation is the intentional use of propagation to centralize event handling. We attach a listener to a parent, inspect event.target, and use a selector such as closest() to identify the relevant descendant. It is especially helpful for dynamic lists and plain DOM code.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b12b263cbf4a","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"Example","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-85aeeedfaee2","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"\u003cul id=\"products\"> \u003cli data-id=\"1\">\u003cbutton>Buy iPhone\u003c/button>\u003c/li> \u003cli data-id=\"2\">\u003cbutton>Buy MacBook\u003c/button>\u003c/li> \u003c/ul> \u003cscript> const products = document.querySelector(\"#products\"); products.addEventListener(\"click\", event => { const item = event.target.closest(\"li[data-id]\"); if (!item || !products.contains(item)) return; console.log(\"Clicked product:\", item.dataset.id); }); \u003c/script>","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-8a8424b5ecec","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"Why closest()? The actual clicked element may be a button or a nested span. closest(\"li[data-id]\") walks from that element toward its ancestors to find the nearest product row. event.target identifies the target visible to this listener (Shadow DOM retargeting can change it); event.currentTarget is the element whose listener is executing (here, the ul).","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-cbdfe7c38968","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"React connection: Hydration connects server-rendered interactive UI to client-side React logic. React already uses delegated handling internally for many events, so ordinary onClick handlers on individual React elements are fine. You still need to understand propagation, event.target vs. event.currentTarget, and stopPropagation().","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-2820fb785226","heading":"Event propagation, bubbling & delegation › Event delegation › Example","text":"Key distinction: Propagation is the browser mechanism. Bubbling is one propagation phase. Delegation is the technique built on top of it, usually using bubbling, although capture-based delegation is also possible.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-cancellation","heading":"Default actions & cancellation","text":"Default actions & cancellation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-05ffd1974766","heading":"Default actions & cancellation","text":"Default actions are browser behaviors associated with events, such as following a link or submitting a form. They are distinct from listener execution and event propagation.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a8c7d3c308e3","heading":"Default actions & cancellation","text":"MethodEffectDoes not do","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-fa41429a331d","heading":"Default actions & cancellation","text":"preventDefault()Cancels the default action if the event is cancelable and the listener is not passive.Stop propagation or other listeners.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-11f5d25996c3","heading":"Default actions & cancellation","text":"stopPropagation()Stops further propagation along the event path.Cancel default actions or stop other listeners on the current target.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-baa7a2881e7a","heading":"Default actions & cancellation","text":"stopImmediatePropagation()Also stops remaining listeners on the current target.Cancel the default action.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-51fa89c53663","heading":"Default actions & cancellation","text":"form.addEventListener('submit', event => { event.preventDefault(); // Handle submission without native navigation. saveForm(new FormData(form)); });","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-8881073e1577","heading":"Default actions & cancellation","text":"Check the contract: event.cancelable tells whether cancellation is supported; event.defaultPrevented records successful cancellation. Calling preventDefault() after an await can be too late; cancel synchronously during dispatch when you need to take over the action.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-095df19bd133","heading":"Default actions & cancellation","text":"Passive listeners: { passive: true } promises not to cancel the default action, allowing the browser to proceed without waiting for a cancellation decision on scroll-blocking events. It does not make handler work faster. A genuinely canceling listener needs passive: false; use it only when necessary.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-90284b2309ae","heading":"Default actions & cancellation","text":"Preserve native behavior: Broad propagation blocking can break ancestor controls and analytics. Intercept only the action you own; custom link handling should preserve modified clicks and opening new tabs.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-lifecycle","heading":"Listener lifecycle & resource ownership","text":"Listener lifecycle & resource ownership","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-6180514d1871","heading":"Listener lifecycle & resource ownership","text":"Register listeners when their owner becomes active and remove them when it is disposed. Listeners attached to long-lived targets such as window can retain stale closures and component data after the UI disappears.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-e0e3d6a1c12d","heading":"Listener lifecycle & resource ownership","text":"capture: Selects capture-phase registration; removal must match the same capture flag.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-3ff18c8a96ef","heading":"Listener lifecycle & resource ownership","text":"once: Removes the listener after its first invocation. If the event never arrives, explicit teardown may still be required.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-4724b7dd3105","heading":"Listener lifecycle & resource ownership","text":"passive: Declares that the listener will not cancel the default action; choose it according to the behavior described above.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-f285f5e6b111","heading":"Listener lifecycle & resource ownership","text":"signal: Associates listener lifetime with an AbortSignal. Aborting its controller removes all listeners registered with that signal. See the AbortSignal cancellation contract.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-13acff1698f6","heading":"Listener lifecycle & resource ownership","text":"function mountPanel(panel) { const controller = new AbortController(); const { signal } = controller; panel.addEventListener('click', handlePanelClick, { signal }); window.addEventListener('resize', updatePanelLayout, { signal }); return () => controller.abort(); // Call when the panel is disposed. }","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-e0f172c35be0","heading":"Listener lifecycle & resource ownership","text":"Callback identity matters: removeEventListener(type, callback, capture) must receive the original function reference, event type, and matching capture flag. A fresh arrow function or a new bind() result will not remove the original listener. The options object itself need not be the same object; passive and once are not removal-matching keys.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-20899986f6cd","heading":"Listener lifecycle & resource ownership","text":"React integration: Install native subscriptions in an effect and return cleanup; the effect dependency and timing rules explain when re-synchronization occurs. Include reactive dependencies to avoid stale closures; recreating the subscription when dependencies change is valid. Make cleanup safe for StrictMode’s development setup/cleanup replay. See AbortController lifecycle for signal reuse and cancellation limits.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-resource-pattern","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Resource ownership & disposal as a general pattern","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-258a82140ff1","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Purpose: Pair acquisition with release at the same ownership boundary. Subscriptions, observers, timers, workers, and connections should not outlive the feature that owns them. This is explicit resource management; it resembles RAII’s ownership discipline, but JavaScript garbage collection does not provide deterministic cleanup of external resources.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-c9c044565851","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Example: A chart component creates a ResizeObserver, subscribes to store updates, and starts a refresh timer in its effect. Cleanup disconnects the observer, unsubscribes, and clears the timer; a shared application connection instead belongs to a longer-lived service, not each chart.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-224534559bcb","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Use when: Setup registers future work or retains a resource. Return a disposer, use try/finally for bounded imperative work, or use an effect cleanup for React synchronization. If setup partially fails, release resources already acquired. Cleanup should tolerate the lifecycle’s repeated setup/teardown.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-0a613b4cf106","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"Benefits and tradeoffs: Prevents leaks, duplicate notifications, and stale writes. Cleanup alone does not undo a completed server operation; combine it with cooperative cancellation and stale-result guards.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-577d704f1048","heading":"Listener lifecycle & resource ownership › Resource ownership & disposal as a general pattern","text":"When not to use: Pure calculations and derived values need no disposal effect. Do not add an effect just to calculate data; see derived state. A finalizer is not a reliable substitute for explicit release. Effect dependencies define resynchronization; subscription contracts define what unsubscribe must stop.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"events-shadow-dom","heading":"When delegation breaks inside a web component","text":"When delegation breaks inside a web component","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-a9c0e4bc845c","heading":"When delegation breaks inside a web component","text":"Symptom: An ancestor listens for a click and calls event.target.closest('button'), but cannot find a button inside a custom element’s shadow tree.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-89c11db065b4","heading":"When delegation breaks inside a web component","text":"Event retargeting: Outside the shadow boundary, event.target typically points to the custom-element host rather than its internal button. closest() does not traverse from a host into its shadow tree.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-2ee0dc69ee8e","heading":"When delegation breaks inside a web component","text":"bubbles vs. composed: Bubbling controls upward propagation; composition controls crossing shadow boundaries. A bubbling custom event still stays inside its shadow tree unless it is composed. Native click events are normally both bubbling and composed.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-2477240e23e5","heading":"When delegation breaks inside a web component","text":"composedPath(): Inspect the event path during dispatch when diagnosing an open shadow root. Closed-root internals are hidden from outside observers. Depending on internal button selectors creates a fragile coupling even when it works.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-b8b7753197ea","heading":"When delegation breaks inside a web component","text":"Prefer a public semantic event: Let the component handle its internal DOM and emit an event such as product-selected with a documented payload. Consumers depend on the component’s public behavior rather than its markup.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-6b8e43c27e90","heading":"When delegation breaks inside a web component","text":"// Inside the component's shadow-root click handler: button.dispatchEvent(new CustomEvent('product-selected', { detail: { productId }, bubbles: true, composed: true })); // Outside: delegate on the public event, not the internal button. productList.addEventListener('product-selected', event => { selectProduct(event.detail.productId); });","kind":"Code"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-bbb49b783717","heading":"When delegation breaks inside a web component","text":"Custom-event contract: CustomEvent defaults to bubbles: false, composed: false, and cancelable: false. Opt into each deliberately. If the component supports a cancelable action, set cancelable: true and check dispatchEvent()’s return value before performing that action. Only expose payload data that belongs in the public API.","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-be47a2ea493a","heading":"Interview review: event delegation","text":"Interview review: event delegation","kind":"Notes"},{"page":"browser-events.html","topic":"DOM Events, Scheduling & Delegation","anchor":"search-fb61e0419da8","heading":"Interview review: event delegation","text":"Event delegation is a pattern built on top of DOM event propagation. Instead of registering event listeners on multiple child elements, we register a single listener on their common ancestor. When an event occurs on a child, it bubbles up to the ancestor, where we can identify the original target and handle the event accordingly. This reduces the need for individual listeners and also works for dynamically added children.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-tooling-title","heading":"","text":"Build Tooling & Modules","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-9859b23d459b","heading":"","text":"Understand what the toolchain transforms, what ships to the browser, and how releases remain compatible.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-ce89985f11e7","heading":"","text":"ES modules, CommonJS & module resolution","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-c8388f8a8dd5","heading":"","text":"Bundling, transpilation & polyfills","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-4d3307e46e33","heading":"","text":"Tree shaking, side effects & dependency duplication","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-08582e3dae5e","heading":"","text":"Asset versioning, source maps & configuration","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-5d4dd7f56e9e","heading":"","text":"Interview review: inspect the emitted application","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-modules","heading":"ES modules, CommonJS & module resolution","text":"ES modules, CommonJS & module resolution","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-modules-definition","heading":"ES modules, CommonJS & module resolution","text":"ES modules (ESM) use import/export with a statically analyzable structure and live bindings. CommonJS (CJS) uses require/module.exports with different loading and interop semantics. Resolution determines which file/package entry a specifier refers to; it depends on runtime, package exports, extensions, and tool configuration.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-b8da3476e4a1","heading":"ES modules, CommonJS & module resolution","text":"// counter.js — ESM export let count = 0; export function increment() { count += 1; } // consumer.js — imported count is a live binding, not a copied snapshot. import { count, increment } from './counter.js'; increment(); console.log(count); // 1","kind":"Code"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-ddcaae452ca5","heading":"ES modules, CommonJS & module resolution","text":"Use: Understand which environment executes a module and how its entry points are selected. Browser native ESM, Node, TypeScript, and bundlers can resolve differently. TypeScript path aliases do not automatically configure the runtime resolver.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-b3459713ec2b","heading":"ES modules, CommonJS & module resolution","text":"Pitfalls: Cyclic dependencies can expose uninitialized bindings or order-sensitive setup. CJS/ESM default/named import interop varies by environment. Fix the dependency graph and package exports rather than relying on accidental transpiler behavior. Code splitting with dynamic import returns a promise; loading can fail.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-pipeline","heading":"Bundling, transpilation & polyfills","text":"Bundling, transpilation & polyfills","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-pipeline-definition","heading":"Bundling, transpilation & polyfills","text":"A bundler analyzes dependencies and emits deployable assets/chunks. Transpilation rewrites source syntax for a target. Type checking verifies types. A polyfill supplies a missing runtime API. These jobs are separate even when one toolchain combines them.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-575a95e89626","heading":"Bundling, transpilation & polyfills","text":"Example: A tool may strip TypeScript and transform optional chaining while never running a full type check. Transforming syntax does not provide fetch, Promise.any, or another missing runtime API. Set explicit browser/runtime targets and run a separate type-check step if needed.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-66ad496a4ef3","heading":"Bundling, transpilation & polyfills","text":"Use: Define supported environments and feature detection before adding polyfills. Prefer native APIs when supported; use targeted compatibility tooling when the support contract requires it. Avoid large indiscriminate polyfill bundles and do not assume a successful build means type-safe or runtime-compatible code.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-1b652d3e5cdf","heading":"Bundling, transpilation & polyfills","text":"Tradeoffs: Bundling can reduce request and packaging overhead; native ESM can simplify suitable deployments. Development behavior can differ from optimized production output, so verify a production build, not only the dev server.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-tree-shaking","heading":"Tree shaking, side effects & dependency duplication","text":"Tree shaking, side effects & dependency duplication","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-tree-shaking-definition","heading":"Tree shaking, side effects & dependency duplication","text":"Tree shaking removes statically provable unused exports/code in an optimized build. It depends on analyzable modules and correct side-effect information; importing a library does not guarantee only the used function is shipped.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-998f3b3f173c","heading":"Tree shaking, side effects & dependency duplication","text":"Example: A module that registers a locale, patches a global, or imports CSS performs observable work at import time. Incorrectly declaring all files side-effect-free can remove necessary behavior. Package sideEffects metadata and bundler behavior need deliberate configuration.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-92dc2ed6549f","heading":"Tree shaking, side effects & dependency duplication","text":"Use: Inspect a bundle analyzer for duplicate dependencies, large transitive imports, and unexpected chunks. Duplicate React instances can break hook assumptions; align peer dependencies and resolution rather than only deduplicating at random.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-024014aaab13","heading":"Tree shaking, side effects & dependency duplication","text":"Alternatives and limits: Tree shaking is different from minification and from lazy loading. Use selective imports where needed, route/feature splitting for deferred code, and remove unused dependencies. Avoid manual micro-optimizations until the emitted bundle identifies a real cost.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-deployment","heading":"Asset versioning, source maps & configuration","text":"Asset versioning, source maps & configuration","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-deployment-definition","heading":"Asset versioning, source maps & configuration","text":"A production artifact should have explicit runtime configuration and cache behavior. Content-hashed asset names allow long-lived immutable caching while the HTML entry point selects the current build.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-3303523e52ea","heading":"Asset versioning, source maps & configuration","text":"Deployment example: Keep older chunks available during rollout so an already-open tab can load its referenced version. Deleting all old assets immediately can cause chunk-load failures. Provide a deliberate recovery flow that does not discard unsaved work.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-efb21441d748","heading":"Asset versioning, source maps & configuration","text":"Configuration: Build-time environment values are embedded into client assets; treat them as public. Runtime public configuration can vary without rebuilding if the application is designed for it. Server secrets must remain server-side; an environment-variable name or prefix is not a security boundary by itself.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-82b678e74496","heading":"Asset versioning, source maps & configuration","text":"Source maps: Map minified stack traces back to authored code. Associate maps with the exact release; decide whether to publish them or upload privately to reporting tooling, since they may reveal source details. Maps improve diagnosis, not security isolation.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"search-285f32acec22","heading":"Asset versioning, source maps & configuration","text":"Tradeoffs: Aggressive asset caching needs versioned URLs and rollout compatibility. A service worker adds another cache/update lifecycle; it is not automatically a deployment fix. Connect decisions to HTTP caching and incremental rollout.","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-review","heading":"Interview review: inspect the emitted application","text":"Interview review: inspect the emitted application","kind":"Notes"},{"page":"build-tooling.html","topic":"Build Tooling & Modules","anchor":"build-review-definition","heading":"Interview review: inspect the emitted application","text":"Explain module boundaries, package resolution, compile targets, polyfills, chunking, cache policy, and release identification. Distinguish “the compiler accepted it,” “the bundle built,” and “the supported runtime can execute it.” Each is a different guarantee.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-title","heading":"","text":"Component Composition","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-377b78e8ee68","heading":"","text":"Start with composition and state ownership, then define customization, accessibility guarantees, and form validation and submission contracts.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-95ca8e814a20","heading":"","text":"Composition builds larger interfaces by combining small components with explicit responsibilities. Prefer a clear contract for behavior, state ownership, and customization over a component with dozens of interacting boolean props.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-1f35b153c2c4","heading":"","text":"Composition patterns & children","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-81f173955c9e","heading":"","text":"Controlled vs. uncontrolled components","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-5e896e526364","heading":"","text":"Compound components & slots","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-72da9b55f152","heading":"","text":"Headless components, hooks & customization","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-c4d15463c9a1","heading":"","text":"Accessible component contracts","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-736d260055d5","heading":"","text":"Progressive enhancement: start with a working platform contract","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-488a24f1335d","heading":"","text":"Complex forms: fields, validation & asynchronous submission","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ad251098ada8","heading":"","text":"Interview review","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-patterns","heading":"Composition patterns & children","text":"Composition patterns & children","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-e87262f53ec8","heading":"Composition patterns & children","text":"Containment with props.children: A wrapper accepts nested React nodes without knowing their concrete component types. A Card can provide structure while callers supply content.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ba47a12e3b72","heading":"Composition patterns & children","text":"Named slots: Props such as header and footer accept React nodes for specific insertion points. Use them when placement has meaning beyond a single children region.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ae2bdffcaaed","heading":"Composition patterns & children","text":"Render props: A function prop, such as renderItem(item), lets the caller render content using state or data supplied by the component. A function-valued children prop is also a render-prop pattern when the component explicitly invokes it.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-7ce165571cff","heading":"Composition patterns & children","text":"function Card({ title, children, footer }) { return ( \u003csection> \u003ch2>{title}\u003c/h2> \u003cdiv>{children}\u003c/div> \u003cfooter>{footer}\u003c/footer> \u003c/section> ); } \u003cCard title=\"Products\" footer={\u003cPagination />}> \u003cProductList /> \u003c/Card>","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ba39dc4f80ba","heading":"Composition patterns & children","text":"Contract: Ordinary children are React nodes, not callbacks. Do not assume every child is an element you can clone; it may be text, a fragment, or null. Prefer explicit props or context over inspecting and rewriting arbitrary children.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-controlled","heading":"Controlled vs. uncontrolled components","text":"Controlled vs. uncontrolled components","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-488ba639d316","heading":"Controlled vs. uncontrolled components","text":"Controlled: The parent owns the input’s value contract (separate from server/client data ownership) and supplies the source of truth through value and a change callback. Use it for coordinated inputs, validation, or externally driven updates. The callback requests a change; the parent must supply the updated value.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ea00488e52b0","heading":"Controlled vs. uncontrolled components","text":"Uncontrolled: The component or native DOM input owns current state. defaultValue supplies an initial value; changing it later is not a controlled update. When editing fetched data, use an explicit server snapshot and draft policy. Read native input values through form submission or refs when needed; see handling submit events with FormData.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-e3c0c71fd0af","heading":"Controlled vs. uncontrolled components","text":"Hybrid API: A reusable component may support either mode, but each state variable must have one owner. For native text inputs, keep controlled values as strings, often value={value ?? ''}, and avoid switching between controlled and uncontrolled modes during the component’s lifetime.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-3b58c5cddd05","heading":"Controlled vs. uncontrolled components","text":"// Controlled: React state is the source of truth. \u003cinput value={query} onChange={event => setQuery(event.target.value)} /> // Uncontrolled: the DOM owns the current value. \u003cinput name=\"query\" defaultValue=\"React\" />","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-compound","heading":"Compound components & slots","text":"Compound components & slots","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-e57acc8e768b","heading":"Compound components & slots","text":"Compound components expose cooperating parts under one API. For example, Autocomplete.Root, Autocomplete.Input, and Autocomplete.Results share a state and behavior contract, often through context, while callers control their arrangement.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-bfc250621451","heading":"Compound components & slots","text":"// Illustrative API: these named parts are supplied by a component library. \u003cAutocomplete.Root value={selected} onValueChange={setSelected}> \u003clabel htmlFor=\"product-search\">Product\u003c/label> \u003cAutocomplete.Input id=\"product-search\" /> \u003cAutocomplete.Results> {products.map(product => ( \u003cAutocomplete.Item key={product.id} value={product.id}> {product.name} \u003c/Autocomplete.Item> ))} \u003c/Autocomplete.Results> \u003c/Autocomplete.Root>","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-80d9ef7cc118","heading":"Compound components & slots","text":"Compound parts vs. slots: Autocomplete.Input is a named component in a compound API; its behavior comes from its implementation and shared contract. A slot is an insertion or replacement point. They can work together, but dot notation alone does not create slot behavior or shared state.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-4c996efb8f22","heading":"Compound components & slots","text":"Shared behavior: The root coordinates selection, open state, active option, and IDs. Parts consume only what they need. Keep ownership explicit if input query and selected value are separate state variables.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-eb1d270ac405","heading":"Compound components & slots","text":"Accessibility contract: A real autocomplete must implement combobox/listbox semantics, accessible names, keyboard navigation, focus management, and relationships such as aria-controls and aria-activedescendant. Flexible composition must preserve those guarantees; see the accessible component contract.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-headless","heading":"Headless components, hooks & customization","text":"Headless components, hooks & customization","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-119494589f95","heading":"Headless components, hooks & customization","text":"Headless APIs separate behavior from visual presentation. A headless component may render unstyled semantic elements; a custom hook can expose state, actions, and prop getters while the caller renders the DOM. See custom hook API design for lifecycle, return-value, and testing contracts. A hook does not automatically share state between callers; shared state needs a provider or store.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-c2848d72d38c","heading":"Headless components, hooks & customization","text":"Props: Configure supported behavior and appearance, such as disabled, size, or a formatter. Prefer explicit options for common variations.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-2052747ec664","heading":"Headless components, hooks & customization","text":"Slots & render props: Replace a region or its rendering when callers need structural flexibility. Forward required refs and accessibility attributes, and compose internal and user event handlers deliberately.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-b23957fe5112","heading":"Headless components, hooks & customization","text":"Adapters: Translate an external contract into the component’s contract. For example, a form-library adapter maps field value, change, blur, error, and ref behavior to the input API. Keep vendor-specific details out of the reusable core. See Adapter vs. Strategy and Facade for integration boundaries.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-f91d75d1afb0","heading":"Headless components, hooks & customization","text":"Tradeoff: More customization creates more combinations to support. Define which party owns markup, focus, state, and accessibility; an unrestricted escape hatch can break invariants that ordinary props preserve.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-accessibility","heading":"Accessible component contracts","text":"Accessible component contracts","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-af159c031e7b","heading":"Accessible component contracts","text":"An accessible component API guarantees semantics, keyboard behavior, focus ownership, and state announcements across its supported customizations. See accessibility foundations for the tree, names, and keyboard model. Accessibility belongs to the behavior contract, including in headless APIs.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-5ec8d9cf9e05","heading":"Accessible component contracts","text":"Prefer native semantics: A native button provides keyboard activation and disabled behavior. Adding role=\"button\" to a div does not implement these. Give non-submit buttons inside forms type=\"button\".","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-4fa7063e26ba","heading":"Accessible component contracts","text":"Define the accessible name: Associate labels with inputs; expose labels for icon-only controls. Forward stable IDs, aria-describedby, and state attributes to the actual interactive element. Use useId for relationships, not list keys.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-63d94797b9e1","heading":"Accessible component contracts","text":"Own focus deliberately: A modal dialog needs an accessible title, appropriate initial focus, constrained focus navigation, inert background behavior, and focus restoration on close. Native dialog.showModal() supplies important platform behavior; custom dialogs must implement it.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-397467afad4e","heading":"Accessible component contracts","text":"Specify keyboard interaction: Compound widgets need a documented model, such as arrow navigation and an active descendant for a combobox. aria-activedescendant references a real option ID while DOM focus stays on the input; keep that option mounted when virtualizing.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-784b078a9766","heading":"Accessible component contracts","text":"Preserve the contract through slots: Forward refs and merge required IDs, ARIA attributes, and handlers. A replacement must preserve the expected element semantics. Define whether a user handler’s preventDefault() vetoes internal behavior; see default-action cancellation.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-029b820ba93c","heading":"Accessible component contracts","text":"Validate: Test keyboard-only use, focus restoration, accessible names/states, zoom, and a screen reader. Automated accessibility checks catch only part of the contract. Reuse established accessible primitives for complex widgets when their API fits.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-progressive","heading":"Progressive enhancement: start with a working platform contract","text":"Progressive enhancement: start with a working platform contract","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-3bec404c99e5","heading":"Progressive enhancement: start with a working platform contract","text":"Purpose: Build a useful baseline with browser capabilities, then enhance it where JavaScript is available. The baseline must actually work: semantic markup alone does not make a client-only workflow functional without JavaScript.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-26c44902d4e8","heading":"Progressive enhancement: start with a working platform contract","text":"Example: A server-handled search form navigates to a results page; client code can later enhance it with debouncing and in-place results. A real anchor preserves copy-link, open-in-new-tab, keyboard, and navigation behavior.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-efecc847a45e","heading":"Progressive enhancement: start with a working platform contract","text":"\u003cform action=\"/search\" method=\"get\"> \u003clabel htmlFor=\"catalog-query\">Search products\u003c/label> \u003cinput id=\"catalog-query\" name=\"q\" type=\"search\" /> \u003cbutton type=\"submit\">Search\u003c/button> \u003c/form>","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-87c5b970fce2","heading":"Progressive enhancement: start with a working platform contract","text":"Use when: Content, navigation, and form submission should remain useful during slow JavaScript loading, partial failure, or constrained devices. Native server endpoints must validate/authorize input; state-changing forms still need CSRF protection.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-619473afcc9a","heading":"Progressive enhancement: start with a working platform contract","text":"Benefits and tradeoffs: Preserves platform affordances and a resilient baseline, but enhanced and baseline paths must share rules and be verified. Do not intercept navigation or submission until the enhancement can fulfill its contract.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-837893d99ab1","heading":"Progressive enhancement: start with a working platform contract","text":"When not to force a full fallback: Rich canvas editors and complex live collaboration may inherently require JavaScript. Keep accessible surrounding navigation, explain loading/failure, and recover drafts rather than maintaining an unusable duplicate implementation.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-a5daac2c7a4c","heading":"Progressive enhancement: start with a working platform contract","text":"Compare: SSR improves initial HTML delivery but does not automatically make interactions work without JavaScript; see hydration. Graceful degradation starts from a richer experience and defines fallback; progressive enhancement starts with the baseline. Framework form Actions have framework-specific enhancement guarantees; choose them deliberately alongside the form submission contract.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-forms","heading":"Complex forms: fields, validation & asynchronous submission","text":"Complex forms: fields, validation & asynchronous submission","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-bc10980d3dba","heading":"Complex forms: fields, validation & asynchronous submission","text":"Compose a form from a form owner, field adapters, and domain sections. The owner coordinates submission and cross-field rules; each field exposes name, value/change or default value, blur/touched state, error, and a focusable ref. Use native fieldset/legend for related controls.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-74328cddb250","heading":"Complex forms: fields, validation & asynchronous submission","text":"Choose ownership: Simple forms can use native inputs and FormData. Use controlled fields for coordinated interactions; a form library helps with dirty/touched tracking, field arrays, and subscriptions. Preserve unsaved drafts when remote data changes.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-f18f0f02ddab","heading":"Complex forms: fields, validation & asynchronous submission","text":"Validate at the right boundary: Native constraints handle basic required/type/range checks. Schema validation can handle cross-field/domain structure. Client validation improves feedback; the server must independently validate input and authorize the operation. Validation is separate from output encoding and HTML sanitisation.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-b97a61b6b71c","heading":"Complex forms: fields, validation & asynchronous submission","text":"Keep validation responsive: Show errors after blur or an attempted submit as appropriate. Debounce asynchronous checks such as username availability, cancel obsolete checks, and guard stale responses. Availability checks are advisory; the server must still enforce uniqueness when saving.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-138332e5887d","heading":"Complex forms: fields, validation & asynchronous submission","text":"Model submission: Distinguish idle, validating, submitting, success, validation failure, conflict, and network failure. Prevent unintended repeat submissions; retain input on failure and map server field errors back to their fields. See useActionState and useFormStatus for React Action-based forms.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-ed0104875d55","heading":"Complex forms: fields, validation & asynchronous submission","text":"// A reusable field contract; the form owner supplies validation state. function EmailField({ id, value, onChange, error }) { const errorId = id + '-error'; return ( \u003cdiv> \u003clabel htmlFor={id}>Email\u003c/label> \u003cinput id={id} name=\"email\" type=\"email\" required value={value} onChange={onChange} aria-invalid={error ? true : undefined} aria-describedby={error ? errorId : undefined} /> {error && \u003cp id={errorId}>{error}\u003c/p>} \u003c/div> ); }","kind":"Code"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-33b28ddfad00","heading":"Complex forms: fields, validation & asynchronous submission","text":"Accessible feedback: On failed submission, render an error summary with links to invalid fields and move focus to the summary or first invalid field. Associate inline errors through aria-describedby; announce submission status through a restrained live region. Do not announce every keystroke or rely on color alone.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-3b50d20b5bdc","heading":"Complex forms: fields, validation & asynchronous submission","text":"Complexity and tradeoffs: Use stable domain IDs for dynamic field arrays so reordering preserves field identity. Define validation and draft retention across multi-step forms. A disabled submit button only prevents local repeats; retries and ambiguous network outcomes still need a server-supported idempotency and conflict policy. Aborting the request does not undo a save.","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"composition-review","heading":"Interview review","text":"Interview review","kind":"Notes"},{"page":"component-composition.html","topic":"Component Composition","anchor":"search-4b4054c92dd5","heading":"Interview review","text":"Interview takeaway: Start with state ownership and accessibility, then choose props, children, compound parts, or a headless hook according to the flexibility callers actually need. See Context + useReducer for coordinating compound parts.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-title","heading":"","text":"State Ownership, Context & Data","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-12c0258b7efb","heading":"","text":"Choose the authoritative owner first, including the URL. Model transitions and sharing, then coordinate remote data, drafts, overlapping mutations, and real-time updates.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-22d266e9c9b3","heading":"","text":"Server state vs. client state: choose by ownership","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e5ae43401d04","heading":"","text":"URL state: navigation is a state owner","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-69668fcfb8f0","heading":"","text":"Unidirectional data flow & derived state","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9376036c0d74","heading":"","text":"Message design: actions, commands, events & payloads","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a505255275ef","heading":"","text":"Model local workflows and valid transitions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bb2219b3510c","heading":"","text":"Share state through Context","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a1b4094f6865","heading":"","text":"Observer, publish–subscribe & external stores","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9750620907ed","heading":"","text":"Synchronize remote data and local drafts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-7cc8248fc8c9","heading":"","text":"Optimistic updates & concurrent mutation conflicts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-16421a2385c5","heading":"","text":"Real-time updates: WebSockets vs. Server-Sent Events","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ad251098ada8","heading":"","text":"Interview review","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-server-client","heading":"Server state vs. client state: choose by ownership","text":"Server state vs. client state: choose by ownership","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-05a89860497e","heading":"Server state vs. client state: choose by ownership","text":"Client state is state whose authoritative owner is the running UI: an open dialog, selected tab, or unsaved form draft. Server state is data owned by a remote system: a product, profile, or purchase record. The browser holds a cached representation of server state that can become stale or change independently of this tab.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-1bdf77b995e6","heading":"Server state vs. client state: choose by ownership","text":"Two separate dimensions: Server/client state describes data ownership. Server/Client Components describe component execution boundaries. A Client Component can read and mutate server state; sending fetched data as props does not turn it into client-owned state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5c4f083115e1","heading":"Server state vs. client state: choose by ownership","text":"QuestionClient stateServer state","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a326bc07adc5","heading":"Server state vs. client state: choose by ownership","text":"Who owns the truth?The UI, its parent, or a client store.A remote system; the client has a snapshot.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-94a265229866","heading":"Server state vs. client state: choose by ownership","text":"Typical changesUser interactions and local workflow transitions.Reads, mutations, other users, background jobs, and remote events.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8df9caf46cc9","heading":"Server state vs. client state: choose by ownership","text":"Primary concernsOwnership, transitions, persistence needs, and subscription scope.Freshness, fetching, errors, retries, invalidation, and reconciliation.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9a86cb99c3de","heading":"Server state vs. client state: choose by ownership","text":"Typical toolsuseState, useReducer, Context, or a client store.Framework loaders/Server Components, TanStack Query, SWR, or a supported data layer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tool-selection","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"When to use which tool","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-4fb53216bdd1","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Local UI state: Start with useState; use useReducer for related transitions. Keep the owner close to its consumers.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bf51e7af9473","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Shared client state: Lift state to a common parent or distribute it through Context. An external store can fit broad, frequent, selectively subscribed updates; sharing alone does not make state server state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-375458426d0b","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Navigation state: Put shareable filters, sorting, and pagination in the URL when refresh, back/forward navigation, or copied links should preserve them. The query result is server state; the selected filter is a client/navigation input.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f146459bb7d5","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Read-mostly page data: A framework loader or Server Component may fetch before rendering and provide route-level revalidation. Do not automatically add a second client cache when the framework already owns the needed data lifecycle.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-de0c9b3fa33a","heading":"Server state vs. client state: choose by ownership › When to use which tool","text":"Interactive remote data: Use a query cache when multiple consumers need remote data, background refresh, mutation coordination, or cache reuse across navigation. A small isolated request can use an effect, but then you own cancellation and race handling plus the remaining loading/error lifecycle.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-tradeoffs","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Benefits, limitations & alternatives","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e807f9f3f85a","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Local state/reducer — benefits: Explicit UI ownership, simple transitions, no remote-cache machinery. Tradeoff: Sharing and persistence require design; these hooks do not provide refetching or invalidation.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2e99a79220e4","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Context/client store — benefits: Shares client-owned workflows and operations across a subtree. Tradeoff: Provider updates and subscription granularity need attention. Context can distribute fetched data, but does not itself supply a server-state synchronization policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c7e2cca196e9","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Query cache — benefits: Shares keyed remote data and provides configurable freshness, retries, in-flight deduplication, and mutation lifecycle hooks. Tradeoff: Adds a dependency and policies for keys, invalidation, memory, and identity changes. It cannot infer all business relationships or make cached data always current.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bb3e88c6c0c7","heading":"Server state vs. client state: choose by ownership › Benefits, limitations & alternatives","text":"Framework-managed data — benefits: Integrates loading, rendering, navigation, and potentially SSR. Tradeoff: Cache and revalidation semantics depend on the framework; mixed framework/client caches require explicit coordination.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-url","heading":"URL state: navigation is a state owner","text":"URL state: navigation is a state owner","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-95c1dd4374bd","heading":"URL state: navigation is a state owner","text":"Use the URL for state that should survive refresh, support copied links, and participate in back/forward navigation: search terms, filters, sort order, pagination, and the selected resource. Keep transient UI such as hover state local. The URL stores the selection; a query cache stores the resulting server data.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d059a3da62c0","heading":"URL state: navigation is a state owner","text":"Read and validate: Parse URLSearchParams, allowlist sort values, normalize defaults, and validate page numbers. Use the normalized values in query keys so cache identity matches the request.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-7eefd10b5c9f","heading":"URL state: navigation is a state owner","text":"Update through the router: Prefer its search-parameter API for subscriptions, navigation, and SSR integration. Use push for meaningful history entries and replace for refinements that should not flood history. Reset the page when a filter changes.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-90aa6b8552b1","heading":"URL state: navigation is a state owner","text":"One authoritative source: Derive committed filters from the URL. A local input draft is useful while typing, but define when it is committed and how navigation resets it. Two independently synchronized copies invite loops and stale values.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b28e1fc9a2af","heading":"URL state: navigation is a state owner","text":"Tradeoffs: URLs improve shareability but expose values in history, logs, and potentially referrers. Do not put credentials or sensitive drafts there. Encoding is not encryption.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f1b1340ca77c","heading":"URL state: navigation is a state owner","text":"Implementation: Read new URLSearchParams(location.search) at a router boundary, normalize inputs, then pass them to the data layer. Bare history.pushState() does not emit popstate; a custom integration must publish its own updates and handle back/forward events. See persistence choices for state that should persist without becoming a link.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-unidirectional","heading":"Unidirectional data flow & derived state","text":"Unidirectional data flow & derived state","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-354a45d0b82a","heading":"Unidirectional data flow & derived state","text":"Purpose: Make changes traceable: interaction → handler/action → state transition → render. The rendered view derives from state; it does not maintain an independently synchronized copy of the same truth.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a2538947e578","heading":"Unidirectional data flow & derived state","text":"Example: Store items and query, then calculate visibleItems = items.filter(matchesQuery) during render. Do not store visibleItems and update it through an effect after every item or query change. That creates temporary inconsistency and extra work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b1b5e47132b8","heading":"Unidirectional data flow & derived state","text":"Use when: Designing form ownership, list filters, reducers, or shared stores. Choose one authoritative owner for each fact, and expose explicit change requests. See controlled component contracts and message design.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c4ef21f25ae0","heading":"Unidirectional data flow & derived state","text":"Benefits and tradeoffs: Predictable transitions and fewer synchronization bugs. Expensive derived calculations may need memoization or indexed computation; memoization is an optimization, not a new owner. A form draft intentionally diverges from a server snapshot and is a separate state concept.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a39db829933c","heading":"Unidirectional data flow & derived state","text":"When not to overengineer: A simple local interaction needs no store or action system. Native uncontrolled forms are valid. Two-way-binding frameworks can still have explicit ownership; the problem is ambiguous or duplicated ownership, not the presence of a binding API. Avoid using effects to synchronize values that can be derived directly.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-design","heading":"Message design: actions, commands, events & payloads","text":"Message design: actions, commands, events & payloads","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8810781e8509","heading":"Message design: actions, commands, events & payloads","text":"These are message-design concepts, not one formal design pattern. They appear in reducers, state machines, domain-driven design (DDD), and event-driven systems. The useful distinction is between intent and fact; the same JavaScript object shape can represent either.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-parts","heading":"Message design: actions, commands, events & payloads › What each part means","text":"What each part means","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2b59efe1fe8e","heading":"Message design: actions, commands, events & payloads › What each part means","text":"TermResponsibilityExample","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3f314a81d5c6","heading":"Message design: actions, commands, events & payloads › What each part means","text":"CommandRequests an operation. A handler validates it, checks permissions, and attempts the work. It can be rejected.CreateOrder: please create an order.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-651e1f0ae371","heading":"Message design: actions, commands, events & payloads › What each part means","text":"EventDescribes an occurrence. A domain event records a business fact; other consumers may react to it.OrderCreated: an order was successfully created.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-651c73ec82e7","heading":"Message design: actions, commands, events & payloads › What each part means","text":"ActionA message accepted by a state-management API. In Redux, a plain action is an object with a string type. Its meaning can be command-like or event-like.{ type: 'orders/orderCreated', payload: order } represents a fact as a Redux action.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-751135e2d9d9","heading":"Message design: actions, commands, events & payloads › What each part means","text":"PayloadThe data needed to process or understand a message, separate from its type and metadata. It is not an operation by itself.A creation command carries product ID and quantity; the resulting event carries the saved order and its assigned ID.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-695b56715fc1","heading":"Message design: actions, commands, events & payloads › What each part means","text":"Type and metadata: The type identifies what the message means. Optional metadata can carry a request ID, correlation ID, timestamp, or schema version. payload is a common convention, not a JavaScript requirement: useReducer accepts any action shape you design, and the state-machine example uses top-level fields. An action creator simply constructs an action; dispatch submits it to the store or reducer integration.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-flow","heading":"Message design: actions, commands, events & payloads › How they work together","text":"How they work together","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-340937592002","heading":"Message design: actions, commands, events & payloads › How they work together","text":"Create an order: intent → work → fact → UI state User submits the formThe UI constructs a CreateOrder command with productId and quantity as its payload. The command handler attempts the operationThe handler sends the request. The server validates input, authorizes access, and applies the business rules. Success produces a confirmed factThe server returns the saved order. The frontend represents that confirmation as an orders/orderCreated action whose payload is the order. The reducer updates the UI modelA pure state transition stores the confirmed order. React renders the confirmation UI. On rejection or network failure, report the failed attempt; do not claim OrderCreated. This example uses local action dispatch, not a message broker or durable domain-event publication.","kind":"Diagram"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-example","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Example: keep side effects outside the reducer","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-60490760e6fd","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"The example assumes one in-flight submission and starts with { status: 'idle', order: null, error: null }. The handler owns the asynchronous work; the reducer only derives state from the resulting actions.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-610adb883623","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"// Message design example: a command handler performs the side effect. async function handleCreateOrder(command, dispatch) { if (command.type !== 'CreateOrder') throw new Error('Unsupported command'); dispatch({ type: 'orders/submissionStarted' }); try { const response = await fetch('/api/orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(command.payload) }); if (!response.ok) throw new Error('Order could not be confirmed'); const order = await response.json(); // API returns the saved order. dispatch({ type: 'orders/orderCreated', payload: order }); } catch (error) { dispatch({ type: 'orders/submissionFailed', payload: { message: error.message } }); } } // A pure reducer consumes actions; it never performs the HTTP request. function orderReducer(state, action) { switch (action.type) { case 'orders/submissionStarted': return { ...state, status: 'submitting', error: null }; case 'orders/orderCreated': return { ...state, status: 'success', order: action.payload }; case 'orders/submissionFailed': return { ...state, status: 'error', error: action.payload.message }; default: return state; } } // From a submit handler; dispatch comes from useReducer or a Redux store. handleCreateOrder({ type: 'CreateOrder', payload: { productId: 'book-42', quantity: 1 } }, dispatch);","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9446cc781dae","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Command payload: The requested product and quantity express what the user wants. The server still validates them and derives trusted values such as price and ownership.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5001da5697e2","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Event-like action payload: The confirmed order represents what the server accepted. orders/orderCreated is both a Redux-style action and an event-like message; these categories are not mutually exclusive.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-015c3376ef04","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Failure semantics: A failed response means the client could not confirm success. A connection loss does not prove that the server did not create the order. Preserve the draft and use the idempotency and reconciliation policy before retrying.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fbaef9e1b7f1","heading":"Message design: actions, commands, events & payloads › Example: keep side effects outside the reducer","text":"Production integration: For shared server data, use the existing query-cache mutation lifecycle rather than maintaining a second copy in a reducer. The reducer here makes message roles visible; it is not a replacement data layer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-message-tradeoffs","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"When this distinction helps—and when to keep it simple","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c5dd2970a217","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Use it when asynchronous workflows have clear requested, pending, confirmed, and failed outcomes; when several consumers react to one fact; or when a state machine needs explicit transition inputs. Intent/fact naming makes debugging and responsibilities clearer. Tradeoff: Separate message types, handlers, and metadata add code and contracts to maintain. A local toggle may need only setOpen; a command does not require a command bus, and an event does not require a broker.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-03497a95e1df","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Naming: Commands usually use imperative names (CreateOrder); events use past tense (OrderCreated). Naming helps communicate intent but does not enforce correctness.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8d6684558f9a","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Delivery is a separate contract: Local dispatch is not durable publication or guaranteed delivery. Network events can be duplicated or missed; see real-time synchronization and recovery.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6d753faa614f","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Related architectures: CQRS separates commands (writes) from queries (reads); it does not inherently require separate databases or event sourcing. Event sourcing persists events as the source of truth. Dispatching event-like actions in React or Redux does not automatically implement either architecture.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2554ac54d309","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"React terminology: React Actions, such as form Actions and useActionState, are functions participating in an update workflow. They are distinct from the message objects discussed here.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-97befee1b2eb","heading":"Message design: actions, commands, events & payloads › When this distinction helps—and when to keep it simple","text":"Interview explanation: A command expresses intent, an event records an occurrence, an action is the state-management API’s message, and a payload carries the associated data. I perform side effects in a handler or data layer and keep the reducer pure. I choose explicit messages when they clarify a workflow, without introducing unnecessary messaging infrastructure.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-local-workflows","heading":"Model local workflows and valid transitions","text":"Model local workflows and valid transitions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-machines","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"State machines: model valid transitions","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-76440fc6a80c","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"A finite state machine (FSM) defines states, events, and permitted transitions. Its events describe transition inputs; see commands, events, and action messages for the naming distinction. This avoids contradictory boolean combinations such as isLoading and isSuccess both being true. A reducer can implement an FSM, but a reducer is not automatically a state machine.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-f9ca7bfb4310","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"type SearchState = | { status: 'idle' } | { status: 'loading'; requestId: number } | { status: 'success'; results: string[] } | { status: 'error'; message: string }; type SearchEvent = | { type: 'started'; requestId: number } | { type: 'resolved'; requestId: number; results: string[] } | { type: 'rejected'; requestId: number; message: string } | { type: 'reset' }; function searchReducer(state: SearchState, event: SearchEvent): SearchState { if (event.type === 'reset') return { status: 'idle' }; if (event.type === 'started') { return { status: 'loading', requestId: event.requestId }; } // Completion events only apply to the active request. if (state.status !== 'loading' || state.requestId !== event.requestId) { return state; } if (event.type === 'resolved') { return { status: 'success', results: event.results }; } return { status: 'error', message: event.message }; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-db2d6ee022ae","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"Discriminated unions make each state’s data explicit. The request-ID check is a transition guard that ignores stale completions. Start requests in an event handler or effect, then dispatch completion events; never fetch inside the reducer. Combine this with request cancellation to reduce wasted work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c02f0d0315c0","heading":"Model local workflows and valid transitions › State machines: model valid transitions","text":"Tradeoff: An explicit transition model helps async workflows and multi-step UI. For hierarchical states, parallel states, or complex effects, a dedicated state-machine library can be clearer than an expanding reducer. For a simple toggle, local useState is usually enough.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-state-pattern","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"State pattern vs. finite state machine vs. Strategy","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0554d3ff0883","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Purpose: The classic State pattern delegates state-dependent behavior to state-specific objects or functions. An FSM explicitly defines valid states and transitions; the State pattern is an implementation technique and does not by itself guarantee a complete transition model.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2fde00bb9409","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Example: An upload’s idle state accepts start; uploading accepts pause/cancel; completed accepts neither. For a few states, a discriminated union and reducer make these rules visible. State objects can help if each state owns substantial behavior, but do not trigger subscriptions or requests inside a React reducer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e7dbbbdc09da","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"Use when: Different lifecycle states permit different operations. Benefits: Replaces scattered state checks with localized behavior. Tradeoffs: More objects and indirection; transitions become difficult to audit if spread across implementations.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e028b0585dea","heading":"Model local workflows and valid transitions › State pattern vs. finite state machine vs. Strategy","text":"When not to use: Use a boolean for one independent toggle, a reducer for a modest explicit workflow, or a statechart library for hierarchical/parallel states and complex transitions. Strategy selects an algorithm independently of lifecycle; State selects behavior because the lifecycle changed.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-sharing","heading":"Share state through Context","text":"Share state through Context","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-131463f76ed8","heading":"Share state through Context","text":"Context distributes values; it does not define state transitions. useReducer centralizes transitions, while a provider makes state and operations available to a subtree. Keep local state local; introduce shared state only when multiple consumers need the same source of truth. Start with controlled vs. uncontrolled state ownership when designing a reusable component.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-reducer","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Context + useReducer: separate state, actions & dispatch","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d26ec75ce688","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"For hook selection and lazy initialization, see useState versus useReducer. A reducer is a pure function (state, action) => nextState. Return immutable updates and perform side effects outside it. Keep domain actions meaningful, such as itemAdded, rather than exposing arbitrary state mutation. The message-design example separates a command handler’s side effects from event-like actions consumed by a pure reducer.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e0753a753847","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"import { createContext, useContext, useReducer, useMemo, useCallback } from 'react'; const StateContext = createContext(undefined); const DispatchContext = createContext(undefined); const ActionsContext = createContext(undefined); function reducer(state, action) { switch (action.type) { case 'increment': return { count: state.count + 1 }; case 'reset': return { count: 0 }; default: throw new Error('Unknown action: ' + action.type); } } function CounterProvider({ children }) { const [state, dispatch] = useReducer(reducer, { count: 0 }); const increment = useCallback(() => dispatch({ type: 'increment' }), [dispatch]); const reset = useCallback(() => dispatch({ type: 'reset' }), [dispatch]); const actions = useMemo(() => ({ increment, reset }), [increment, reset]); return ( \u003cDispatchContext.Provider value={dispatch}> \u003cActionsContext.Provider value={actions}> \u003cStateContext.Provider value={state}> {children} \u003c/StateContext.Provider> \u003c/ActionsContext.Provider> \u003c/DispatchContext.Provider> ); } function useCounterState() { const state = useContext(StateContext); if (state === undefined) throw new Error('CounterProvider is required'); return state; } function useCounterActions() { const actions = useContext(ActionsContext); if (actions === undefined) throw new Error('CounterProvider is required'); return actions; } function useCounterDispatch() { const dispatch = useContext(DispatchContext); if (dispatch === undefined) throw new Error('CounterProvider is required'); return dispatch; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-75f9e074f181","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"State context: Read current data; these consumers update when the state value changes.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cb33382b2efa","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Actions context: Expose stable domain operations that hide action-object structure. A button that only calls increment() need not subscribe to count changes.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d9ffd551020c","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Dispatch context: Expose raw dispatch when consumers genuinely need it. React guarantees a stable dispatch identity. Often state plus actions or state plus dispatch is sufficient; three contexts are an option, not a requirement.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-44a60ffb92c0","heading":"Share state through Context › Context + useReducer: separate state, actions & dispatch","text":"Custom consumer hooks: Centralize provider checks and expose a domain API. A hook that reads state and then returns only actions still subscribes its caller to state; keep subscriptions separate.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-propagation","heading":"Share state through Context › Context propagation & referential stability","text":"Context propagation & referential stability","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-90284adf6d35","heading":"Share state through Context › Context propagation & referential stability","text":"React compares the provider’s previous and next value using Object.is. When it changes, consumers reading that context receive an update, even through React.memo. Reading only state.count from a large context does not create a property-level subscription.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-71de5b114281","heading":"Share state through Context › Context propagation & referential stability","text":"Referential stability: An object literal or inline function creates a new reference on each render. A provider using value={{ state, dispatch }} therefore changes identity whenever that object is recreated.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cca0e8e5e9c5","heading":"Share state through Context › Context propagation & referential stability","text":"Stable values: useMemo stabilizes a wrapper object when its dependencies are unchanged; useCallback stabilizes a function. Include all reactive dependencies to avoid stale closures. A callback that depends on changing state must change unless it is restructured safely.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e983a3fd42e4","heading":"Share state through Context › Context propagation & referential stability","text":"Why separation helps: Stable action/dispatch contexts do not broadcast state changes to action-only consumers. Splitting unrelated state domains also reduces the subscription scope.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8e2024bf0aae","heading":"Share state through Context › Context propagation & referential stability","text":"What separation cannot guarantee: Consumers can still render because their own state or props changed, or their ancestor rendered. Context separation removes a particular update source; it does not block ordinary parent-driven rendering. Use the React render analysis workflow to verify the result.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-selectors","heading":"Share state through Context › Context selectors & subscription granularity","text":"Context selectors & subscription granularity","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-159790a373b5","heading":"Share state through Context › Context selectors & subscription granularity","text":"A selector derives the slice a consumer needs. Native useContext does not subscribe selectively: a custom hook returning useContext(Context).count still subscribes to the entire context value.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e7f8d3701626","heading":"Share state through Context › Context selectors & subscription granularity","text":"use-context-selector is a third-party library that supports selected-value subscriptions. Create the context using the library’s createContext, then consume it with its selector hook:","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-771f9f945c9d","heading":"Share state through Context › Context selectors & subscription granularity","text":"import { createContext, useContextSelector } from 'use-context-selector'; // Alternative to the native StateContext in the earlier example. const SelectableStateContext = createContext({ count: 0, query: '' }); function CountLabel() { const count = useContextSelector(SelectableStateContext, state => state.count); return \u003cspan>{count}\u003c/span>; }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0680cc6ff0ef","heading":"Share state through Context › Context selectors & subscription granularity","text":"A query-only update need not trigger a selector subscription update when the selected count remains equal. Selectors should be pure and return referentially stable results for unchanged inputs; returning a fresh object defeats this optimization. Parent-driven renders remain possible. For frequent updates or complex subscriptions, consider an external store with selector support and React’s useSyncExternalStore integration. See Observer and external-store contracts for snapshots, ownership, and tradeoffs.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-observer","heading":"Observer, publish–subscribe & external stores","text":"Observer, publish–subscribe & external stores","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-a611de5360fb","heading":"Observer, publish–subscribe & external stores","text":"Purpose: Notify consumers when a producer changes without hard-coding all consumers into its update logic. Observer usually means subscribing directly to a subject. Publish–subscribe introduces a topic/channel or broker between publishers and subscribers; terminology varies, so describe the actual topology.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6e4b61377f5c","heading":"Observer, publish–subscribe & external stores","text":"Examples: A store maintains listeners through subscribe(listener) and returns an unsubscribe function. A local event bus publishes cart/itemAdded to independent analytics and notification consumers. Network pub/sub adds serialization, authorization, and delivery/recovery concerns; a local bus does not supply those guarantees.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-419f8a00c414","heading":"Observer, publish–subscribe & external stores","text":"Use when: Several independent consumers react to a change, or an external data source needs React subscriptions. For shared state, keep a source-of-truth store and expose snapshots; use notifications to announce changes, not as the only record of current state.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c4cfa017f88b","heading":"Observer, publish–subscribe & external stores","text":"React integration: useSyncExternalStore connects a subscription and a stable snapshot reader to React. Return an immutable cached snapshot while data is unchanged, subscribe with an unsubscribe contract, and provide an appropriate server snapshot for SSR. Use selector-capable integrations for slice subscriptions; returning a new object on every snapshot read can cause repeated rendering. React’s protocol helps prevent tearing—components displaying inconsistent versions of the same external store.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3c32ee56eee1","heading":"Observer, publish–subscribe & external stores","text":"Benefits and tradeoffs: Decouples producers from consumers, but hidden subscriptions obscure execution order and resource ownership. A listener failure or synchronous reentrant publication needs a defined policy; an event bus is not a transaction. Unsubscribe on disposal and bound buffered work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-9eff84cad0bf","heading":"Observer, publish–subscribe & external stores","text":"When not to use: Prefer props/callbacks for a parent–child interaction, Context for scoped value distribution, and a query cache for server state. Avoid using a global event bus to coordinate a workflow whose steps and errors should be explicit in one handler. Unlike events, commands represent work that needs a responsible handler.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0a2aecf051bd","heading":"Observer, publish–subscribe & external stores","text":"Compare: Native Context subscribes consumers to provider value changes; selectors or external stores can provide finer granularity. Browser observers are specialized platform subscriptions, not general state stores; see Intersection Observer. See resource ownership for cleanup and WebSockets/SSE for remote delivery.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-remote-data","heading":"Synchronize remote data and local drafts","text":"Synchronize remote data and local drafts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-query-lifecycle","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Server-state lifecycle: read → mutate → reconcile","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-23483bfd5fb4","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Identify the resource: A query key includes the resource and every input that affects its result, including relevant tenant/user scope and filters. Keys identify cached representations; they are not authorization checks.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fc7b47b5c7ee","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Define freshness: In TanStack Query v5, staleTime describes how long cached data is considered fresh. Stale does not mean deleted: it may be displayed while eligible triggers refetch. gcTime controls retention after the query becomes inactive; it is a separate concern.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-211fd6da0266","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Perform a mutation: Send the command to the server and expose pending/error UI. For confirmation-first behavior, keep the old value until success; for speculative behavior, follow the optimistic UI contract.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-eb1be615add9","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Reconcile the cache: Write a complete authoritative response into its detail entry, or invalidate affected query keys. Invalidation marks matching queries stale and normally refetches active matches; it does not discover related lists automatically or fetch every inactive entry immediately.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e588d1600e88","heading":"Synchronize remote data and local drafts › Server-state lifecycle: read → mutate → reconcile","text":"Handle identity and concurrency: Clear/scope sensitive caches when sessions change. Guard obsolete responses; overlapping writes may need version checks or a conflict policy on the server. A stale-time setting is not a distributed consistency guarantee.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-implementation","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Implementation: local UI state + a remote query cache","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0e68f248628e","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"This client-rendered example uses TanStack Query v5. It keeps the panel’s expanded state local and the product in one shared query cache. It assumes the API handles authentication, authorization, input validation, and applicable CSRF defenses; the cache does not replace those checks.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3624d3b18291","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"// Client-side React application; TanStack Query v5. import { useState } from 'react'; import { QueryClient, QueryClientProvider, useQuery, useMutation, useQueryClient } from '@tanstack/react-query'; const queryClient = new QueryClient(); // One stable cache for this client app. async function readJson(response) { if (!response.ok) throw new Error('HTTP ' + response.status); return response.json(); } function ProductPanel({ tenantId, productId }) { const [expanded, setExpanded] = useState(false); // Client state. const cache = useQueryClient(); const key = ['product', tenantId, productId]; const url = '/api/tenants/' + encodeURIComponent(tenantId) + '/products/' + encodeURIComponent(productId); const product = useQuery({ queryKey: key, queryFn: ({ signal }) => fetch(url, { signal }).then(readJson), staleTime: 30_000 }); const favorite = useMutation({ mutationFn: nextValue => fetch(url + '/favorite', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ favorite: nextValue }) }).then(readJson), // API returns the complete, confirmed product. onMutate: () => cache.cancelQueries({ queryKey: key, exact: true }), onSuccess: saved => { cache.setQueryData(key, saved); return cache.invalidateQueries({ queryKey: ['products', tenantId] }); } }); if (product.isPending) return \u003cp role=\"status\">Loading product…\u003c/p>; if (product.isError && !product.data) return \u003cp role=\"alert\">Cannot load product.\u003c/p>; return ( \u003csection> \u003ch2>{product.data.name}\u003c/h2> \u003cbutton aria-expanded={expanded} onClick={() => setExpanded(open => !open)}> {expanded ? 'Hide details' : 'Show details'} \u003c/button> {expanded && \u003cp>{product.data.description}\u003c/p>} \u003cbutton disabled={favorite.isPending} onClick={() => favorite.mutate(!product.data.favorite)}> {favorite.isPending ? 'Saving…' : product.data.favorite ? 'Unfavorite' : 'Favorite'} \u003c/button> {favorite.isError && \u003cp role=\"alert\">Change failed. Please retry.\u003c/p>} \u003c/section> ); } function App() { // In a real app these come from validated session and route data. return ( \u003cQueryClientProvider client={queryClient}> \u003cProductPanel tenantId=\"acme\" productId=\"42\" /> \u003c/QueryClientProvider> ); }","kind":"Code"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-8626af223757","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Client ownership: expanded belongs only to this panel; it does not need to travel through the server or global Context.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c749f6f29aee","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Server ownership: product.data stays in the query cache. The query key isolates this tenant/resource representation; staleTime is an explicit freshness choice, not a universal recommendation.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-45c1c2c53b7f","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Cancellation: The query function consumes the provided AbortSignal. Before the mutation starts, cancelQueries stops an older detail fetch from overwriting the confirmed result later.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-06ec25a2cfba","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Mutation reconciliation: Success updates the detail entry and invalidates separately keyed product lists. Returning the invalidation Promise keeps the mutation pending through that step. Other related keys still need an explicit policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-57ec0837ee60","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Cache lifetime: A module-level client is suitable for this single client app. For SSR, create/isolate caches per request and follow the framework’s dehydration/hydration integration; never share personalized request data through a process-global cache.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-72d18053590c","heading":"Synchronize remote data and local drafts › Implementation: local UI state + a remote query cache","text":"Failure handling: Initial read failures and mutation failures have separate UI. A full product should also surface background-refresh failures without unnecessarily discarding already-visible data.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-form-drafts","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Forms: server snapshot + client-owned draft","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ee25ccc5a508","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"A fetched profile is server state; editing its name creates a client-owned draft. Initializing a draft from fetched data can be intentional. Blindly copying every refetch into the form with an effect can overwrite unsaved edits.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ccb95a95c73a","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Initialize deliberately: Mount the editor after the resource loads. Key it by resource identity if changing records should reset the draft. Changing the key on every server version would also discard edits, so only do that under an explicit reset policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-640e6e93d6dd","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Handle remote changes: Track dirty fields. Keep edits, offer reload/reset, or merge untouched fields when a background update arrives; do not silently replace dirty values.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-48970b226fdf","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"Save and reconcile: Submit the draft, handle validation/conflict errors, update or invalidate the server cache, and reset the draft to the accepted response if that is the intended UX. For conflicting edits, use the server version/ETag precondition and conflict policy.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-480fb6f9d856","heading":"Synchronize remote data and local drafts › Forms: server snapshot + client-owned draft","text":"GraphQL changes the request/schema contract, not server-state ownership. See normalized caches and mutation reconciliation for the GraphQL client choices.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-mutation-conflicts","heading":"Optimistic updates & concurrent mutation conflicts","text":"Optimistic updates & concurrent mutation conflicts","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-2a684abeaf54","heading":"Optimistic updates & concurrent mutation conflicts","text":"An optimistic update displays the expected result before the server confirms it. It improves perceived responsiveness for reversible, predictable operations such as a favorite toggle. For payments, scarce inventory, or ambiguous outcomes, prefer a pending state and authoritative confirmation. useOptimistic models temporary UI; a query-cache mutation lifecycle coordinates shared remote data.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b087223b617f","heading":"Optimistic updates & concurrent mutation conflicts","text":"Prepare: Cancel obsolete reads where supported; record the affected entity, mutation ID, and base version. Save a snapshot only if rollback cannot erase newer work.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-b2c267557a9c","heading":"Optimistic updates & concurrent mutation conflicts","text":"Apply: Display the pending change, ideally as an overlay of pending operations on a confirmed snapshot. Keep the list and detail representations consistent or invalidate them deliberately.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-627611baeb43","heading":"Optimistic updates & concurrent mutation conflicts","text":"Confirm or reject: Replace pending values with the authoritative response on success. On failure, remove only that operation’s optimistic change and show a recovery action. Reconcile affected queries after pending operations settle.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-concurrent-mutations","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Why simple rollback breaks with overlapping writes","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-fe2ca21dac94","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Example: Mutation A optimistically sets a name to “Ada”; B then sets it to “Grace.” If A fails and restores its entire old snapshot, it erases B’s newer change. Similarly, an older success response may arrive last and overwrite newer UI. Response arrival order is not business ordering.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6b761c3a84f9","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Serialize or disable per entity: Simplest when users do not need overlapping writes. The existing favorite example disables its button while saving. Other tabs or users can still write concurrently.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ebd59c971449","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Track pending operations: Assign mutation IDs and derive the display from confirmed data plus remaining operations. A “latest request” guard protects local display ordering, but does not undo writes already accepted by the server.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-c83a686ad489","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Optimistic concurrency control: Send a base version or an If-Match precondition with the resource’s ETag. The server checks and writes atomically; failed preconditions produce 412 Precondition Failed, while application conflicts may use 409 Conflict. Refetch and offer merge/retry rather than silently overwriting.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-750f1f2c33a4","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Retry safely: For supported operations, reuse an idempotency key for retries of the same logical command. This avoids duplicate effects; it does not resolve two different commands editing the same resource.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e4db6938c804","heading":"Optimistic updates & concurrent mutation conflicts › Why simple rollback breaks with overlapping writes","text":"Form connection: Keep the user’s dirty draft separate from the confirmed snapshot and show a conflict explicitly; follow the draft reconciliation policy and submission contract.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-occ-choice","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Choosing optimistic concurrency control","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-cec7b51a81a0","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Problem: Two editors read version 7 and submit different changes. Without a precondition, the later write may silently overwrite the first. With optimistic concurrency control (OCC), each write includes the version it read; the server atomically updates only if that version is still current.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-e162942f55f3","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Example: Read a profile with ETag \"v7\", then send If-Match: \"v7\" with PATCH. After another write advances it to v8, the stale request receives 412. Preserve the local draft, load the latest version, and offer a merge or explicit retry. Use a strong validator for If-Match; server-side compare-and-update must be atomic.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-52e9b17a30b3","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Use when: Conflicts are infrequent and users can resolve them. Benefits: No lock held during human editing; conflicts are explicit. Tradeoffs: Requires versions and recovery UX. Frequent conflicts may make repeated retries unproductive.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-3004f0d85197","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Alternatives: A short database transaction with pessimistic locking can coordinate tightly contested server operations; avoid holding a lock across a human editing session. Atomic domain operations such as increment can avoid unnecessary read-modify-write conflicts. Last-write-wins is acceptable only when intentional data loss is harmless; collaborative merging may need specialized algorithms. UI serialization controls one client, not other users.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-05f4986c46fe","heading":"Optimistic updates & concurrent mutation conflicts › Choosing optimistic concurrency control","text":"Distinction: OCC prevents stale writes; an optimistic UI predicts an outcome; an idempotency key deduplicates retries of one logical operation. They solve different problems and can be used together. See migration compatibility when versions span old and new clients.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-realtime","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Real-time updates: WebSockets vs. Server-Sent Events","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-775c26429f3a","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Real-time messages deliver changes to server-owned data; they do not create a second source of truth. Feed them into the same query cache or normalized store used by ordinary reads and mutations.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ab31684bb3ae","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"TransportUse whenTradeoffs","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-eee325f9ecca","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"WebSocketBidirectional traffic: chat, collaborative interactions, or frequent client commands.Persistent connection; implement reconnect, heartbeat, resubscription, and application recovery. The classic browser API has no built-in backpressure.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-bfcde3db5950","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"SSE / EventSourceServer-to-client notifications, progress, feeds; send commands through ordinary HTTP.Text event stream over HTTP with automatic reconnect. Event IDs enable resumption only if the server supports replay. Native EventSource cannot set arbitrary Authorization headers.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-963628663c41","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"PollingUpdates are infrequent or operational simplicity matters more than immediate delivery.Simple recovery but repeated requests and freshness delay. Consider visibility-aware polling and conditional reads.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-853bbf88307e","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Own the lifecycle: Subscribe in an effect or shared data service and close connections on teardown, resource changes, or logout. Avoid a separate connection per row. See effect synchronization.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-5cf80825fe1c","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Merge safely: Validate message shape, resource identity, and version. Ignore duplicate or older versions. Apply complete authoritative data or invalidate and refetch when a delta cannot be applied safely; coordinate events with pending optimistic operations.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-ba203f5b935d","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Recover gaps: Reconnect does not guarantee missed events are delivered. Use event IDs/sequence numbers and server replay, or refetch a snapshot before resuming. Bound queued messages and coalesce updates when consumers fall behind.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-0f9739c79b70","heading":"Real-time updates: WebSockets vs. Server-Sent Events","text":"Secure the channel: Authenticate connections and authorize every subscription/resource. Validate WebSocket origins; apply appropriate CORS/credential rules to SSE. Handle session expiry and close subscriptions on logout.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-review","heading":"Interview review","text":"Interview review","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"state-interview-answer","heading":"Interview review › Interview-ready distinction","text":"Interview-ready distinction","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-6a51745f7c62","heading":"Interview review › Interview-ready distinction","text":"I classify state by its authoritative owner before choosing a library. UI state stays local or in a shared client store when needed; remote data is a cached server snapshot with explicit freshness and mutation-reconciliation policies. A form can contain both. Context distributes values, but does not replace a query cache, and Server versus Client Components is a separate execution decision.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-868801fac560","heading":"Interview review › Interview-ready distinction","text":"Related concepts: HTTP and application caching · Form Actions · External-store subscriptions · Authorization and cache isolation · TanStack Query defaults.","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"context-review","heading":"Interview review › Interview-ready design rationale","text":"Interview-ready design rationale","kind":"Notes"},{"page":"context-state.html","topic":"State Ownership, Context & Data","anchor":"search-d8efade12efa","heading":"Interview review › Interview-ready design rationale","text":"I make state ownership and valid transitions explicit before choosing a sharing mechanism. For a shared workflow, I can use a pure reducer with Context, separate data subscriptions from stable operations, and expose custom hooks. I know that native context broadcasts value changes to all its consumers, so I use domain separation or selectors when profiling shows a need for finer subscriptions. For asynchronous workflows, I model explicit states and guard stale transitions rather than managing loosely related booleans.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-title","heading":"","text":"Frontend Performance Optimization","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-01fc3e82f3b6","heading":"","text":"Start with a measured symptom. Understand the browser pipeline, isolate React-specific work, then choose a targeted technique and verify its impact.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c7fa282677cf","heading":"","text":"Start with a user-visible problem, measure its cause, then verify the improvement. A smaller bundle or fewer React renders matters when it improves loading, responsiveness, stability, or resource use. Optimize the critical path rather than an isolated number.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-480d5c172b10","heading":"","text":"Measuring performance","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8e6249784042","heading":"","text":"Browser rendering pipeline","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8a59bc6288d1","heading":"","text":"Diagnosing unnecessary React renders","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e3957012b228","heading":"","text":"Optimization techniques: purpose and tradeoffs","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-a2760d0bb23e","heading":"","text":"Interview-ready investigation","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-measurement","heading":"Measuring performance","text":"Measuring performance","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-bb3f379f4348","heading":"Measuring performance › Choose the right measurement tool","text":"Choose the right measurement tool","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8125429d9f08","heading":"Measuring performance › Choose the right measurement tool","text":"React DevTools Profiler: Record an interaction to find expensive component renders and commits. Use its flamegraph, ranked view, and render-reason information where available. React render work is not the same as browser layout or paint; use a browser trace for those costs.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-59887f092003","heading":"Measuring performance › Choose the right measurement tool","text":"Chrome DevTools Performance panel: Record a reproducible user journey. Inspect the main-thread flame chart, interaction timings, JavaScript call stacks, style recalculation, layout, paint, and dropped frames. Bottom-up groups accumulated cost by function; Call tree shows how execution reached it.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-72d89da2ce6a","heading":"Measuring performance › Choose the right measurement tool","text":"Chrome DevTools Network & Coverage: Find request waterfalls, large transfers, cache behavior, and unused JavaScript or CSS in the recorded journey. Unused code on one screen may still be required elsewhere.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-0d76a91b745c","heading":"Measuring performance › Choose the right measurement tool","text":"Lighthouse: A repeatable synthetic (lab) audit for loading and diagnostics under configured conditions. Its score is a signal, not a complete account of real-user experience. Total Blocking Time (TBT) is a lab responsiveness metric; it is not INP.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e8031096d61d","heading":"Measuring performance › Choose the right measurement tool","text":"Real User Monitoring (RUM): Measure production users across devices, networks, and routes. Compare field data with lab traces to understand who is affected and reproduce their bottleneck. Chrome UX Report (CrUX) offers aggregated field data for eligible pages and origins.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-19d224a2371e","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"Core Web Vitals: the user-facing outcomes","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-1051dd4fd8fb","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"MetricWhat it measuresGood thresholdTypical investigation","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-86374ea24160","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"LCP · Largest Contentful PaintWhen the largest eligible image or text block in the viewport is rendered.≤ 2.5 secondsServer response time, resource discovery, image loading, render-blocking CSS.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-5edc11615fcc","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"INP · Interaction to Next PaintResponsiveness across click, tap, and keyboard interactions; reports a near-worst interaction, with outliers handled according to interaction count.≤ 200 millisecondsInput delay, event-handler processing, and presentation delay before the next paint.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-30a044a0297c","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"CLS · Cumulative Layout ShiftThe largest session-window score of unexpected layout shifts; a unitless measure of visual instability.≤ 0.1Images without reserved dimensions, inserted content, and font swaps.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-de3b66640e19","heading":"Measuring performance › Core Web Vitals: the user-facing outcomes","text":"Evaluate at the 75th percentile of page visits, segmented by mobile and desktop. Use additional percentiles and device or route segments to diagnose affected groups. A fast developer laptop can hide problems on slower devices.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c8e4e0cebea3","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Measure JavaScript execution and rendering bottlenecks","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-b3d7116aaeb1","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Self time vs. total time: Self time belongs to the function itself; total time includes functions it calls. Inspect both to avoid blaming a cheap wrapper for expensive descendants.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-f74dbd49d4c5","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Long tasks: Main-thread tasks longer than 50 ms can delay input and rendering. Split work into smaller tasks and yield to the browser; move suitable CPU-intensive computations to a Web Worker, which cannot access the DOM directly.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-03a88a1dd6af","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"User Timing API: Use performance.mark() and performance.measure() to label application work in a trace. Elapsed time across an await includes waiting; it is not necessarily JavaScript CPU time.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c16af6191714","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"Frame budget: A 60 Hz display refreshes about every 16.7 ms; at 120 Hz, about every 8.3 ms. JavaScript shares that time with rendering and browser overhead, so it cannot consume the full interval.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-2081ec7c1bca","heading":"Measuring performance › Measure JavaScript execution and rendering bottlenecks","text":"performance.mark('filter-start'); const results = expensiveFilter(products, query); performance.mark('filter-end'); performance.measure('product-filter', 'filter-start', 'filter-end');","kind":"Code"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-browser","heading":"Browser rendering pipeline","text":"Browser rendering pipeline","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-4b67bdd8ad5c","heading":"Browser rendering pipeline","text":"Browser rendering: from document to frameHTML parsingConstruct the DOM: document structure and content.CSS parsingConstruct the CSSOM: parsed style rules.Style calculationResolve selectors, cascade, and inheritance into computed styles.Render treeCombine renderable content with its styles.LayoutCalculate box sizes and positions.PaintProduce drawing instructions for visual content.RasterizationConvert drawing instructions into pixels, commonly in tiles.CompositingCombine rasterized layers into the final frame.DOM and CSSOM construction feed style calculation and render-tree construction. Browsers work incrementally; an update can reuse results and skip stages.","kind":"Diagram"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-91a8d0a3b576","heading":"Browser rendering pipeline","text":"This is a conceptual model: browsers perform work incrementally, and an update may skip stages when earlier results remain valid.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-811da15674e8","heading":"Browser rendering pipeline","text":"DOM (Document Object Model): The parsed document tree. JavaScript can add, remove, or update its nodes.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9713fcf6893d","heading":"Browser rendering pipeline","text":"CSSOM (CSS Object Model) & style calculation: The browser parses CSS rules and resolves the cascade, inheritance, and selectors into computed styles for elements. CSS can block initial rendering; synchronous scripts can block HTML parsing.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-504fcd16be1a","heading":"Browser rendering pipeline","text":"Render tree: Combines renderable content with its styles. It differs from the DOM; for example, display: none elements produce no layout boxes.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8ac25136a670","heading":"Browser rendering pipeline","text":"Layout (reflow): Calculates box sizes and positions. Changing geometry, such as width or font size, can invalidate layout for the element and related content.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-6af7e571c297","heading":"Browser rendering pipeline","text":"Paint: Produces drawing instructions for backgrounds, text, borders, and other visual content. Repaint means regenerating affected visual output; changing a color typically needs paint without layout.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-12e3608d05d7","heading":"Browser rendering pipeline","text":"Rasterization: Converts drawing instructions into pixels, commonly in tiles.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-799e2011a90f","heading":"Browser rendering pipeline","text":"Compositing: Combines rasterized layers into the final frame. Animating transform or opacity on a suitable composited layer can avoid layout and paint. Layer promotion is browser-dependent; excessive layers consume memory.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-7e571088a890","heading":"Browser rendering pipeline","text":"Reflow vs. repaint: Reflow changes geometry; repaint changes appearance. A layout change usually leads to paint for affected content, but a paint-only change need not recalculate layout. Neither is the same as a React re-render.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-layout-thrashing","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Layout thrashing: alternating DOM writes and geometry reads","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9cc2fb5ed135","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Forced synchronous layout occurs when JavaScript reads geometry after a change has invalidated layout, forcing the browser to calculate it immediately. Repeating this write/read cycle is layout thrashing.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-db61862e10b8","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"// Avoid: each width update can invalidate the next geometry read. for (const row of rows) { row.style.width = container.offsetWidth + 'px'; } // Prefer: batch the read before the writes. const width = container.offsetWidth; for (const row of rows) { row.style.width = width + 'px'; }","kind":"Code"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-d291f090f0d2","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Recognize geometry reads: offsetWidth, offsetHeight, and getBoundingClientRect() may require up-to-date layout. A read is not automatically expensive; pending invalidation determines whether it forces work.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-d9e94a8d3a7c","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Batch DOM reads before writes when the algorithm permits. Prefer CSS layout rules when they can express the relationship directly.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-66c3771317fc","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Use requestAnimationFrame() to schedule visual updates before a repaint. It does not prevent forced layout if the callback still alternates writes and reads.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-75c2c7ac0fb3","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"Reduce affected work: Large DOM trees and broad style invalidation increase cost. Consider virtualization, CSS containment, or content-visibility for suitable offscreen sections; verify layout, accessibility, and find-in-page behavior.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-4842894c1ccb","heading":"Browser rendering pipeline › Layout thrashing: alternating DOM writes and geometry reads","text":"DOM operations are not equally expensive: The cost depends on which styles and layout boxes become invalid. Many writes can be batched by the browser; one badly timed geometry read can force that pending work onto the critical path.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-react","heading":"Diagnosing unnecessary React renders","text":"Diagnosing unnecessary React renders","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-b2259a0a285d","heading":"Diagnosing unnecessary React renders","text":"A component can render because its state changes, an ancestor renders, or a consumed context changes. A render does not imply a DOM mutation or repaint. First identify which renders are expensive and whether they affect the interaction.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e58cc2e3cb60","heading":"Diagnosing unnecessary React renders","text":"Record the interaction in React Profiler and find the expensive commits and components.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-a96641d780b6","heading":"Diagnosing unnecessary React renders","text":"Inspect the trigger: Look for state placed too high in the tree, broad context updates, unstable object/function props, or effects that repeatedly update state.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-2480f02ff3c4","heading":"Diagnosing unnecessary React renders","text":"Reduce the scope of updates: Colocate state with its consumers, split unrelated context values, and avoid storing derived values in state when they can be calculated during rendering.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-7428f32d3dcf","heading":"Diagnosing unnecessary React renders","text":"Apply memoization selectively: Use the techniques below when unchanged inputs can skip meaningful work; profile again to confirm the benefit.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-f64797dadb43","heading":"Diagnosing unnecessary React renders","text":"Measurement caveat: Development-mode StrictMode can invoke rendering and effect setup/cleanup extra times to expose bugs. Validate user-facing performance in a representative production build; React profiling itself may require a profiling-enabled build and adds overhead.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-techniques","heading":"Optimization techniques: purpose and tradeoffs","text":"Optimization techniques: purpose and tradeoffs","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-f621a6ca7c12","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Control frequency and repeated computation","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-debounce","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Debouncing: Run after a quiet interval, resetting the timer on each input. Example: fetch search suggestions 250 ms after typing stops. It reduces calls but adds latency; cancel pending timers on cleanup.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-743bfb246525","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Throttling: Limit execution frequency during continuous activity. Example: update scroll analytics at most once every 200 ms. Choose leading-edge and/or trailing-edge behavior deliberately so the final update is handled.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-memoization","heading":"Optimization techniques: purpose and tradeoffs › Control frequency and repeated computation","text":"Memoization: Reuse a result when its inputs are unchanged. useMemo caches a calculation, useCallback caches a function identity, and React.memo can skip a component render when props compare equal. Default comparisons use Object.is for dependencies or individual props. State/context updates still render memoized components. See hook cache guarantees and React Compiler. Memoization costs memory and comparison work; unstable dependencies or cheap calculations may erase its value.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8afa02f762ed","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Reduce initial loading and rendering work","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-0e807186293b","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Code splitting: Divide JavaScript into independently loadable chunks, often by route or feature, using dynamic import(). This reduces initial download, parsing, and execution work when chunks are deferred. Excessive splitting can create request waterfalls.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-lazy-loading","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Lazy loading: Defer a resource until it is needed. Use React.lazy with Suspense for supported component loading, or loading=\"lazy\" for offscreen images. Reserve image dimensions to avoid CLS; do not lazy-load the likely LCP image. For visibility-triggered custom loading, see Intersection Observer. Code splitting creates chunks; lazy loading decides when to request them. See Streaming SSR and Suspense for progressive server delivery.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-virtualization","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Virtualization (windowing): Mount only visible list items plus a small overscan region. This reduces DOM size, React work, and layout cost. Account for variable row heights, keyboard focus, screen-reader navigation, and browser search. Resize Observer can measure variable row heights.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-238f726029da","heading":"Optimization techniques: purpose and tradeoffs › Reduce initial loading and rendering work","text":"Pagination: Limit the data fetched per page. Cursor-based pagination is often useful for large or changing datasets; offset-based pagination is simpler for page-number navigation. Pagination reduces data volume; virtualization reduces mounted UI. They can be combined.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c00eb918f6a6","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Reduce network work and prevent stale results","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-caching","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Caching: Reuse responses or computed data. HTTP caching uses Cache-Control; validators such as ETag support conditional requests and revalidation. Application query caches reuse server state across components; see query keys, freshness, and mutation invalidation. Define freshness, invalidation, and user-specific cache keys; personalized responses must not leak through shared caches.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9859bbf3979a","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Request cancellation: Stop obsolete asynchronous work to reduce wasted processing and prevent stale results. See AbortController & AbortSignal for the mechanism, React cleanup example, and correctness limits.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-deduplication","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Request deduplication: Share one in-flight request among consumers of the same query key. Caching reuses completed results; deduplication shares pending work. Include all result-affecting parameters and the relevant user/tenant scope in the key.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-c98a4975c872","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"Example: a slow product search. Debounce typing to reduce requests, cancel or ignore obsolete searches to prevent stale results, deduplicate identical in-flight queries, and cache reusable results. If the result list itself is expensive, paginate the data and virtualize the rows. Use the trace to decide which of these is actually needed.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-d3e290f45d2d","heading":"Optimization techniques: purpose and tradeoffs › Reduce network work and prevent stale results","text":"For the protocol details behind cache and bundle optimizations, see HTTP freshness and validators and tree shaking and module side effects.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"performance-review","heading":"Interview-ready investigation","text":"Interview-ready investigation","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-b3cc615e2ff2","heading":"Interview-ready investigation","text":"Define the symptom and target: Is loading slow, typing delayed, scrolling janky, or content shifting? Choose the relevant metric and affected user segment.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e0285992fa17","heading":"Interview-ready investigation","text":"Capture a baseline: Reproduce the same journey with representative data, device constraints, and explicitly cold or warm caches. Use field data to check how widespread it is.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9dd63679a184","heading":"Interview-ready investigation","text":"Identify the dominant bottleneck: Network, JavaScript, React rendering, layout, paint, or a combination. Follow the critical path and call stacks rather than guessing.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-9cbc07fb8d85","heading":"Interview-ready investigation","text":"Make a targeted change and remeasure: Compare repeated runs under equivalent conditions, then check production percentiles. Watch for regressions in memory, accessibility, data freshness, and other metrics.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-8f7b27a48c1a","heading":"Interview-ready investigation","text":"Prevent recurrence: Establish performance budgets for important journeys and asset sizes, and monitor regressions in CI and production.","kind":"Notes"},{"page":"frontend-performance.html","topic":"Frontend Performance Optimization","anchor":"search-e2525eb826fa","heading":"Interview-ready investigation","text":"I begin with the user-visible symptom and a representative baseline. I combine field metrics with Chrome performance traces, using React Profiler when component rendering is implicated. I separate JavaScript execution, React render work, and browser layout and paint, then address the largest cost on the critical path. I validate the result under the same conditions and monitor production percentiles, rather than assuming fewer renders or a higher audit score means a better experience.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"graphql-title","heading":"","text":"GraphQL","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-c300ecd6f453","heading":"","text":"Understand the schema-to-resolver execution model, client data ownership, failure semantics, and when REST is the simpler choice.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-04d9a796de1b","heading":"","text":"What GraphQL solves—and what it does not","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-648224e2e827","heading":"","text":"Schema, types & operation documents","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-37567d4d800c","heading":"","text":"How a GraphQL request executes","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-43a6729734b0","heading":"","text":"Resolvers, context & N+1 prevention","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-4722cd13207f","heading":"","text":"Queries, mutations & subscriptions","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-d5d597e33ddd","heading":"","text":"Nullability, partial data & errors","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-ee2968f64ccb","heading":"","text":"Client caching, identity & mutation reconciliation","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-e35ab68ca065","heading":"","text":"Schema evolution, generated types & query safety","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-ae260ba631fd","heading":"","text":"GraphQL vs. REST: choose by the client and operating cost","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-purpose","heading":"What GraphQL solves—and what it does not","text":"What GraphQL solves—and what it does not","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-purpose-definition","heading":"What GraphQL solves—and what it does not","text":"GraphQL is a query language and execution model for a typed API. Clients select fields from a server-defined schema; the server validates and executes the selection and returns a correspondingly shaped result. It is not a database, ORM, transport protocol, or replacement for authorization.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-70b773c3b56e","heading":"What GraphQL solves—and what it does not","text":"Problem: Different screens need different combinations of related data. Fixed endpoint representations may over-fetch unused fields or require several client requests. GraphQL exposes a composable schema so a client can request a tailored view of those relationships.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-b523de7f0b17","heading":"What GraphQL solves—and what it does not","text":"Example: A product page requests product name plus seller name, while checkout requests price and availability. The schema can serve both without a new endpoint per view. One operation can still trigger many backend calls; a small response is not proof of a cheap query.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-972d9407f9b4","heading":"What GraphQL solves—and what it does not","text":"Use: Multiple clients with evolving, relationship-rich views and teams able to own schema governance and execution cost. For a few stable resource operations, REST is often simpler. A BFF can aggregate data using REST or GraphQL; these are separate choices.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-schema","heading":"Schema, types & operation documents","text":"Schema, types & operation documents","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-schema-definition","heading":"Schema, types & operation documents","text":"The schema defines available fields and types. An operation document selects fields, passes arguments, and names the requested work. Variables provide typed values separately from the document; fragments reuse field selections; aliases rename result keys or request a field with different arguments.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-4ee236117d94","heading":"Schema, types & operation documents","text":"type Query { product(id: ID!): Product } type Product { id: ID! name: String! priceMinor: Int! seller: Seller! } type Seller { id: ID! name: String! }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-2cf524688419","heading":"Schema, types & operation documents","text":"query ProductCard($id: ID!) { product(id: $id) { id name seller { id name } } }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-34ba91de99b9","heading":"Schema, types & operation documents","text":"The successful response follows the selected shape; unselected priceMinor is absent:","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-59b1d188c3ce","heading":"Schema, types & operation documents","text":"{ \"data\": { \"product\": { \"id\": \"42\", \"name\": \"Interview Handbook\", \"seller\": { \"id\": \"7\", \"name\": \"Bookshop\" } } } }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-d2ff84893962","heading":"Schema, types & operation documents","text":"How to read it: ID is an opaque identifier scalar, not necessarily a number. The exclamation mark is a non-null contract. The product lookup itself is nullable (for example, no visible match), while a present product must supply name and seller under this schema. Variables might be { \"id\": \"42\" }; do not concatenate untrusted strings into query source.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-150e1fa8f887","heading":"Schema, types & operation documents","text":"Other components: Scalars represent leaf values; enums constrain named choices; input objects describe structured arguments; interfaces/unions model polymorphic outputs. Directives such as skip/include conditionally select fields. Custom scalars need documented serialization and validation; a Date scalar is not built in. GraphQL Int is a signed 32-bit integer; choose a documented scalar/representation when money or IDs exceed that range.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-000f65a429c8","heading":"Schema, types & operation documents","text":"Pagination: A connection-style field may expose edges/node/cursor and pageInfo/hasNextPage/endCursor. This is a common schema convention, not a GraphQL requirement. Bound first/last and follow the underlying pagination contract.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-execution","heading":"How a GraphQL request executes","text":"How a GraphQL request executes","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-execution-definition","heading":"How a GraphQL request executes","text":"A GraphQL server parses an operation document, validates it against the schema, coerces variables, and executes the selected fields. An operation name selects which operation to run if the document contains several. The schema limits what can be requested; resolvers supply the actual values.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-aa8b884a9234","heading":"How a GraphQL request executes","text":"Product query: selection → validation → resolution → responseClient submits ProductCard and variablesThe selected fields describe the required result, not SQL or the underlying storage layout.Server validates and establishes request contextCheck the operation against the schema and supply validated identity, services, and request-scoped loaders.Resolve product, then selected child fieldsLoad the authorized product; resolve seller through a bounded, scoped data-access path.Return data and any execution errorsThe client handles complete, partial, or failed results according to the operation and UI contract.Authentication and request-context setup are hosting concerns; their exact position in the HTTP pipeline depends on the server framework.","kind":"Diagram"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-06e24ddad54e","heading":"How a GraphQL request executes","text":"Transport: GraphQL is commonly served over HTTP, often at one endpoint. POST can carry document, variables, and operation name; some servers support GET for queries. Mutation operations must not execute through GET. Subscriptions require a supported transport/protocol, such as a chosen WebSocket protocol or SSE integration.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-1722a638ffcf","heading":"How a GraphQL request executes","text":"Tradeoff: A shared endpoint simplifies schema entry but changes logging, caching, and rate-limit granularity. Record operation names/hashes, duration, errors, and backend calls; avoid logging sensitive variables indiscriminately.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-resolvers","heading":"Resolvers, context & N+1 prevention","text":"Resolvers, context & N+1 prevention","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-resolvers-definition","heading":"Resolvers, context & N+1 prevention","text":"A resolver supplies a field’s value. Common server libraries call resolvers with parent/source, arguments, request context, and execution info. Default field resolution often reads an object property; explicit resolvers connect fields to services and relationships.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-cc7c55c8adf7","heading":"Resolvers, context & N+1 prevention","text":"// Common resolver-map convention; wire through your server framework. // context.services enforces access; sellerById is scoped to this request. const resolvers = { Query: { product: (_parent, { id }, context) => context.services.products.findVisibleById(id, context.user) }, Product: { seller: (product, _args, context) => context.loaders.sellerById.load(product.sellerId) } };","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-3381363f4b2f","heading":"Resolvers, context & N+1 prevention","text":"Context: Supply validated identity, application services, request IDs, and request-scoped loaders. Do not trust a userId variable to establish identity. Enforce authorization consistently in application/data access, including nested fields.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-5c03375ce5aa","heading":"Resolvers, context & N+1 prevention","text":"Batching: A DataLoader-style utility batches loads within its scheduling window and caches them within its configured scope. Its batch function must return results aligned to input keys, including missing values/errors. Scope it per request and authorization boundary; a process-global personalized loader can leak data.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-c8c4d5014fdb","heading":"Resolvers, context & N+1 prevention","text":"Use: Relationship fields with repeated entity lookups. Prefer a join/eager load or purpose-built query when it is simpler and cheaper. A loader cannot rescue an arbitrarily expensive query or guarantee one database round trip for the whole operation. See N+1 tradeoffs.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-operations","heading":"Queries, mutations & subscriptions","text":"Queries, mutations & subscriptions","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-operations-definition","heading":"Queries, mutations & subscriptions","text":"Queries read data. Mutations request changes. Subscriptions establish an event source that produces execution results over time. These are schema operation categories; they do not automatically define persistence or delivery guarantees.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-265aad0ae2f5","heading":"Queries, mutations & subscriptions","text":"input RenameProductInput { id: ID! name: String! } type RenameProductPayload { product: Product } type Mutation { renameProduct(input: RenameProductInput!): RenameProductPayload! }","kind":"Code"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-74438e9a646a","heading":"Queries, mutations & subscriptions","text":"Mutation behavior: Top-level fields in one mutation operation execute serially. This does not make nested resolution serial, create a database transaction, roll back earlier successful fields, or serialize all clients’ writes. Invoke an application service with explicit validation, transaction, and concurrency-control rules.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-f830ff075784","heading":"Queries, mutations & subscriptions","text":"Example: RenameProduct checks access and a permitted name, updates the record, and returns the confirmed product. Return enough identity/version data for the client cache to reconcile. Choose an explicit typed payload for expected business outcomes rather than exposing database exception strings.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-811f75648bfe","heading":"Queries, mutations & subscriptions","text":"Subscription limits: Reconnection does not inherently replay missed events or guarantee exactly-once delivery. Authorize subscriptions, bound resource usage, and define resume/refetch behavior. Ordinary polling may be sufficient for infrequent updates; compare WebSocket, SSE, and polling.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-errors","heading":"Nullability, partial data & errors","text":"Nullability, partial data & errors","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-errors-definition","heading":"Nullability, partial data & errors","text":"A GraphQL execution response can contain both data and errors. A field-level error can leave other fields usable. Non-null propagation moves a null-producing failure to the nearest nullable ancestor; the schema’s nullability determines the blast radius.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-a1697896d980","heading":"Nullability, partial data & errors","text":"Example: In the product schema, seller is non-null. If seller resolution fails, product can become null even when its name resolved successfully, because product is the nullable ancestor. If every ancestor were non-null, the error could null the operation’s data.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-ce17be143599","heading":"Nullability, partial data & errors","text":"List notation: [Product] allows a null list and null items; [Product!] allows a null list but not null items; [Product!]! allows neither. Use non-null for guarantees the server can maintain, not as a blanket preference.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-fcd489244352","heading":"Nullability, partial data & errors","text":"Client policy: Deliberately choose whether partial results render, show a warning, or fail the task. Error paths identify affected fields; expose safe application codes in extensions where the contract specifies them. Transport failure, parse/validation failure, field execution errors, and expected domain rejection need distinct handling.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-f86fb99d8b75","heading":"Nullability, partial data & errors","text":"HTTP: Do not assume HTTP 200 means full application success or that every GraphQL failure must return 200. Status behavior depends on failure phase and the server’s HTTP/media-type contract. Inspect the GraphQL result and the client library’s error policy. See UI failure isolation.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-caching","heading":"Client caching, identity & mutation reconciliation","text":"Client caching, identity & mutation reconciliation","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-caching-definition","heading":"Client caching, identity & mutation reconciliation","text":"A normalized GraphQL cache stores identifiable entities separately and connects query results through references. Clients such as Apollo or Relay can merge representations when configured identity and field policies agree. A plain fetch call has no automatic normalized cache.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-f9b194cb8fae","heading":"Client caching, identity & mutation reconciliation","text":"Example: Two operations fetch Product 42 with different fields. A cache using type plus ID can retain one entity, allowing a confirmed mutation response to update its known fields. Lists, membership, ordering, pagination, deleted entities, and argument-specific fields still require explicit policies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-965e3f3cb510","heading":"Client caching, identity & mutation reconciliation","text":"Use: Reused entities across relationship-rich screens. Supply stable IDs, sensible pagination/merge rules, and identity/tenant isolation. For a small operation surface, an ordinary query cache plus explicit updates may be simpler than normalization.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-327b930b233f","heading":"Client caching, identity & mutation reconciliation","text":"Server/HTTP caching: POST-based arbitrary operations do not map as naturally to ordinary shared HTTP caching as resource GETs. Persisted queries and suitable GET query support can enable stable request identities, but server/CDN policies must include variables, authorization scope, and relevant headers. Persisted operations are not automatically authorized or cacheable.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-350d0d9834db","heading":"Client caching, identity & mutation reconciliation","text":"Comparison: Request-local loader caching avoids repeated backend reads within an operation; normalized client caching coordinates entity views; HTTP caching reuses responses. Follow the same server-state lifecycle and cache boundaries.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-tooling","heading":"Schema evolution, generated types & query safety","text":"Schema evolution, generated types & query safety","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-tooling-definition","heading":"Schema evolution, generated types & query safety","text":"A typed schema enables documentation, validation, operation-aware code generation, and change detection. Generate types from the actual selected operation when possible; a schema’s Product type is not the same as the ProductCard query’s selected result.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-acb4d123ea8d","heading":"Schema evolution, generated types & query safety","text":"Evolution: Add fields, deprecate old ones, measure usage, and migrate clients before removal. Adding required arguments/input fields breaks callers; nullability and enum changes can break generated assumptions too. A schema registry or CI compatibility check helps, but client rollout behavior still matters.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-071c8f1df6bd","heading":"Schema evolution, generated types & query safety","text":"Cost controls: Bound pagination, operation size, aliases/batching, depth, and estimated cost as appropriate. A shallow query can still be expensive, so combine static policies with timeouts, concurrency limits, and backend measurements. Rate-limit by meaningful work/identity rather than only “one HTTP request.”","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-fe47c12ee373","heading":"Schema evolution, generated types & query safety","text":"Security: Validate scalar/business values and enforce object/field permissions. Disabling introspection is not authorization. Trusted persisted-operation allowlists can reduce exposed query shapes, but authorization and variable validation remain necessary. Avoid leaking internal stack traces and private fields through errors or shared caches.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-5d2f1a51dab7","heading":"Schema evolution, generated types & query safety","text":"Tradeoff: Schema governance and tooling pay off for substantial multi-client APIs but can be overhead for small services. Generated TypeScript still does not establish runtime truth; see static versus runtime validation.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-vs-rest","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"GraphQL vs. REST: choose by the client and operating cost","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"gql-vs-rest-definition","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"REST organizes interactions around resources and representations using HTTP semantics; many practical “REST APIs” use a pragmatic resource-oriented style. GraphQL offers a typed field-selection/execution contract. Neither guarantees good domain design, low latency, security, or maintainability.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-6ae1842b79f1","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"ConcernGraphQLResource-oriented HTTP API","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-9a724d86ba89","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Variable screen dataClient selects related fields through a schema.Use resource representations, sparse fields, includes, or a BFF as needed.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-4c8e50b5755e","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Backend workResolvers need batching, authorization, and cost controls.Handlers need efficient queries, authorization, and bounded work too.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-63fbef6ca86c","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"CachingOften client normalization plus explicit server/persisted-query policies.Resource GETs align naturally with HTTP validators and cache policies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-41b3b8b4c17b","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"ContractsSchema, operation validation, and operation-specific code generation.OpenAPI/JSON Schema and generated clients can also provide typed contracts.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-90b715a9b847","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Uploads/streamingOften use a signed upload URL or a separate endpoint/protocol.Dedicated endpoints and standard HTTP transfer patterns often fit naturally.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-63bc12925303","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"OperationsTrack operation names/costs and partial errors.Track routes, status semantics, representation sizes, and dependencies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-b383c551765c","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Choose GraphQL: Several clients need changing combinations of related entities, shared schema ownership is realistic, and the organization can operate query-level authorization/cost/caching policies.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-c2019d301ee5","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Choose REST: Resource operations are stable, HTTP caching is valuable, clients are simple, or the team wants a smaller operational surface. Avoid adding GraphQL just to remove one inconvenient endpoint; an aggregate endpoint or BFF may solve it.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-700502c4fa9d","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Other alternatives: RPC suits explicit commands/workflows and can have generated contracts; gRPC uses Protobuf and requires deliberate browser integration. SSE/WebSockets address ongoing delivery, not resource modeling. A system can combine REST downloads/uploads, GraphQL reads, and event subscriptions without forcing one style everywhere.","kind":"Notes"},{"page":"graphql.html","topic":"GraphQL","anchor":"search-01299ad4647c","heading":"GraphQL vs. REST: choose by the client and operating cost","text":"Interview explanation: Start with client data shapes and ownership, measure waterfalls and backend work, then choose the contract and operating model. One endpoint or fewer response fields is not a sufficient performance argument.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-networking-title","heading":"","text":"HTTP & Networking","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-36f69aa20188","heading":"","text":"Trace requests, preserve protocol semantics, and choose explicit caching and transport policies.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-765c39339dfd","heading":"","text":"From URL to response: the request lifecycle","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-576c90409331","heading":"","text":"Methods, status codes & idempotency","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-b91e6c59668a","heading":"","text":"HTTP caching: freshness, validation & cache keys","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-9d792cc1e521","heading":"","text":"Payloads, compression & request waterfalls","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-c869469d0274","heading":"","text":"Browser origin, credentials & storage boundaries","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-514d1c19ee92","heading":"","text":"Interview review: follow the response contract","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-lifecycle","heading":"From URL to response: the request lifecycle","text":"From URL to response: the request lifecycle","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-lifecycle-definition","heading":"From URL to response: the request lifecycle","text":"A network navigation can involve cache lookup, DNS resolution, a connection, TLS negotiation, an HTTP request/response, and browser parsing/rendering. Existing connections, service workers, caches, redirects, and speculative work can change which steps occur.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-76ffceec0c45","heading":"From URL to response: the request lifecycle","text":"Example: A slow product page may have fast server execution but a long DNS/TLS setup, redirect chain, or JavaScript request waterfall. Inspect the Network panel’s timing and initiator chain instead of labeling all waiting time “backend latency.”","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-2adc977ca6cc","heading":"From URL to response: the request lifecycle","text":"Protocol choices: HTTP/1.1 commonly uses multiple connections; HTTP/2 multiplexes streams on a TCP connection but can still suffer connection-level TCP head-of-line blocking; HTTP/3 uses QUIC with independent streams and TLS integration. These change transport behavior, not resource authorization or application semantics.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-a4ad27818270","heading":"From URL to response: the request lifecycle","text":"Use: Diagnose connection reuse, cache behavior, payload transfer, and dependent requests before optimizing. DNS/CDN routing and geographic distance affect latency; moving a service does not fix an avoidable client waterfall. See performance measurement.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-semantics","heading":"Methods, status codes & idempotency","text":"Methods, status codes & idempotency","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-semantics-definition","heading":"Methods, status codes & idempotency","text":"Safe methods have read-only intended semantics; idempotent methods have the same intended server effect when repeated as when applied once. This does not require identical responses and does not mean every implementation obeys the contract.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-0d339133a919","heading":"Methods, status codes & idempotency","text":"MethodIntended useImportant distinction","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-31b956a27410","heading":"Methods, status codes & idempotency","text":"GET / HEADRead representation / response metadata.Safe and idempotent; do not use them for state-changing commands.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-990c50b7685c","heading":"Methods, status codes & idempotency","text":"POSTSubmit work or create a subordinate resource.Not inherently idempotent; a server-supported idempotency key can deduplicate one operation.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-85dd81c7f61c","heading":"Methods, status codes & idempotency","text":"PUTCreate/replace the state of a target resource.Idempotent semantics; send the representation required by the contract.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-1e0d4fc2b8c0","heading":"Methods, status codes & idempotency","text":"PATCHApply partial modifications.Not inherently idempotent; depends on patch semantics.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-46bd2d577655","heading":"Methods, status codes & idempotency","text":"DELETERemove the target resource association.Idempotent intended effect; a second call may return a different status.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-b71a57fcefe6","heading":"Methods, status codes & idempotency","text":"Status contract: 200 for successful content, 201 for creation, 202 for accepted but unfinished work, 204 for no response body. 400 covers invalid requests; 401 unauthenticated, 403 forbidden, 404 unavailable resource, 409 application conflict, 412 failed precondition, 422 semantically invalid content where adopted, 429 rate-limited, and 5xx server/gateway failure. Follow a documented API contract rather than assuming all clients treat codes identically.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-e9fee2e127c9","heading":"Methods, status codes & idempotency","text":"Use: Correct semantics support caching, retry decisions, and client recovery. Never retry a mutation just because a connection failed without considering its idempotency contract. Use structured error bodies for actionable details.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-caching","heading":"HTTP caching: freshness, validation & cache keys","text":"HTTP caching: freshness, validation & cache keys","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-caching-definition","heading":"HTTP caching: freshness, validation & cache keys","text":"An HTTP cache stores a response under a cache key and policy. A fresh response can be reused without contacting the origin; a stale response may need revalidation. Browser private caches and shared CDN/proxy caches have different privacy boundaries.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-2e53b7fc5fb6","heading":"HTTP caching: freshness, validation & cache keys","text":"Cache-Control: public, max-age=60, s-maxage=300 ETag: \"product-v7\" Vary: Accept-Encoding","kind":"Code"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-7249bf469ba9","heading":"HTTP caching: freshness, validation & cache keys","text":"Interpretation: This deliberately public response can be fresh for 60 seconds in a private cache and 300 in shared caches. Vary makes relevant request-header values part of cache selection. Use public policies only for data safe to share across users; URL-only CDN keys can leak personalized content if policy and authorization are wrong.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-f307d42a9076","heading":"HTTP caching: freshness, validation & cache keys","text":"Directives: no-store asks caches not to store; no-cache permits storage but requires validation before reuse; private disallows shared-cache storage. immutable suits fingerprinted assets with long freshness. stale-while-revalidate permits bounded stale reuse while revalidating where supported.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-1d230ced22f6","heading":"HTTP caching: freshness, validation & cache keys","text":"Conditional reads: Send If-None-Match with the ETag; a 304 response reuses the cached body with updated metadata. Last-Modified/If-Modified-Since provide another validator. Conditional writes use If-Match and optimistic concurrency control, which solve a different problem.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-5cc305c16725","heading":"HTTP caching: freshness, validation & cache keys","text":"Choose the layer: HTTP caches reuse responses; a query cache coordinates application data and mutations. One does not automatically invalidate the other. Version static asset URLs, set explicit personalized-response policies, and define invalidation for mutable public resources. See the optimization overview.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-transport","heading":"Payloads, compression & request waterfalls","text":"Payloads, compression & request waterfalls","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-transport-definition","heading":"Payloads, compression & request waterfalls","text":"Total request time includes waiting, transfer, decompression, parsing, and downstream rendering. Smaller wire payloads can still require expensive JavaScript parsing or application work.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-d8a2c1789060","heading":"Payloads, compression & request waterfalls","text":"Use: Inspect transfer size versus decoded size; use negotiated compression for suitable text, appropriately sized images, pagination, and conditional requests. A CDN can cache suitable public assets near users, but does not make an uncacheable personalized request disappear.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-0b53540edfe6","heading":"Payloads, compression & request waterfalls","text":"Waterfall example: Fetch user → then settings → then permissions when settings/permissions only need the user ID creates dependencies. If an authenticated API can provide independent requests or an appropriate aggregate response, start them together. Do not parallelize work that truly depends on earlier results.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-1f11c2d121ca","heading":"Payloads, compression & request waterfalls","text":"Tradeoffs: Aggregation reduces round trips but can couple latency and failures; splitting lets optional UI load independently. Preload/prefetch can help known critical resources but waste bandwidth when overused. Connection reuse and HTTP multiplexing do not eliminate application dependencies. See bounded concurrency and BFF composition.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-browser-boundaries","heading":"Browser origin, credentials & storage boundaries","text":"Browser origin, credentials & storage boundaries","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-browser-boundaries-definition","heading":"Browser origin, credentials & storage boundaries","text":"The browser enforces rules that a server-side HTTP client does not share. An origin is scheme, host, and port; a cookie’s scope and SameSite rules use additional concepts and are not identical to same-origin checks.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-b2488b6a55b9","heading":"Browser origin, credentials & storage boundaries","text":"Example: A fetch can fail browser CORS checks even when a server-side request to the same API succeeds. Cross-origin fetch credentials require the appropriate client option and server policy, while browser cookie restrictions can still block their use.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"search-2f8399150289","heading":"Browser origin, credentials & storage boundaries","text":"Choose deliberately: Keep the canonical explanations in CORS and TLS, CSRF, and credential storage. CORS governs browser access to responses; it is not authentication or an authorization boundary. Never “fix” credentialed CORS with wildcard origins.","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-review","heading":"Interview review: follow the response contract","text":"Interview review: follow the response contract","kind":"Notes"},{"page":"http-networking.html","topic":"HTTP & Networking","anchor":"http-review-definition","heading":"Interview review: follow the response contract","text":"Describe the request path, method semantics, cacheability, validators, credential boundary, and failure response. Diagnose a slow request with timings before choosing a CDN, batching, GraphQL, or a BFF. Those mechanisms address different sources of cost.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"javascript-mechanics-title","heading":"","text":"JavaScript Language Mechanics","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d0e38d0f263b","heading":"","text":"Understand bindings, invocation, object identity, and memory before applying them to React or backend code.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d4a6bc7e4083","heading":"","text":"Lexical scope, closures & lifetime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-344ea1a2ecc2","heading":"","text":"this, arrow functions & method invocation","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-0da0c2272c67","heading":"","text":"Objects, prototypes & classes","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-2d23790b8037","heading":"","text":"Equality, mutation & copying","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-f0c6bb7b89fa","heading":"","text":"Garbage collection & memory leaks","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e64ee08e851e","heading":"","text":"Interview review: reason from the runtime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-scope","heading":"Lexical scope, closures & lifetime","text":"Lexical scope, closures & lifetime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-scope-definition","heading":"Lexical scope, closures & lifetime","text":"Lexical scope resolves names from where code is defined. A closure retains access to its surrounding lexical environment after the outer function returns. It captures bindings, not an automatic frozen copy of every value.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4c867e81696d","heading":"Lexical scope, closures & lifetime","text":"function makeCounter() { let count = 0; return () => ++count; } const next = makeCounter(); next(); // 1 next(); // 2","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-e6c6af5f73fc","heading":"Lexical scope, closures & lifetime","text":"Use: Encapsulated state, callbacks, factories, and dependency injection. Each factory invocation has a separate environment; closures created within the same invocation can share bindings. Closures are ordinary functions, not separate threads.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-8d55cab2a5f7","heading":"Lexical scope, closures & lifetime","text":"Pitfalls: var is function-scoped; let/const are block-scoped and cannot be accessed before initialization because of the temporal dead zone. const prevents reassignment of the binding, not mutation of an object. Long-lived callbacks can retain large environments.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-6a5a835327e1","heading":"Lexical scope, closures & lifetime","text":"React connection: Each render creates a new snapshot and closures from that render observe its values. Use correct dependencies, functional updates, or refs according to the intended lifecycle; see render snapshots and dependencies. Do not suppress dependencies merely to keep a closure stable.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-this","heading":"this, arrow functions & method invocation","text":"this, arrow functions & method invocation","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-this-definition","heading":"this, arrow functions & method invocation","text":"For ordinary functions, this depends on how the function is called. A method call binds its receiver; extracting the function loses that receiver. Arrow functions inherit this lexically and cannot be rebound with call/apply/bind.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-31e79ee9392b","heading":"this, arrow functions & method invocation","text":"const counter = { value: 2, read() { return this.value; } }; counter.read(); // 2 const read = counter.read.bind(counter); read(); // 2, even when passed as a callback.","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-93aa2d532adc","heading":"this, arrow functions & method invocation","text":"Use: Understand method callbacks in SDKs and classes. call/apply invoke with an explicit receiver; bind creates another function. In strict mode, an ordinary unbound call has undefined this.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-cbe447ebe272","heading":"this, arrow functions & method invocation","text":"Choose deliberately: Arrow callbacks suit lexical behavior; use an ordinary method when the receiver should vary. A closure with explicit parameters often avoids receiver ambiguity entirely. Repeated bind() creates new references; listener removal requires the original callback identity.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-prototypes","heading":"Objects, prototypes & classes","text":"Objects, prototypes & classes","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-prototypes-definition","heading":"Objects, prototypes & classes","text":"Prototype delegation searches an object’s own properties first, then its prototype chain. Class methods typically live on the prototype; a class is JavaScript syntax with additional semantics, not a separate inheritance runtime.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-8298e5d9aee8","heading":"Objects, prototypes & classes","text":"class Counter { constructor() { this.value = 0; } increment() { this.value += 1; } } const counter = new Counter(); Object.hasOwn(counter, 'value'); // true Object.hasOwn(counter, 'increment'); // false","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-52a33b8becf2","heading":"Objects, prototypes & classes","text":"Use: Reading library behavior, understanding shared methods, and integrating class-based APIs. Class field arrow functions are created per instance; prototype methods are shared. Native #private fields provide runtime private access, unlike TypeScript’s ordinary private modifier.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-6c996ea36b7c","heading":"Objects, prototypes & classes","text":"Alternatives and pitfalls: Prefer composition and functions when inheritance does not represent a stable substitutable relationship. Avoid changing built-in prototypes. Use Object.hasOwn when inherited keys must not count, and validate untrusted object keys to avoid prototype-pollution paths. A Map can be clearer for a dynamic key/value registry.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-identity","heading":"Equality, mutation & copying","text":"Equality, mutation & copying","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-identity-definition","heading":"Equality, mutation & copying","text":"Primitives compare by value; objects compare by identity. Assigning or passing an object copies its reference value, so two variables can refer to the same mutable object. JavaScript passes arguments by value, including reference values.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4ed039679329","heading":"Equality, mutation & copying","text":"const previous = { user: { name: 'Ada' }, count: 1 }; const shallow = { ...previous }; shallow !== previous; // true shallow.user === previous.user; // true const next = { ...previous, user: { ...previous.user, name: 'Grace' } }; // Only the changed path has new identities; previous remains unchanged.","kind":"Code"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-d1792a3aa611","heading":"Equality, mutation & copying","text":"Use: Immutable state updates and predictable cache selectors. Spread/Object.assign are shallow copies. structuredClone supports many structured values and cycles, but not functions or DOM nodes and does not preserve arbitrary custom class behavior. JSON round-tripping loses or rejects values such as undefined, dates-as-dates, BigInt, and cycles.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4004a8612211","heading":"Equality, mutation & copying","text":"Equality details: === considers NaN unequal to itself and +0/-0 equal; Object.is does the opposite for those cases. React uses Object.is in several identity comparisons. Map/Set use SameValueZero for keys/values.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-4aede890560a","heading":"Equality, mutation & copying","text":"When not to deep-copy: Deep-cloning every update wastes work and destroys unchanged reference identities. Use structural sharing or a maintained immutable-update helper; see referential stability and memoization.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-memory","heading":"Garbage collection & memory leaks","text":"Garbage collection & memory leaks","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-memory-definition","heading":"Garbage collection & memory leaks","text":"JavaScript garbage collection reclaims objects that are no longer reachable from live roots. An unwanted object that remains reachable is a memory leak; cycles alone are not necessarily leaks.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-8348d648bfc2","heading":"Garbage collection & memory leaks","text":"Example: A window listener keeps a closure alive, which retains a detached panel and its data. An unbounded Map cache or timer can cause the same retention even when the UI disappears.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-39668f84e699","heading":"Garbage collection & memory leaks","text":"Investigate: Reproduce repeated mount/unmount or navigation, compare heap snapshots, inspect retained objects and their retaining paths, and check whether memory stabilizes after collection. Allocation volume and retained memory are different measurements.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"search-1de3191ddbeb","heading":"Garbage collection & memory leaks","text":"Prevent: Define cache size/eviction and resource disposal. WeakMap/WeakSet avoid strongly retaining keys but are not general cache eviction policies: keys are non-enumerable and collection timing is nondeterministic. FinalizationRegistry does not provide reliable timely cleanup.","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-review","heading":"Interview review: reason from the runtime","text":"Interview review: reason from the runtime","kind":"Notes"},{"page":"javascript-mechanics.html","topic":"JavaScript Language Mechanics","anchor":"js-review-definition","heading":"Interview review: reason from the runtime","text":"Explain where a variable resolves, which invocation owns its binding, how a function gets its receiver, which object identities change, and what keeps data reachable. Use those mechanisms to explain stale closures, failed memoization, mutation bugs, and retained listeners rather than memorizing isolated output puzzles.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-title","heading":"","text":"React Hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d1f9df29c6b0","heading":"","text":"Begin with render snapshots and state. Build up to refs, effects, shared subscriptions, responsive updates, and reusable hooks; use the hook index for direct lookup.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-80c838617e2d","heading":"","text":"Choose hooks by the responsibility they manage: state, synchronization, identity, scheduling, or integration. Hooks compose behavior; they do not replace clear state ownership or make expensive work disappear.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7a5f24cd7ec","heading":"","text":"Version scope: React 19-era applications, including useEffectEvent in React 19.2+. useFormStatus comes from react-dom; the other React APIs below come from react. Check your installed React version and framework support before adopting newer APIs. Most stateful and effectful hooks belong in Client Components; use has distinct rules and can also be used in Server Components. See component execution boundaries.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f5cd1c11a6ec","heading":"","text":"Study format: Each hook follows the same seven-part structure: purpose, when to use, example, when not to use and alternatives, benefits and tradeoffs, pitfalls and guarantees, and related concepts. Examples are independent; React hooks are imported from react unless a different import is shown. Application helpers and component fragments are identified explicitly.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4bc859dadae8","heading":"","text":"Rules, render snapshots & dependencies","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b092b14f899d","heading":"","text":"Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-51370648e3cf","heading":"","text":"State & transitions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c3b18f7cbbfb","heading":"","text":"Refs & imperative integration","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0d768edb4395","heading":"","text":"Effects & synchronization","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8da1dbaac11e","heading":"","text":"Memoization & identity","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-83a8910fb32f","heading":"","text":"Context & external stores","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e47926f77e22","heading":"","text":"Responsive interactions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7103dbf587a2","heading":"","text":"Actions, forms & async resources","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-60ae9cfa4a8f","heading":"","text":"Accessibility & diagnostics","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-58f7add2654d","heading":"","text":"Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b5e3cd96d86","heading":"","text":"Interview-ready decision process","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-mental-model","heading":"Rules, render snapshots & dependencies","text":"Rules, render snapshots & dependencies","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-18e41d2e96f2","heading":"Rules, render snapshots & dependencies","text":"Rules of Hooks: Call hooks at the top level of a function component or custom hook, before conditional returns. Do not call them in loops, event handlers, or ordinary utility functions. React relies on consistent hook call order. The use API is an explicit exception discussed below.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1af3e7a8fb4b","heading":"Rules, render snapshots & dependencies","text":"Render snapshots: Each render sees its own props and state. Callbacks close over that snapshot. A stale closure occurs when later work uses an outdated captured value; a dependency omission is a common cause.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-54d64bef5cf3","heading":"Rules, render snapshots & dependencies","text":"Purity: Rendering calculates UI. Do not mutate external data, start subscriptions, or send requests as a render side effect. React may retry or discard render work; reducers, initializers, and memo calculations must also be pure.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6e518f1f8bfd","heading":"Rules, render snapshots & dependencies","text":"Dependency arrays: Include every reactive value read by an effect or memoized callback/calculation. Dependencies are compared using Object.is. Fix the code’s ownership or synchronization model rather than disabling exhaustive-deps to force a preferred schedule.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b4e5ebdda923","heading":"Rules, render snapshots & dependencies","text":"Hook identity & state lifetime: State belongs to a component’s position and identity in the tree. Changing its key can reset state; defining component types inside another component can cause unintended remounts. A hook call does not create globally shared state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-345603a0bec9","heading":"Rules, render snapshots & dependencies","text":"Connect this model to render, reconciliation, and commit, and to referential stability when designing dependencies.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-63e8da7b01ee","heading":"Rules, render snapshots & dependencies","text":"For the language mechanism behind captured values and object identity, see lexical closures and reference equality and structural sharing.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-catalog","heading":"Hook index","text":"Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7576d14980ba","heading":"Hook index","text":"State & transitions: useState, useReducer","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d8080257148c","heading":"Hook index","text":"Refs & imperative integration: useRef, useImperativeHandle","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-622e0ada346e","heading":"Hook index","text":"Effects & synchronization: useEffect, useLayoutEffect, useEffectEvent, useInsertionEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c6b3cfed42fd","heading":"Hook index","text":"Memoization & identity: useMemo, useCallback","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d4656f27a888","heading":"Hook index","text":"Context & external stores: useContext, useSyncExternalStore","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-40782e71b242","heading":"Hook index","text":"Responsive interactions: useTransition, useDeferredValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cc60c07799eb","heading":"Hook index","text":"Actions, forms & async resources: useActionState, useFormStatus, useOptimistic, use","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d08fc91d1a3f","heading":"Hook index","text":"Accessibility & diagnostics: useId, useDebugValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-530f90125e55","heading":"Hook index","text":"Custom hooks: Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-state","heading":"State & transitions","text":"State & transitions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-state-title","heading":"State & transitions › useState","text":"useState","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-539e047444f0","heading":"State & transitions › useState","text":"Purpose: Stores a local state value and queues renders when it changes. Each render sees a snapshot; a setter does not mutate the value in the running handler.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d76b2c4ae941","heading":"State & transitions › useState","text":"When to use: An independent value such as an expanded panel, input query, or selected tab.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-674835bba06c","heading":"State & transitions › useState › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-608a84eaa1d2","heading":"State & transitions › useState › Example","text":"function Counter() { const [count, setCount] = useState(0); function addTwo() { setCount(previous => previous + 1); setCount(previous => previous + 1); } return \u003cbutton onClick={addTwo}>{count}\u003c/button>; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-37a361d543f0","heading":"State & transitions › useState › Example","text":"Functional updaters run against queued state, so the two updates add 2 even when React batches them.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bcbb44ef6ac9","heading":"State & transitions › useState › Example","text":"When not to use & alternatives: Do not store values that can be derived from props/state during render. Use useRef for mutable values that should not render, or useReducer for related transitions.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c975dc4d63c7","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f66559c0c22e","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Benefits: Small API, local ownership, and automatic batching reduce coordination work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-98c72050c961","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Tradeoffs: Many interdependent setters can obscure invariants; lifting state too far broadens render work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cc58143c2fa3","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Pitfalls & guarantees: Use immutable updates and pure updaters. The setter identity is stable; Object.is-equal values can skip updates. useState(() => createInitialDraft()) lazily initializes; pass a function wrapper when storing a function. React may invoke initializers/updaters twice in development. Batching is not one guaranteed render for an entire async workflow.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-926aa0c85ccf","heading":"State & transitions › useState › Benefits & tradeoffs","text":"Related concepts: State ownership · Render snapshots · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-reducer-title","heading":"State & transitions › useReducer","text":"useReducer","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-20e30a999ec8","heading":"State & transitions › useReducer","text":"Purpose: Applies a pure (state, action) => nextState function to queued actions. It makes related transitions explicit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a20533edb51a","heading":"State & transitions › useReducer","text":"When to use: A workflow with several events and invariants, such as draft editing, retries, or selection management.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-45c6ffb3c318","heading":"State & transitions › useReducer › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-47eb94f43920","heading":"State & transitions › useReducer › Example","text":"function counterReducer(state, action) { switch (action.type) { case 'increment': return { count: state.count + 1 }; case 'reset': return { count: 0 }; default: throw new Error('Unknown action: ' + action.type); } } function Counter() { const [state, dispatch] = useReducer(counterReducer, { count: 0 }); return ( \u003cbutton onClick={() => dispatch({ type: 'increment' })}> {state.count} \u003c/button> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-429b05e84b26","heading":"State & transitions › useReducer › Example","text":"Events describe intent; the reducer centralizes the permitted state change. Shared-provider wiring stays in the existing Context topic.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b08e2933713","heading":"State & transitions › useReducer › Example","text":"When not to use & alternatives: For one simple value, prefer useState. For hierarchical or parallel workflows, consider a dedicated state-machine library rather than an expanding switch statement.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-66708d27159d","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d357a2c53a8e","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Benefits: Centralized transitions are independently testable and easier to audit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f3142a49e7bb","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Tradeoffs: Adds action types and indirection; it does not automatically optimize rendering or share state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8c5c595454d4","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Pitfalls & guarantees: Dispatch has stable identity. Keep reducers immutable and side-effect free; fetch in a handler/effect and dispatch completion events. useReducer(reducer, initialArg, init) supports lazy initialization. A reducer is not automatically an FSM; model states and guards explicitly.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d6c73e734c00","heading":"State & transitions › useReducer › Benefits & tradeoffs","text":"Related concepts: Context + reducer · Finite state machines · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-refs","heading":"Refs & imperative integration","text":"Refs & imperative integration","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-ref-title","heading":"Refs & imperative integration › useRef","text":"useRef","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0221e457c647","heading":"Refs & imperative integration › useRef","text":"Purpose: Keeps a stable object with a mutable current property; mutation does not request a render.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-816c2e5364d6","heading":"Refs & imperative integration › useRef","text":"When to use: DOM access, timer IDs, or an imperative resource that is not the screen’s source of truth.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0cc543cf6442","heading":"Refs & imperative integration › useRef › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6cca9e4231e7","heading":"Refs & imperative integration › useRef › Example","text":"function SearchField() { const inputRef = useRef(null); return ( \u003c> \u003cinput ref={inputRef} aria-label=\"Search\" /> \u003cbutton onClick={() => inputRef.current?.focus()}>Focus search\u003c/button> \u003c/> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e3089c079cd0","heading":"Refs & imperative integration › useRef › Example","text":"React assigns the DOM node during commit. The click handler uses it without putting the node in state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d182a0e8915b","heading":"Refs & imperative integration › useRef › Example","text":"When not to use & alternatives: Use state for values that must update UI. Do not use refs to conceal missing effect dependencies; useEffectEvent may fit genuinely non-reactive effect logic.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c53591104506","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bcadd3617161","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Benefits: Provides stable mutable storage and direct integration with DOM APIs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-106116d27a59","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Tradeoffs: Changes are invisible to rendering and can become hidden state if overused.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9bfea531a5a6","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Pitfalls & guarantees: Do not generally read/write refs during render except predictable initialization patterns. DOM refs can be null before attachment and after removal. StrictMode may create/discard a ref object in development while checking purity; only the committed instance matters.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e43ba205a3ec","heading":"Refs & imperative integration › useRef › Benefits & tradeoffs","text":"Related concepts: Reactive state · Restricted imperative APIs · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-imperative-handle-title","heading":"Refs & imperative integration › useImperativeHandle","text":"useImperativeHandle","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bad899d56965","heading":"Refs & imperative integration › useImperativeHandle","text":"Purpose: Customizes the handle exposed through a ref instead of exposing the component’s complete internal DOM.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-51eda7064ea4","heading":"Refs & imperative integration › useImperativeHandle","text":"When to use: A parent needs a small imperative capability such as focus, selection, or scroll-to-item.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-386b93d29450","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-032806fc926b","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"// React 19: function components receive ref as a prop. function SearchInput({ ref }) { const inputRef = useRef(null); useImperativeHandle(ref, () => ({ focus() { inputRef.current?.focus(); } }), []); return \u003cinput ref={inputRef} aria-label=\"Search\" />; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bc3dd468e0ff","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"The parent receives a focus method, not arbitrary access to the internal input API.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-259ee3da6b98","heading":"Refs & imperative integration › useImperativeHandle › Example","text":"When not to use & alternatives: Prefer declarative props for open state, selection, or other persistent UI state. Expose a raw DOM ref only if that is the intended public contract.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f2e295d10fc8","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fb2eec93a241","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Benefits: Encapsulates implementation details while supporting necessary imperative integration.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1587b6df5139","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Tradeoffs: Introduces parent/child timing coupling and a public API that must remain compatible.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ac715a7d923a","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Pitfalls & guarantees: Include reactive values captured by the handle in dependencies. With no dependency array, a new handle is created each render. React 18 and earlier generally need forwardRef; React 19 supports ref as a prop. Handle access must tolerate unmounted children.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a9d37bbd041d","heading":"Refs & imperative integration › useImperativeHandle › Benefits & tradeoffs","text":"Related concepts: Component customization contracts · DOM refs · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-effects","heading":"Effects & synchronization","text":"Effects & synchronization","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-effect-title","heading":"Effects & synchronization › useEffect","text":"useEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e4999212a357","heading":"Effects & synchronization › useEffect","text":"Purpose: Synchronizes committed UI with an external system through setup and cleanup.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-176df2dc79a3","heading":"Effects & synchronization › useEffect","text":"When to use: Subscriptions, timers, observers, connections, and third-party widgets whose lifetime follows component inputs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-609aaca0010e","heading":"Effects & synchronization › useEffect › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f785cc12394a","heading":"Effects & synchronization › useEffect › Example","text":"function WindowTitle({ title }) { useEffect(() => { const previousTitle = document.title; document.title = title; return () => { document.title = previousTitle; }; }, [title]); return null; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c189f4ba2946","heading":"Effects & synchronization › useEffect › Example","text":"This single-owner example updates an external browser resource after commit and restores it when synchronization ends.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-812841a825eb","heading":"Effects & synchronization › useEffect › Example","text":"When not to use & alternatives: Calculate derived data during render; handle an explicit user action in its handler. Use useLayoutEffect only when pre-paint measurement is required. Prefer a framework/query cache over hand-written effects for complex server-state fetching.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-75daaa15b981","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ddb2a3d60513","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Benefits: Explicit setup/cleanup coordinates resource lifetime with changing inputs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-079e496d119f","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Tradeoffs: Adds lifecycle and race-condition complexity; fetching this way can create waterfalls and misses SSR data delivery.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9eb19a9ac036","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Pitfalls & guarantees: No array: runs after each commit. []: no reactive dependencies. [a, b]: cleanup then setup when dependencies change; cleanup also runs on unmount. StrictMode checks setup → cleanup → setup in development. Effects never run on the server, and are not guaranteed to run after paint. Do not make the callback async; return cleanup, not a Promise. Include reactive dependencies and guard obsolete async results.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a38f6b0ca8a2","heading":"Effects & synchronization › useEffect › Benefits & tradeoffs","text":"Related concepts: Listener lifecycle · Async cleanup and cancellation · Non-reactive effect logic · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-layout-effect-title","heading":"Effects & synchronization › useLayoutEffect","text":"useLayoutEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f04a3dc9ddd2","heading":"Effects & synchronization › useLayoutEffect","text":"Purpose: Runs after DOM commit and before the browser repaints, allowing measurement and a synchronous visual correction.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c216efb868f2","heading":"Effects & synchronization › useLayoutEffect","text":"When to use: A tooltip or overlay must measure its rendered box before its final position is painted.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bfeeb13bccf7","heading":"Effects & synchronization › useLayoutEffect › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-13f9ef90d44d","heading":"Effects & synchronization › useLayoutEffect › Example","text":"function MeasuredLabel({ text }) { const ref = useRef(null); const [width, setWidth] = useState(0); useLayoutEffect(() => { setWidth(ref.current.getBoundingClientRect().width); }, [text]); return \u003cspan ref={ref} data-measured-width={width}>{text}\u003c/span>; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-efb0fc420cda","heading":"Effects & synchronization › useLayoutEffect › Example","text":"The geometry read happens after the DOM exists. This illustrates initial/text-driven measurement, not tracking every font or container-size change.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d58c66382573","heading":"Effects & synchronization › useLayoutEffect › Example","text":"When not to use & alternatives: Use CSS for layout when possible, useEffect for non-visual synchronization, or Resize Observer for ongoing size changes.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-17889bdb906c","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ac01a0e2f25f","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Benefits: Prevents a visible intermediate position when measurement determines placement.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-899daa396b94","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Tradeoffs: Blocks paint; synchronous updates add work to the frame’s critical path.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-10371f22bd9a","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Pitfalls & guarantees: It does not run during SSR, which has no browser layout. Keep server output stable and choose an appropriate client boundary. Dependency and cleanup rules still apply. Avoid alternating geometry reads and writes, which can force repeated layout.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5ee4ed3631ef","heading":"Effects & synchronization › useLayoutEffect › Benefits & tradeoffs","text":"Related concepts: Layout thrashing · Resize Observer · Hydration · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-effect-event-title","heading":"Effects & synchronization › useEffectEvent","text":"useEffectEvent","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-384dfb562075","heading":"Effects & synchronization › useEffectEvent","text":"Purpose: Defines non-reactive effect-triggered logic that reads the latest committed props/state without making those values synchronization dependencies. Requires React 19.2+.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8ff4ed751be4","heading":"Effects & synchronization › useEffectEvent","text":"When to use: A connection depends on roomId, while its notification should use the current theme without reconnecting.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f2837cc2b8e8","heading":"Effects & synchronization › useEffectEvent › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7aed53e02b3f","heading":"Effects & synchronization › useEffectEvent › Example","text":"function ConnectionNotice({ roomId, theme }) { const onConnected = useEffectEvent(() => notify('Connected', theme)); useEffect(() => { const connection = createConnection(roomId); // Application API. connection.on('connected', () => onConnected()); connection.connect(); return () => connection.disconnect(); }, [roomId]); return null; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ded0a829941e","heading":"Effects & synchronization › useEffectEvent › Example","text":"roomId remains reactive. The effect-triggered notification sees the latest theme without replacing the connection.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-58d209f7e184","heading":"Effects & synchronization › useEffectEvent › Example","text":"When not to use & alternatives: Do not use it to hide dependencies that should re-synchronize an effect. Use ordinary handlers for UI events, useCallback for a memoized callback prop, or complete effect dependencies for reactive logic.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f7d2c0bf4bde","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0b2e539ba139","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Benefits: Separates resource lifetime from incidental reads without manual ref synchronization.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9f59edd9d6f4","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Tradeoffs: Has deliberately narrow calling rules and needs compatible React/lint tooling.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-132c35acd9b5","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Pitfalls & guarantees: Call Effect Events only from effects or their effect-triggered logic in the same component/hook. Do not call them during render or from UI handlers, pass them to children, or add them to dependency arrays. They are not a general-purpose stable callback.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1a8ad8d7fb79","heading":"Effects & synchronization › useEffectEvent › Benefits & tradeoffs","text":"Related concepts: Effect dependencies · Official reference · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-insertion-effect-title","heading":"Effects & synchronization › useInsertionEffect","text":"useInsertionEffect","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-77616076eef3","heading":"Effects & synchronization › useInsertionEffect","text":"Purpose: Provides a specialized phase for CSS-in-JS libraries to insert styles before layout effects run.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a31505cac781","heading":"Effects & synchronization › useInsertionEffect","text":"When to use: You maintain a runtime styling library whose dynamic rules must exist before consumers measure layout.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-054a56c7d6d4","heading":"Effects & synchronization › useInsertionEffect › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-678696e8f36f","heading":"Effects & synchronization › useInsertionEffect › Example","text":"// Library-internal illustration, not a recommended application pattern. function useRuntimeRule(rule) { useInsertionEffect(() => { const style = document.createElement('style'); style.textContent = rule; document.head.append(style); return () => style.remove(); }, [rule]); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a5680b513e37","heading":"Effects & synchronization › useInsertionEffect › Example","text":"The example shows ordering and cleanup. A production library also needs deduplication, SSR extraction, and CSP-compatible style insertion.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2c53b7fb6254","heading":"Effects & synchronization › useInsertionEffect › Example","text":"When not to use & alternatives: Use static CSS, CSS Modules, or your styling library’s supported API in application code. Use layout effects for measurement, not insertion effects.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2bbad0134898","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d399bf795c5d","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Benefits: Makes styles available before layout-effect readers need them.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-04b8c9cccfeb","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Tradeoffs: Advanced integration surface; runtime style insertion adds complexity and browser style work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4d62b6289df7","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Pitfalls & guarantees: Do not update state or rely on refs being attached. DOM mutation ordering is not an application measurement contract. It does not run on the server; server styles need a separate strategy. Never interpolate untrusted CSS without an appropriate security model.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-d593313f7602","heading":"Effects & synchronization › useInsertionEffect › Benefits & tradeoffs","text":"Related concepts: Style calculation and rendering · Pre-paint measurement · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-memoization","heading":"Memoization & identity","text":"Memoization & identity","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-memo-title","heading":"Memoization & identity › useMemo","text":"useMemo","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-49ea598a35b4","heading":"Memoization & identity › useMemo","text":"Purpose: Caches the result of a pure calculation while dependencies remain equal by Object.is.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a2bc468daef8","heading":"Memoization & identity › useMemo","text":"When to use: Profiling identifies an expensive repeated calculation, or a stable object enables another measured optimization.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4861862ca997","heading":"Memoization & identity › useMemo › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0214b74dd1f4","heading":"Memoization & identity › useMemo › Example","text":"// Fragment inside a component; filterProducts is a pure helper. const visibleProducts = useMemo( () => filterProducts(products, query), [products, query] );","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4e1e1bb7c9b1","heading":"Memoization & identity › useMemo › Example","text":"It reuses results only when both dependency references/values remain unchanged; the initial calculation still runs.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0f3915891355","heading":"Memoization & identity › useMemo › Example","text":"When not to use & alternatives: Use a plain calculation when cheap. Use state/ref for semantic persistence or resource ownership; a cache must not be required for correctness.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-778160ff7b59","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e593b2a7ce9d","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Benefits: Can avoid repeated CPU work and stabilize derived object identity.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-146cd85a1732","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Tradeoffs: Retains values and compares dependencies; unstable inputs or cheap calculations can erase the benefit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0f99731eb317","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Pitfalls & guarantees: React may discard the cache; StrictMode may call the calculation twice in development. Keep calculations pure and dependencies complete. React Compiler can reduce manual memoization when enabled, but does not fix bad ownership or impure code.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-29654723943b","heading":"Memoization & identity › useMemo › Benefits & tradeoffs","text":"Related concepts: Memoization tradeoffs · Profiling · Provider identity · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-callback-title","heading":"Memoization & identity › useCallback","text":"useCallback","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ae0570a7997a","heading":"Memoization & identity › useCallback","text":"Purpose: Caches a function identity while dependencies remain equal; it does not cache results or make the function’s body faster.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8e8f76eb7125","heading":"Memoization & identity › useCallback","text":"When to use: A memoized child benefits from a stable callback prop, or a subscription API’s contract needs a stable function.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-497df7ddb544","heading":"Memoization & identity › useCallback › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b49ce425a3aa","heading":"Memoization & identity › useCallback › Example","text":"// Fragment inside a component; api is a stable imported application API. const handleSave = useCallback( draft => api.save(projectId, draft), [projectId] ); return \u003cMemoizedEditor onSave={handleSave} />;","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8d2ff855d4f5","heading":"Memoization & identity › useCallback › Example","text":"The editor can reuse the callback until projectId changes. Child memoization only helps if its other props also permit skipping work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7b9690a2ace1","heading":"Memoization & identity › useCallback › Example","text":"When not to use & alternatives: Use a normal function when identity does not matter. Put an effect-only helper inside the effect rather than adding an unnecessary callback layer.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ff460f522ac","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8453ff14eb48","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Benefits: Can preserve memoized-child bailouts and make identity contracts explicit.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-548ce4b6a494","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Tradeoffs: Dependency maintenance and cache overhead add complexity without guaranteed savings.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-dc3785027b46","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Pitfalls & guarantees: Omitting captured values causes stale closures. Creating the function expression still happens; React chooses whether to return the cached one. Its cache is an optimization, not a permanent identity guarantee. Compiler-enabled code may need less manual memoization.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-81c6db32cfd2","heading":"Memoization & identity › useCallback › Benefits & tradeoffs","text":"Related concepts: Result vs. function caching · Callback identity for listener removal · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-context-stores","heading":"Context & external stores","text":"Context & external stores","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-context-title","heading":"Context & external stores › useContext","text":"useContext","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8a5345b92d23","heading":"Context & external stores › useContext","text":"Purpose: Reads and subscribes to the nearest matching provider’s value. The context distributes data; it does not own state transitions.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1ad0e392a73b","heading":"Context & external stores › useContext","text":"When to use: A subtree shares a theme, dependency, session display value, or domain state without prop drilling through unrelated layers.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-440b3aa7cfe1","heading":"Context & external stores › useContext › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7e2804151433","heading":"Context & external stores › useContext › Example","text":"const ThemeContext = createContext('light'); function ThemedButton() { const theme = useContext(ThemeContext); return \u003cbutton className={'button-' + theme}>Save\u003c/button>; } // An ancestor may override the default with a ThemeContext provider.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b1a93e70fc9","heading":"Context & external stores › useContext › Example","text":"The fallback applies only when there is no provider; a provider value of undefined does not restore the fallback.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ac3e7dbe3cab","heading":"Context & external stores › useContext › Example","text":"When not to use & alternatives: Use props for explicit, shallow dependencies; use composition to avoid needless plumbing. For fine-grained frequent subscriptions, consider context selectors or an external store.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-66fe3bd044c2","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8a85fdd96bdb","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Benefits: Simple scoped dependency distribution, with different values in different subtrees.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9dfd9cee7f94","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Tradeoffs: Changing the provider value updates all consumers of that context, potentially broadening render work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4350dc0e9f4e","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Pitfalls & guarantees: React compares provider values using Object.is. React.memo does not block a consumed context update; returning one field from a custom hook is not a selector subscription. Split domains/actions deliberately; read the existing architecture rather than rebuilding it here.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e1ad63ec2e6a","heading":"Context & external stores › useContext › Benefits & tradeoffs","text":"Related concepts: Provider implementation · Selectors · Propagation and stability · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-sync-external-store-title","heading":"Context & external stores › useSyncExternalStore","text":"useSyncExternalStore","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-3fc8e1b96558","heading":"Context & external stores › useSyncExternalStore","text":"Purpose: Subscribes to a store outside React while coordinating snapshots with concurrent rendering to avoid inconsistent reads (tearing).","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7071a1e5bc55","heading":"Context & external stores › useSyncExternalStore","text":"When to use: An external state library or browser source of truth changes independently of React.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-717c8a84a389","heading":"Context & external stores › useSyncExternalStore › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-213f18aad417","heading":"Context & external stores › useSyncExternalStore › Example","text":"// Module-scope functions keep the subscription identity stable. function subscribeOnline(onChange) { window.addEventListener('online', onChange); window.addEventListener('offline', onChange); return () => { window.removeEventListener('online', onChange); window.removeEventListener('offline', onChange); }; } const getSnapshot = () => navigator.onLine; const getServerSnapshot = () => true; // Shared initial SSR/client assumption. function OnlineStatus() { const online = useSyncExternalStore( subscribeOnline, getSnapshot, getServerSnapshot ); return \u003cp>{online ? 'Browser reports online' : 'Offline'}\u003c/p>; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1f125f076ffd","heading":"Context & external stores › useSyncExternalStore › Example","text":"The Boolean snapshot is stable when unchanged. The same server snapshot is used for SSR and initial hydration, then the browser snapshot is read. navigator.onLine does not prove the backend is reachable.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cc51d7973b76","heading":"Context & external stores › useSyncExternalStore › Example","text":"When not to use & alternatives: Use React state/reducers for React-owned data. A hand-written effect subscription may suffice for an independent side effect, but does not replace this API’s store-consistency contract.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6ba819cd6f52","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-44898891ab42","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Benefits: Provides concurrency-safe subscription semantics and an explicit hydration snapshot.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ef2389cea9a","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Tradeoffs: Requires careful store design, immutable/cached snapshots, and an SSR policy.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a0825db25bad","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Pitfalls & guarantees: subscribe must return unsubscribe. getSnapshot must be Object.is-equal when data has not changed; returning a fresh object each call can loop. Prefer stable subscription functions. SSR consumers need a matching getServerSnapshot or a deliberate client-only strategy. Updates to external mutable stores cannot be made non-blocking merely by wrapping a mutation in startTransition.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-65ac2e4cfdfc","heading":"Context & external stores › useSyncExternalStore › Benefits & tradeoffs","text":"Related concepts: Subscription cleanup · Hydration · External store selection · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-responsiveness","heading":"Responsive interactions","text":"Responsive interactions","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-transition-title","heading":"Responsive interactions › useTransition","text":"useTransition","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-eaa4a0257f79","heading":"Responsive interactions › useTransition","text":"Purpose: Returns pending state and startTransition, which marks non-urgent state updates for interruptible background rendering.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cbffcdfe2fdf","heading":"Responsive interactions › useTransition","text":"When to use: You own the setter for costly tab content or a result view, while input feedback must remain urgent.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f2e89603891b","heading":"Responsive interactions › useTransition › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-486b9bdfd4d6","heading":"Responsive interactions › useTransition › Example","text":"// Fragment inside a tab component; tabs is the available tab list. const [tab, setTab] = useState('overview'); const [isPending, startTransition] = useTransition(); return ( \u003c> {tabs.map(next => ( \u003cbutton key={next} onClick={() => { startTransition(() => setTab(next)); }}>{next}\u003c/button> ))} \u003cdiv aria-busy={isPending}>\u003cTabContent tab={tab} />\u003c/div> \u003c/> );","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9e2e519e67ba","heading":"Responsive interactions › useTransition › Example","text":"Urgent interactions can interrupt transition rendering; isPending lets the UI communicate outstanding work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b5343bdb98e4","heading":"Responsive interactions › useTransition › Example","text":"When not to use & alternatives: Do not transition a controlled text input’s own value update. Use useDeferredValue when you receive a changing value rather than controlling its setter. Use task splitting/workers for long synchronous CPU work.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-54f3ad7da034","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2665f787fa95","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Benefits: Prioritizes interaction feedback and can preserve already-visible content during suspension.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8598700cd690","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Tradeoffs: Background rendering may restart, doing additional work; the pending state needs deliberate UX.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f220c4a8c9ba","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Pitfalls & guarantees: The callback begins immediately; it is not a timer or worker. React 19 supports async Actions, but updates after await currently need another startTransition to be transition updates. General async transitions do not guarantee request completion order; guard stale responses or use an action API with suitable queue semantics.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-33369fc827df","heading":"Responsive interactions › useTransition › Benefits & tradeoffs","text":"Related concepts: Deferring received values · Scheduling · Queued Actions · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-deferred-value-title","heading":"Responsive interactions › useDeferredValue","text":"useDeferredValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cae245169e84","heading":"Responsive interactions › useDeferredValue","text":"Purpose: Lets part of the UI render with an older value while React prepares the updated value in the background.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cf353483e5cb","heading":"Responsive interactions › useDeferredValue","text":"When to use: A fast input feeds an expensive result subtree and you want that subtree to catch up without blocking typing.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-aedb54bfce3e","heading":"Responsive interactions › useDeferredValue › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-209208515c13","heading":"Responsive interactions › useDeferredValue › Example","text":"function Search() { const [query, setQuery] = useState(''); const deferredQuery = useDeferredValue(query); return ( \u003c> \u003cinput aria-label=\"Search\" value={query} onChange={event => setQuery(event.target.value)} /> \u003cdiv style={{ opacity: query !== deferredQuery ? 0.6 : 1 }}> \u003cSlowResults query={deferredQuery} /> \u003c/div> \u003c/> ); } // SlowResults must be memoized or compiler-optimized appropriately.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-34826bbcdfb0","heading":"Responsive interactions › useDeferredValue › Example","text":"The input updates immediately. Isolating the costly subtree lets the unchanged deferred value skip its urgent render.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-71abb3dedf9f","heading":"Responsive interactions › useDeferredValue › Example","text":"When not to use & alternatives: Use debouncing to reduce request frequency; useTransition when you control the update. A cheap subtree does not need deferred rendering.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-65bc7e1f540d","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-0e05fa8645fe","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Benefits: Adaptive scheduling without choosing a fixed debounce delay; can keep stale results visible while loading.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fac2932704f7","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Tradeoffs: Users temporarily see stale data, and background renders may restart.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-599a7f893780","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Pitfalls & guarantees: It does not prevent a network request per keystroke or offload CPU work. Pass a stable value; a newly created object can cause unnecessary background renders. React 19 supports an optional initialValue for the initial client render; SSR ignores that argument during initial hydration.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-66c164df0b13","heading":"Responsive interactions › useDeferredValue › Benefits & tradeoffs","text":"Related concepts: Debouncing · Transitions · Suspense · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-forms-async","heading":"Actions, forms & async resources","text":"Actions, forms & async resources","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-action-state-title","heading":"Actions, forms & async resources › useActionState","text":"useActionState","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e5d73b5cc18d","heading":"Actions, forms & async resources › useActionState","text":"Purpose: Tracks an Action’s returned state and pending status, with queued dispatches through the same hook. Returns state, dispatchAction, and isPending.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-22f4ef188884","heading":"Actions, forms & async resources › useActionState","text":"When to use: A form submission returns validation errors or a result needed by the UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7fa2aea8ec2","heading":"Actions, forms & async resources › useActionState › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a72e48b0e1ac","heading":"Actions, forms & async resources › useActionState › Example","text":"async function saveProfile(previousState, formData) { // Application API: returns { error: string | null }. return profileApi.save({ name: formData.get('name') }); } function ProfileForm() { const [state, formAction, isPending] = useActionState( saveProfile, { error: null } ); return ( \u003cform action={formAction} aria-busy={isPending}> \u003clabel>Name \u003cinput name=\"name\" required />\u003c/label> \u003cbutton disabled={isPending}>Save\u003c/button> {state.error && \u003cp role=\"alert\">{state.error}\u003c/p>} \u003c/form> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-08975ce30a87","heading":"Actions, forms & async resources › useActionState › Example","text":"The form establishes the Action context. The action receives previousState before its form payload and returns the next UI state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-3ccc9d7f1ad6","heading":"Actions, forms & async resources › useActionState › Example","text":"When not to use & alternatives: For trivial synchronous state use useState. For server-state caching, invalidation, and retries, or complex form validation, use an appropriate query/form abstraction rather than expecting this hook to supply those features.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fb87a8f64f74","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-86c82e3ca21f","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Benefits: Combines action results, queueing, and pending state without manual coordination.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-afabc095df1b","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Tradeoffs: Adds an Action-specific signature and semantics; queueing can delay later submissions.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ae29a5c5faf","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Pitfalls & guarantees: Manual dispatch needs an appropriate Action/transition context. Represent expected validation failures in state; thrown failures need error handling, such as an Error Boundary. A React Action is not automatically a Server Function. The optional permalink argument supports specific progressive-enhancement flows with Server Functions; framework support and matching action identity matter.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-09f51ad55f05","heading":"Actions, forms & async resources › useActionState › Benefits & tradeoffs","text":"Related concepts: Form-scoped pending UI · Server authorization · CSRF protections · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-form-status-title","heading":"Actions, forms & async resources › useFormStatus","text":"useFormStatus","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-90f7b82cb98f","heading":"Actions, forms & async resources › useFormStatus","text":"Purpose: Reads the nearest parent form’s submission status and submitted data from a descendant. Import it from react-dom.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-eae808f73e09","heading":"Actions, forms & async resources › useFormStatus","text":"When to use: A reusable submit button or status indicator should work without passing pending state through every layer.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1e01a9bd5261","heading":"Actions, forms & async resources › useFormStatus › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c7a51dded37b","heading":"Actions, forms & async resources › useFormStatus › Example","text":"import { useFormStatus } from 'react-dom'; function SubmitButton() { const { pending } = useFormStatus(); return \u003cbutton disabled={pending}>{pending ? 'Saving…' : 'Save'}\u003c/button>; } // Render \u003cSubmitButton /> inside ProfileForm's \u003cform> above, // replacing its ordinary submit button.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-195953d11b1b","heading":"Actions, forms & async resources › useFormStatus › Example","text":"The descendant subscribes to the containing form; it does not need to know which action implementation is used.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-bd2be8416824","heading":"Actions, forms & async resources › useFormStatus › Example","text":"When not to use & alternatives: Use useActionState’s isPending when the form-owning component needs that action’s status, or explicit props for a non-form async button.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-afba760ffd32","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-150d7ea69648","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Benefits: Encapsulates form-aware presentation and removes pending-state prop drilling.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-408a2444ed53","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Tradeoffs: Couples the consumer to a parent form; placement determines which submission it observes.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f818c5e13040","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Pitfalls & guarantees: It cannot read a form merely returned by the same component, or an unrelated/sibling form. Besides pending, it exposes data, method, and action for the relevant submission. Do not assume it observes arbitrary fetches outside the form’s action lifecycle.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8954f672a030","heading":"Actions, forms & async resources › useFormStatus › Benefits & tradeoffs","text":"Related concepts: Complete form example · Containment and composition · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-optimistic-title","heading":"Actions, forms & async resources › useOptimistic","text":"useOptimistic","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2d8db08bfe38","heading":"Actions, forms & async resources › useOptimistic","text":"Purpose: Layers temporary speculative state over authoritative base state while an Action is pending.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-7b4df1db4070","heading":"Actions, forms & async resources › useOptimistic","text":"When to use: A comment, reaction, or toggle should feel immediate before a server confirms the change.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7d443b177e4","heading":"Actions, forms & async resources › useOptimistic › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-12faba2ca0ce","heading":"Actions, forms & async resources › useOptimistic › Example","text":"// Fragment inside a component. saveLikes is an application API. const [likes, setLikes] = useState(initialLikes); const [optimisticLikes, addOptimisticLike] = useOptimistic( likes, (current, amount) => current + amount ); const [isPending, startTransition] = useTransition(); function like() { startTransition(async () => { addOptimisticLike(1); try { const confirmedLikes = await saveLikes(); startTransition(() => setLikes(confirmedLikes)); } catch (error) { reportError(error); // Application-level failure feedback. } }); } return \u003cbutton disabled={isPending} onClick={like}>{optimisticLikes}\u003c/button>;","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e145d948be80","heading":"Actions, forms & async resources › useOptimistic › Example","text":"The speculative increment is visible immediately. Success updates the base value; failure leaves the base unchanged once the Action finishes.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e36cc33e51dd","heading":"Actions, forms & async resources › useOptimistic › Example","text":"When not to use & alternatives: Use a pending indicator when failure is common or the operation is irreversible/high impact. A query library’s optimistic mutation support may better coordinate an existing server-state cache; see mutation reconciliation.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-b619888b290d","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-dbf3bd8faa3f","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Benefits: Reduces perceived latency and centralizes reconciliation over a base value.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fecd831d3844","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Tradeoffs: Requires a credible rollback/failure experience and careful ordering when mutations overlap.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6835125e0ef8","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Pitfalls & guarantees: Dispatch optimistic updates in an Action/transition; keep updateFn pure. Commit confirmed data to base state, handle server-generated IDs, and avoid duplicates. Optimistic state is temporary, not durable. This example disables overlapping clicks; multi-request workflows need an explicit ordering policy.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-164b789015ae","heading":"Actions, forms & async resources › useOptimistic › Benefits & tradeoffs","text":"Related concepts: Action lifetime · Transition guards · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-title","heading":"Actions, forms & async resources › use","text":"use","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2fb231702262","heading":"Actions, forms & async resources › use","text":"Purpose: Reads a supported Promise or context during rendering. Pending Promises suspend; rejected Promises reach an Error Boundary.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-018bf37b6b6c","heading":"Actions, forms & async resources › use","text":"When to use: A Suspense-compatible framework/cache supplies a stable Promise, or conditional context reading fits the component.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fb497a17877a","heading":"Actions, forms & async resources › use › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4b77e6695cb9","heading":"Actions, forms & async resources › use › Example","text":"function ProductDetails({ productPromise }) { const product = use(productPromise); return \u003ch2>{product.name}\u003c/h2>; } // Parent: \u003cSuspense fallback={\u003cp>Loading…\u003c/p>}> // \u003cProductDetails productPromise={stablePromise} /> // \u003c/Suspense> // Provide an Error Boundary for rejected resources.","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-75f14e3390fa","heading":"Actions, forms & async resources › use › Example","text":"The Promise is supplied rather than recreated during every client render. Suspense owns the pending UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ce559344fdf8","heading":"Actions, forms & async resources › use › Example","text":"When not to use & alternatives: Prefer await inside async Server Components when it fits. Use a query library/framework for resource ownership; use does not supply caching, invalidation, cancellation, or a fetch trigger by itself.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2c2173b2c81f","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ff9566f9779e","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Benefits: Integrates async reads with Suspense and can read context conditionally.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a9194b01e897","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Tradeoffs: Requires a resource-lifetime strategy plus loading/error boundaries.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-fba00516fba5","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Pitfalls & guarantees: Unlike ordinary hooks, use can appear in loops and conditions, but still only inside components/hooks. Do not wrap Promise reads in try/catch. Fresh uncached client-render Promises are unsupported; obtain stable resources from an appropriate cache/framework. Do not confuse use with useEffect: a resource read is not a render side effect.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-748b38858d5c","heading":"Actions, forms & async resources › use › Benefits & tradeoffs","text":"Related concepts: Suspense and streaming · Server vs. Client Components · Caching · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-supporting","heading":"Accessibility & diagnostics","text":"Accessibility & diagnostics","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-id-title","heading":"Accessibility & diagnostics › useId","text":"useId","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5d72901922e9","heading":"Accessibility & diagnostics › useId","text":"Purpose: Generates an ID suitable for relationships between elements, including consistent SSR/hydration identities.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8d85881a5ddd","heading":"Accessibility & diagnostics › useId","text":"When to use: Reusable fields need unique label/input or description/input associations across multiple instances.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a6e7c142b51f","heading":"Accessibility & diagnostics › useId › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-39b4b8098c5a","heading":"Accessibility & diagnostics › useId › Example","text":"function EmailField() { const id = useId(); return ( \u003c> \u003clabel htmlFor={id}>Email\u003c/label> \u003cinput id={id} type=\"email\" aria-describedby={id + '-help'} /> \u003cp id={id + '-help'}>Use your work email.\u003c/p> \u003c/> ); }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-154ad01b2be7","heading":"Accessibility & diagnostics › useId › Example","text":"One generated ID can derive related IDs without hard-coded collisions between field instances.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2f45b1af5c2f","heading":"Accessibility & diagnostics › useId › Example","text":"When not to use & alternatives: Use data-derived stable keys for lists, database identifiers for records, and domain keys for caches. A fixed ID only fits a guaranteed singleton.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-6912ae940ae8","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4bbcdb7ab5c0","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Benefits: Supports reusable accessible markup and coordinated server/client rendering.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e06c547bb694","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Tradeoffs: IDs depend on React’s tree coordination and are not portable business identifiers.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-9b18e75eaf39","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Pitfalls & guarantees: Do not call it inside a list loop; extract a field component per instance. Multiple independent roots may need coordinated identifierPrefix values. Server and client trees must match; useId does not fix arbitrary hydration mismatches. It is not currently supported in async Server Components.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-38a852ff1965","heading":"Accessibility & diagnostics › useId › Benefits & tradeoffs","text":"Related concepts: Accessibility contracts · Hydration · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-use-debug-value-title","heading":"Accessibility & diagnostics › useDebugValue","text":"useDebugValue","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f20c91010d16","heading":"Accessibility & diagnostics › useDebugValue","text":"Purpose: Adds a diagnostic label for a custom hook in React DevTools without changing its rendered UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-04d4c7e966fa","heading":"Accessibility & diagnostics › useDebugValue","text":"When to use: A reusable library/domain hook exposes a useful internal state such as connection status or cache freshness.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-f4c692664422","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-75a80779c4c6","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"function useDebuggedOnlineStatus() { const online = useOnlineStatus(); // Shared domain hook, implemented elsewhere. useDebugValue(online, value => value ? 'Online' : 'Offline'); return online; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5c6f7757367a","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"The formatter produces an inspection label; this snippet illustrates diagnostics, not a second subscription implementation.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-573565d0809c","heading":"Accessibility & diagnostics › useDebugValue › Example","text":"When not to use & alternatives: Use application logging/telemetry for production diagnostics and the Profiler for timing. Simple local hooks may not need custom labels.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2ca8acf804b4","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ce3b610a1eb4","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Benefits: Makes reusable abstractions easier to inspect; an optional formatter defers label-formatting work until inspection.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ef66b139da31","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Tradeoffs: Only benefits inspection and can clutter DevTools if used indiscriminately.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4e8212622e72","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Pitfalls & guarantees: Keep formatting pure. Do not perform expensive work before passing the value if it can live in the formatter. Labels do not measure performance and should not be relied on for application behavior.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2418a423541d","heading":"Accessibility & diagnostics › useDebugValue › Benefits & tradeoffs","text":"Related concepts: Custom hook design · Profiler and timing tools · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-custom","heading":"Custom hooks","text":"Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hook-custom-hooks-title","heading":"Custom hooks › Custom hooks","text":"Custom hooks","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-afd35545bd7e","heading":"Custom hooks › Custom hooks","text":"Purpose: Functions named use… compose hooks into a coherent reusable capability. Each call has independent state unless it explicitly consumes Context or an external store.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-c95b9178c7b4","heading":"Custom hooks › Custom hooks","text":"When to use: Several components share a behavior with a meaningful lifecycle and API, such as a debounced value, browser subscription, or domain operation.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-052143033a88","heading":"Custom hooks › Custom hooks › Example","text":"Example","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2e828a43365f","heading":"Custom hooks › Custom hooks › Example","text":"function useDebouncedValue(value, delayMs) { const [debouncedValue, setDebouncedValue] = useState(value); useEffect(() => { const timer = setTimeout(() => setDebouncedValue(value), delayMs); return () => clearTimeout(timer); }, [value, delayMs]); return debouncedValue; }","kind":"Code"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-376c0c38b4ad","heading":"Custom hooks › Custom hooks › Example","text":"The initial value is immediate; subsequent changes use trailing-edge debouncing. Value/delay changes restart the timer, and cleanup prevents an obsolete timer from committing.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-990e788d9479","heading":"Custom hooks › Custom hooks › Example","text":"When not to use & alternatives: Use an ordinary utility function for pure non-hook logic. Do not extract merely to hide lines or create useMount wrappers that conceal dependencies. Use Context/store ownership when callers actually need shared state.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-64d3f25a519f","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Benefits & tradeoffs","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a1f897ea2f05","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Benefits: Reuses lifecycle logic, hides implementation details, and exposes a testable domain contract.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2f33764e71f5","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Tradeoffs: An overly generic API hides dependencies, introduces naming/return-shape commitments, and can obscure state ownership.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-1f5bf52d533b","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Pitfalls & guarantees: Document callback stability, return values, errors, cancellation, and controlled/uncontrolled behavior. Debouncing does not cancel an already-started request. Test observable behavior under changed inputs, cleanup, unmount, failures, and obsolete completions; do not assert incidental render counts.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-ce68000dee47","heading":"Custom hooks › Custom hooks › Benefits & tradeoffs","text":"Related concepts: Debouncing · Cancellation · Domain consumers · Headless APIs · Hook index","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-custom-variants","heading":"Custom hooks › Custom hook API variations","text":"Custom hook API variations","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-a3269e8ae8ad","heading":"Custom hooks › Custom hook API variations","text":"Value hooks: Return a focused value or tuple; define initial and subsequent behavior.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-5cd1e5f8ecb7","heading":"Custom hooks › Custom hook API variations","text":"Subscription hooks: Own setup/teardown; use useSyncExternalStore when an external source of truth needs consistent snapshots.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-debea77cf372","heading":"Custom hooks › Custom hook API variations","text":"Domain hooks: Expose meaningful state/actions with provider checks and narrow subscriptions; see Context consumer hooks.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-8e6aaae619fa","heading":"Custom hooks › Custom hook API variations","text":"Headless hooks: Return actions, refs, or prop getters while the caller owns markup. Document accessibility, adapters, and event-handler composition.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"hooks-review","heading":"Interview-ready decision process","text":"Interview-ready decision process","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-e7dfe51ba844","heading":"Interview-ready decision process","text":"Who owns the state? Distinguish client ownership from a remote source of truth, then choose local state, Context, a query cache, or another store.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-cdd2f4c03183","heading":"Interview-ready decision process","text":"Is this derived data, an event, or synchronization? Calculate during render, act in a handler, or synchronize with an effect accordingly.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-62bdaa5a2dce","heading":"Interview-ready decision process","text":"Does it need to block paint or be urgent? Reserve layout effects for pre-paint work; transitions for non-urgent UI.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4aaf216cb3ff","heading":"Interview-ready decision process","text":"What is the lifecycle contract? Specify dependencies, cleanup, cancellation, snapshots, and race handling.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-2f65c25a695a","heading":"Interview-ready decision process","text":"What evidence justifies optimization? Use profiling before relying on memoization, and keep correctness independent of caches.","kind":"Notes"},{"page":"react-hooks.html","topic":"React Hooks","anchor":"search-4135c24eb33a","heading":"Interview-ready decision process","text":"References: React built-in hooks, use API, useFormStatus, and custom hook design.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-rendering-title","heading":"","text":"React Rendering: Updates, Strategies & Hydration","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f382e078a156","heading":"","text":"Start with how React computes and commits updates, preserves identity, and schedules work. Then follow initial HTML delivery, hydration, Server Components, and streaming.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5b29791ce3d3","heading":"","text":"Core idea: SSR determines how initial HTML is produced; RSC determines which component code stays on the server; hydration connects browser-side React to server-rendered HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c6065ac331fa","heading":"","text":"The big picture","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-33ea11466b24","heading":"","text":"React updates: render, reconciliation & commit","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e6c53e10d097","heading":"","text":"CSR vs traditional SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-98d978807363","heading":"","text":"Hydration","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d5b64eebdaea","heading":"","text":"React Server Components (RSC) vs Client Components","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bc6957c5c686","heading":"","text":"Streaming SSR and Suspense","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-604c1c9f615d","heading":"","text":"How RSC, SSR, and hydration fit together","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d455a747d1b9","heading":"","text":"Error boundaries: isolate rendering failures","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-45ba6cff0eb3","heading":"","text":"Choosing an approach","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-884397c1e592","heading":"","text":"Interview-ready answer","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-big-picture","heading":"The big picture","text":"The big picture","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-92c451060d03","heading":"The big picture","text":"ConceptWhat it solvesMain idea","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3055de577681","heading":"The big picture","text":"CSR (Client-Side Rendering)Where UI is initially renderedBrowser executes React and creates the DOM.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-58f7dc4c637b","heading":"The big picture","text":"SSR (Server-Side Rendering)How initial HTML is deliveredServer renders HTML before the browser runs React.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-2aadaa5deec0","heading":"The big picture","text":"Streaming SSRWhen pieces of HTML arriveServer sends ready HTML in chunks, often around Suspense boundaries.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1f1fafb133a7","heading":"The big picture","text":"RSC (React Server Components)Where component code executesServer Components run only on the server; their implementation JS isn't sent to the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8d6ef61b461a","heading":"The big picture","text":"HydrationHow server HTML becomes interactiveReact attaches its client-side tree and behavior to existing HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ad882b421119","heading":"The big picture","text":"Two different decisions:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-939089072a2e","heading":"The big picture","text":"Rendering strategy and component boundariesRendering strategyCSR or SSRWhere the initial application UI is rendered.Component execution boundaryServer or Client ComponentWhich component implementations execute in the browser.These are independent decisions: a page can combine Server Components, Client Components, and SSR.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-b7d2b390a3ac","heading":"The big picture","text":"RSC and SSR are not alternatives. A framework such as Next.js can use both on the same page.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-update-cycle","heading":"React updates: render, reconciliation & commit","text":"React updates: render, reconciliation & commit","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fa03782a56bf","heading":"React updates: render, reconciliation & commit","text":"Trigger → render → commit: An initial root render or a state update schedules work. During render, React calls components to calculate the next UI and performs reconciliation: matching new elements against the previous tree to determine what can be preserved and which changes are needed. Rendering a component does not necessarily change the DOM.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-098733005c7e","heading":"React updates: render, reconciliation & commit","text":"Render phase: Must remain pure. Do not mutate external data, send requests, or subscribe while rendering. React may restart or discard this work, so a render is not proof that the UI appeared.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-77cedcc52fcd","heading":"React updates: render, reconciliation & commit","text":"Commit phase: React applies the selected tree’s DOM changes and attaches refs. Layout effects run before the browser repaints; passive effects synchronize external systems after commit, with timing dependent on the interaction. See effect timing and cleanup.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-087bfef23912","heading":"React updates: render, reconciliation & commit","text":"Diagnosis: Distinguish component execution, DOM mutations, and browser layout/paint. They are separate costs; use the React Profiler and browser performance trace together.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-identity-keys","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Component identity & keys: preserve or reset state deliberately","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d81fb9bcf556","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"State belongs to a component’s position in React’s tree, identified by element type and, where supplied, its key within the parent. Matching identity preserves state; removing a component or changing its type/key resets its subtree, including effects and uncontrolled input values.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-76f9bf3abd55","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"// Stable domain IDs preserve each row's state when sorting or inserting. products.map(product => \u003cProductRow key={product.id} product={product} />); // A different account should receive a fresh local editing draft. \u003cProfileEditor key={account.id} initialProfile={account} />;","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1eab62dc3521","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Use stable sibling-unique IDs: Keys need not be globally unique and are not passed as ordinary props. Pass a separate id prop when the child needs it.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-305c6d470f97","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Avoid index keys for changing lists: Insertion, deletion, or sorting can attach state to the wrong record. Random keys remount everything on every render. Keys do not prevent rerenders and cannot preserve state across arbitrary parent changes.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d23efacb547f","heading":"React updates: render, reconciliation & commit › Component identity & keys: preserve or reset state deliberately","text":"Intentional reset: Key an editor by record identity when switching records should reset it. Do not key by each server version unless losing unsaved edits is intended; see server snapshots and local drafts.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-batching","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"Automatic batching & state update queues","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-46e26273f016","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"With modern createRoot roots, React automatically batches updates from handlers and asynchronous callbacks such as promises and timers, reducing separate renders. Each render still observes a fixed state snapshot; a setter queues an update rather than changing the current variable.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6ed371346cac","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"// Starting at 0, these request the same next value: the result is 1. setCount(count + 1); setCount(count + 1); // Functional updaters compose: starting at 0, the result is 2. setCount(c => c + 1); setCount(c => c + 1);","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e1f02c699cad","heading":"React updates: render, reconciliation & commit › Automatic batching & state update queues","text":"Batching does not combine distinct intentional user events into one transaction, and it is not a server transaction guarantee. Updaters must be pure. Use flushSync from react-dom sparingly for integrations that require the DOM to update before the next statement; it can hurt performance. For previous-state calculations, prefer functional state updates.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-concurrent","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Concurrent rendering: prioritize responsiveness","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-44b637c5a976","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Concurrent rendering lets React interrupt, restart, or discard eligible render work before committing it. This is cooperative scheduling on the JavaScript thread, not parallel component execution. The commit’s DOM mutation work is synchronous; users do not see a partially applied React tree from an interrupted render.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-66a7804131be","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Use case: Keep a search input update urgent while marking an expensive results update as a transition. Use useTransition for an update you control, or useDeferredValue to let a consumed value lag behind.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7c2441c88e96","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Limits: A transition does not debounce requests, make computation faster, or interrupt a single long synchronous calculation inside your function. Split that calculation or use a Web Worker.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-99c9354c6245","heading":"React updates: render, reconciliation & commit › Concurrent rendering: prioritize responsiveness","text":"Correctness: Pure renders and useSyncExternalStore help React work with consistent snapshots. Suspense can coordinate pending UI; transition scheduling does not order overlapping network mutations.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-csr-ssr","heading":"CSR vs traditional SSR","text":"CSR vs traditional SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-0dedd61819ac","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"Client-Side Rendering (CSR)","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-543bfee91977","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"Client-side rendering: from request to interactivityRequestThe browser requests the application.HTML shellAn initial document provides the root container.Download JavaScriptLoad the application bundle.Run ReactExecute the component tree in the browser.Create the DOMReact commits the application content.Interactive UIThe rendered controls can respond to input.The browser creates the application content. There is no server-rendered React DOM to hydrate in this example.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-027a1abed951","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"The initial HTML might contain only \u003cdiv id=\"root\">\u003c/div>. React creates the content in the browser:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fc05cb236cba","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"import { createRoot } from 'react-dom/client'; createRoot(document.getElementById('root')!).render(\u003cCounter />);","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-455815f72682","heading":"CSR vs traditional SSR › Client-Side Rendering (CSR)","text":"There is no hydration because there is no pre-existing React-rendered DOM to reuse.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3a4bd5997af9","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"Server-Side Rendering (SSR)","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-228d2f219ec9","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"Server-side rendering: visibility before interactivityRequestThe browser requests the page.Server renders ReactGenerate initial HTML on the server.HTML arrivesThe browser displays the server-rendered content.Visible UIContent such as Count: 0 is already on screen.Interactive UIDownload client JavaScript, then hydrate the client tree so React interactions work.Visibility and React interactivity have separate milestones; JavaScript may download in parallel with HTML delivery.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-eced62434440","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"The server might send \u003cbutton>Count: 0\u003c/button> before the browser has loaded the JavaScript needed to make the button work.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7325c9e0c70f","heading":"CSR vs traditional SSR › Server-Side Rendering (SSR)","text":"Important: In traditional React SSR, client-capable component code is generally also shipped to the browser. The server render improves initial HTML delivery but does not eliminate browser-side React.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ba26e2f030c3","heading":"CSR vs traditional SSR › Quick comparison","text":"Quick comparison","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-802466d953d1","heading":"CSR vs traditional SSR › Quick comparison","text":"AspectCSRTraditional SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bf36070d549e","heading":"CSR vs traditional SSR › Quick comparison","text":"Initial application HTMLGenerated in browserGenerated on server","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8d94e7b2a6a4","heading":"CSR vs traditional SSR › Quick comparison","text":"Content visible before application JS executesUsually noOften yes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e183ad0c3a73","heading":"CSR vs traditional SSR › Quick comparison","text":"HydrationNoYes, for client React tree","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-2d92645f1515","heading":"CSR vs traditional SSR › Quick comparison","text":"Browser JS needed for interactivityYesYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-hydration","heading":"Hydration","text":"Hydration","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5ae4a429c1cf","heading":"Hydration","text":"Hydration is React connecting client-side component logic to HTML that already exists in the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1ca97eea174c","heading":"Hydration","text":"import { useState } from 'react'; function Counter() { const [count, setCount] = useState(0); return ( \u003cbutton onClick={() => setCount(c => c + 1)}> Count: {count} \u003c/button> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-549ec46c8e13","heading":"Hydration","text":"Server output:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c90929df9c16","heading":"Hydration","text":"\u003cdiv id=\"root\">\u003cbutton>Count: 0\u003c/button>\u003c/div>","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3e00f4221415","heading":"Hydration","text":"Browser hydration:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e8324a1ce4c8","heading":"Hydration","text":"import { hydrateRoot } from 'react-dom/client'; hydrateRoot(document.getElementById('root')!, \u003cCounter />);","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c68efc1c8da2","heading":"Hydration","text":"Hydration: reuse existing HTMLServer HTML is visibleThe browser shows Count: 0; its React click handler is not active yet.Client React hydratesExecute browser-side component logic and connect it to the existing DOM.State updates workClicking the existing button updates its count.Hydration reuses server-rendered markup. The server and client must agree on the initial output.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5a91cb115836","heading":"Hydration › Hydration mismatch","text":"Hydration mismatch","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-caf84b0b9748","heading":"Hydration › Hydration mismatch","text":"Server and browser should produce the same initial output. This can fail:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-df1729f9dce2","heading":"Hydration › Hydration mismatch","text":"function RandomValue() { return \u003cdiv>{Math.random()}\u003c/div>; }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a0fa30680f46","heading":"Hydration › Hydration mismatch","text":"The server might render 0.42 while the client initially renders 0.81. Avoid nondeterministic values in initial rendering, or defer browser-only values until after hydration. See effect setup and cleanup for an example of browser-side work.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e60d2c96d89b","heading":"Hydration › Hydration mismatch","text":"Remember: In the browser, React’s render phase computes the next UI tree; reconciliation compares trees, and the commit phase applies DOM changes. SSR produces HTML; hydration reuses that HTML while connecting client-side React logic.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-components","heading":"React Server Components (RSC) vs Client Components","text":"React Server Components (RSC) vs Client Components","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6ff70b9c23d9","heading":"React Server Components (RSC) vs Client Components","text":"Async vs. synchronous components: A synchronous function component returns a React node (often JSX, but also text, null, or other supported values). An async component returns a Promise and can use await during rendering. Server Components support both forms; Client Components cannot be async functions. An async handler still follows event-loop scheduling; async does not move CPU work off the main thread.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1eaae7bfbaa2","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Server Component","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5b9bc48c7109","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"// Server Component, for example in Next.js App Router async function ProductInfo() { const product = await db.getProduct(); return \u003ch1>{product.name}\u003c/h1>; }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-cc5d75a35e3a","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Runs only on the server.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-e453ed72d538","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Can fetch data and access databases and server-side secrets directly. Keep secrets out of rendered output and props sent to Client Components. Server-state ownership is independent of component execution location. Server execution also does not replace authentication and authorization.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ab3d0a5d6c7e","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Can be async and await data during rendering, as in the example above.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a38ed916ed0b","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Its component implementation JavaScript is not shipped to the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5f8d0760f98e","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Is never hydrated.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f64a2a26b349","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Cannot use useState, useEffect, or browser event handlers.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-17aab697e09a","heading":"React Server Components (RSC) vs Client Components › Server Component","text":"Nuance: RSC rendering produces a serialized RSC/Flight payload, not simply an HTML string. SSR can use the resulting tree to produce initial HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f5a8b68851d2","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"Client Component","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7667dec4943f","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"'use client'; import { useState } from 'react'; function LikeButton() { const [liked, setLiked] = useState(false); return ( \u003cbutton onClick={() => setLiked(true)}> {liked ? 'Liked' : 'Like'} \u003c/button> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-177e1679fb63","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"Its JavaScript is shipped to the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-2b163ff771de","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"Can use useState, useEffect, and event handlers. Access browser APIs in effects or handlers, since initial rendering may run on the server.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-13359388f581","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"The component itself must be synchronous, but event handlers can be async. Effects can start async work inside an inner function; the useEffect callback itself must not be async, because it must return either a cleanup function or nothing, not a Promise.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-68fb510d264e","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"Can also be rendered to HTML on the server on the initial request.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-35fb8ce47e5b","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"If server-rendered, it is subsequently hydrated.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-3c75ee6bdc4d","heading":"React Server Components (RSC) vs Client Components › Client Component","text":"'use client' does not mean “render only in the browser.” It marks a module dependency boundary: the module and its transitive imports enter the client module graph. A Client Component can still participate in initial SSR. See children and composition patterns for UI composition; the module boundary is a separate concern.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-49cc5f41aaf1","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"Side-by-side","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a067acbab239","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"AspectServer ComponentClient Component with initial SSR","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-44196943828b","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"Runs on serverYesYes, for initial HTML","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1f73ac16d4ab","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"Contributes to initial HTMLYesYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-daec4b99825e","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"Component implementation JS shippedNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-79e25f01f0fb","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"Executes in browserNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-7ff35500d35e","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"HydratedNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1d6dbb67feac","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"useState / onClickNoYes","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-90dac0511763","heading":"React Server Components (RSC) vs Client Components › Side-by-side","text":"Direct database accessYesNo, keep DB code server-side","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-streaming","heading":"Streaming SSR and Suspense","text":"Streaming SSR and Suspense","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-b049da3753c7","heading":"Streaming SSR and Suspense","text":"Traditional SSR may wait for a slow section before sending the full page. Streaming SSR lets the server send ready sections earlier.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-20a98fe87885","heading":"Streaming SSR and Suspense","text":"import { Suspense } from 'react'; function ProductPage() { return ( \u003c> \u003cHeader /> \u003cProductDetails /> \u003cSuspense fallback={\u003cReviewsSkeleton />}> \u003cReviews /> \u003c/Suspense> \u003c/> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d6dbe883fdd4","heading":"Streaming SSR and Suspense","text":"Illustrative timeline:","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-fdb9ebdcf592","heading":"Streaming SSR and Suspense","text":"Streaming SSR: a progressive delivery timeline0 msServerHeader and product are ready; reviews are still loading. Send HTML chunk 1.BrowserShow the header, product, and reviews skeleton.~500 msServerReviews are still pending.BrowserClient JavaScript is available; hydration may begin for ready interactive parts.2000 msServerReviews finish. Send HTML chunk 2.BrowserReviews replace the skeleton. Interactive parts can hydrate.Illustrative timings. Both HTML chunks travel through the same HTTP response; streaming and hydration can overlap.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-76d7f05e7718","heading":"Streaming SSR and Suspense","text":"The chunks travel through the same HTTP response. Suspense boundaries help React isolate content that is not ready. Selective hydration lets React hydrate Suspense boundaries independently and prioritise boundaries the user interacts with. Hydration can overlap with streaming rather than waiting for the whole page. The data source must support Suspense; fetching inside useEffect does not trigger a Suspense fallback.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-86f25b6ef050","heading":"Streaming SSR and Suspense","text":"Distinction: Streaming controls when HTML arrives; hydration controls when browser-side React becomes active.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-473fe748c902","heading":"Streaming SSR and Suspense","text":"For state, effects, refs, and async APIs within these execution boundaries, see React Hooks.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-lifecycle","heading":"How RSC, SSR, and hydration fit together","text":"How RSC, SSR, and hydration fit together","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-129dbb5d2f68","heading":"How RSC, SSR, and hydration fit together","text":"// Server Component async function ProductPage() { const product = await db.getProduct(); return ( \u003c> \u003ch1>{product.name}\u003c/h1> \u003cLikeButton /> \u003c/> ); }","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8319309b5c97","heading":"How RSC, SSR, and hydration fit together","text":"Combine the two: ProductPage handles server-side data fetching, while LikeButton, the Client Component from the component-boundary example, handles interactive state.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5d5361d9f655","heading":"How RSC, SSR, and hydration fit together › Initial page load","text":"Initial page load","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a7663d01236a","heading":"How RSC, SSR, and hydration fit together › Initial page load","text":"Initial page load: RSC, SSR, and hydration togetherOn the serverExecute ProductPageThe Server Component fetches the product.Produce the RSC payloadSerialize the result, including a reference to the LikeButton Client Component.Render initial HTML with SSRInclude both the product heading and LikeButton markup.Browser displays the pageMacBook Pro and the Like button are visible.ProductPage · Server ComponentImplementation JavaScript stays on the server. This component is not hydrated.LikeButton · Client ComponentSend its JavaScript to the browser, execute it, and hydrate. The Like interaction now works.Both component types contribute to initial HTML, while the Client Component supplies browser-side interaction logic.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-a9f9691222f3","heading":"How RSC, SSR, and hydration fit together › Subsequent client-side navigation","text":"Subsequent client-side navigation","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-25d1c384a4de","heading":"How RSC, SSR, and hydration fit together › Subsequent client-side navigation","text":"Client-side navigation with Server ComponentsNavigate to /products/2The framework handles a client-side navigation.Execute Server ComponentsThe server renders the next product’s component result.Return the RSC payloadSend the new serialized component result.Reconcile in the browserReact updates the existing UI using the new result.A client-side navigation does not necessarily download a new full HTML document. RSC updates do not require SSR on every navigation.","kind":"Diagram"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bc8866b6723f","heading":"How RSC, SSR, and hydration fit together › Subsequent client-side navigation","text":"A new full HTML document is not necessarily generated or downloaded on each client-side navigation. This is why RSC does not require SSR for every update.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-error-boundaries","heading":"Error boundaries: isolate rendering failures","text":"Error boundaries: isolate rendering failures","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-551f7b0f8553","heading":"Error boundaries: isolate rendering failures","text":"Purpose: Replace a failed React subtree with a fallback while preserving useful surrounding UI. Choose boundaries by independent recovery and user tasks, not automatically around every component.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-6d4d7f9ea4f6","heading":"Error boundaries: isolate rendering failures","text":"Example: Put recommendations behind a boundary so a rendering exception does not remove product details and the purchase controls. Keep a broader route boundary for failures that make the route unusable.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-df3f65b5c6fc","heading":"Error boundaries: isolate rendering failures","text":"import { Component } from 'react'; class ErrorBoundary extends Component { state = { failed: false }; static getDerivedStateFromError() { return { failed: true }; } componentDidCatch(error, info) { // Send error and component stack to the application's reporting service. } render() { return this.state.failed ? this.props.fallback : this.props.children; } } // Usage: \u003cErrorBoundary fallback={\u003cp>Recommendations unavailable.\u003c/p>}> // \u003cRecommendations /> // \u003c/ErrorBoundary>","kind":"Code"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-4b81b040e0ba","heading":"Error boundaries: isolate rendering failures","text":"Scope: Boundaries catch descendant rendering, constructor, and lifecycle errors. They do not catch their own errors, ordinary event-handler exceptions, arbitrary rejected promises/timer callbacks, or the server render itself. Handle request errors through the data layer and event failures with explicit error handling. Suspense-enabled render reads can surface errors to a boundary through their integration.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-01b8838e5708","heading":"Error boundaries: isolate rendering failures","text":"Use when: A route or widget can fail independently and has a meaningful fallback. A framework’s route error handling or a maintained boundary library often supplies reset/reporting integration. React has no built-in function-component error-boundary hook.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ca29c6484229","heading":"Error boundaries: isolate rendering failures","text":"Benefits and tradeoffs: Limits UI failure scope and improves diagnostics. Too many boundaries can conceal broken workflows behind generic messages; never imply a purchase succeeded because its UI failed. Define reset behavior when the resource changes or the user retries; a remount via a changed key resets subtree state but cannot repair invalid data.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-57dcb3ce2abd","heading":"Error boundaries: isolate rendering failures","text":"Compare: Suspense handles supported pending rendering; error boundaries handle rendering failure. Neither is a retry policy or circuit breaker. Request timeouts and server failure containment address different layers.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-choices","heading":"Choosing an approach","text":"Choosing an approach","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-da1a066ac4da","heading":"Choosing an approach","text":"CSR: Useful for highly interactive applications where server-rendered initial HTML is not important.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-1f7e6c1eecbd","heading":"Choosing an approach","text":"SSR: Useful when the first response should already contain meaningful HTML, including for content visibility and SEO.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-b363c19bfdd6","heading":"Choosing an approach","text":"Streaming SSR: Useful when parts of a page depend on slow data and can be separated with Suspense.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-f15dc347e24c","heading":"Choosing an approach","text":"Server Components: Good default for server data fetching, non-interactive UI, and keeping implementation JS out of the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-54d39523d46d","heading":"Choosing an approach","text":"Client Components: Needed for local interactive state, effects, browser APIs, and event handlers.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-bcb51c95d37a","heading":"Choosing an approach","text":"In Next.js App Router, a practical default is to use Server Components for server-only work and add Client Components at interactive boundaries, while letting SSR produce the initial page HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"react-review","heading":"Interview-ready answer","text":"Interview-ready answer","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-5b1357d79d42","heading":"Interview-ready answer","text":"CSR creates the UI in the browser. SSR generates initial HTML on the server and then hydrates client-side React so the page becomes interactive. Streaming SSR sends that HTML progressively, often using Suspense boundaries, so slow sections do not block ready content. React Server Components run exclusively on the server and send a serialized result rather than their component implementation JavaScript; they are never hydrated. Client Components can still contribute to server-rendered HTML, but their JavaScript is sent to the browser and hydrated. Modern Next.js combines RSC, SSR, streaming, and hydration rather than treating them as mutually exclusive choices.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-8d13a3c770aa","heading":"Interview-ready answer › Five things to remember","text":"Five things to remember","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-889f4b18780b","heading":"Interview-ready answer › Five things to remember","text":"CSR: React creates the DOM in the browser.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-c9d39d38549a","heading":"Interview-ready answer › Five things to remember","text":"SSR: The server generates initial HTML.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ef24389f534a","heading":"Interview-ready answer › Five things to remember","text":"Streaming: Ready HTML can arrive before slower sections finish.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-34c1875ad87a","heading":"Interview-ready answer › Five things to remember","text":"RSC: Server-only component code stays on the server; no hydration for those components.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-ebe6601f8e0a","heading":"Interview-ready answer › Five things to remember","text":"Hydration: Browser-side React activates previously server-rendered interactive UI.","kind":"Notes"},{"page":"react-rendering.html","topic":"React Rendering: Updates, Strategies & Hydration","anchor":"search-d8c46b1ac722","heading":"Interview-ready answer › Five things to remember","text":"One-line summary: SSR is about HTML generation, RSC is about component execution boundaries, streaming is about delivery timing, and hydration is about client interactivity.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"typescript-title","heading":"","text":"TypeScript","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-3dd064551908","heading":"","text":"Model valid states and reusable contracts while keeping static guarantees separate from runtime validation.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-a2129b1d773b","heading":"","text":"Static types vs. runtime validation","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-ffb60694fc7f","heading":"","text":"Structural typing, interfaces & object contracts","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-ad9305f22ba6","heading":"","text":"Discriminated unions, narrowing & never","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-4173940e8415","heading":"","text":"Generics, constraints & reusable APIs","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-b6124fd50abd","heading":"","text":"satisfies, const assertions & utility types","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-6015471b9b3e","heading":"","text":"Interview review: types express guarantees you can defend","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-boundaries","heading":"Static types vs. runtime validation","text":"Static types vs. runtime validation","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-boundaries-definition","heading":"Static types vs. runtime validation","text":"TypeScript checks code statically and erases most type syntax during compilation. It does not validate incoming JSON, enforce authorization, or change JavaScript runtime behavior. A type assertion tells the compiler to trust you; it is not a conversion or validation step.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-ebf3e811e0c5","heading":"Static types vs. runtime validation","text":"type User = { id: string; name: string }; function isUser(value: unknown): value is User { return typeof value === 'object' && value !== null && 'id' in value && typeof value.id === 'string' && 'name' in value && typeof value.name === 'string'; } const raw: unknown = JSON.parse('{\"id\":\"42\",\"name\":\"Ada\"}'); if (!isUser(raw)) throw new Error('Invalid user response'); raw.name.toUpperCase(); // Narrowed to User.","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-a17a807be4e0","heading":"Static types vs. runtime validation","text":"Use: Treat network/storage values as unknown and validate at trust boundaries. For complex schemas, use a maintained schema validator and infer compatible types where possible. A hand-written type predicate can lie too; verify its checks and contract.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-c3f8492f7ad1","heading":"Static types vs. runtime validation","text":"Choose: unknown requires narrowing before use; any disables checking and can propagate unsafety. Reserve any for constrained interop boundaries rather than application-wide models. Generated API types improve consistency but still do not validate a response.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-structural","heading":"Structural typing, interfaces & object contracts","text":"Structural typing, interfaces & object contracts","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-structural-definition","heading":"Structural typing, interfaces & object contracts","text":"Structural typing checks whether a value has the required shape, rather than requiring a declared nominal relationship. Extra-property checks on fresh object literals catch likely mistakes, but TypeScript object types are not generally exact object schemas.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e9dd59a424be","heading":"Structural typing, interfaces & object contracts","text":"Example: A value with id, name, and avatar can satisfy a function accepting only id/name. Use interface for extendable object contracts and type for unions, tuples, and other compositions; both can describe most ordinary object shapes.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-99f8804d597a","heading":"Structural typing, interfaces & object contracts","text":"Important distinctions: readonly restricts writes through that type, not runtime mutation or deep aliasing. Optional properties and explicit undefined are not always interchangeable, especially with exactOptionalPropertyTypes. Enable strict null checking and avoid treating missing data as present with repeated non-null assertions.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-96d27bff4846","heading":"Structural typing, interfaces & object contracts","text":"When not to model everything: Prefer small domain contracts over types that mirror every implementation detail. Branded types can prevent accidental mixing of structurally identical IDs, but require disciplined constructors/validation; they are not a runtime security mechanism.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-unions","heading":"Discriminated unions, narrowing & never","text":"Discriminated unions, narrowing & never","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-unions-definition","heading":"Discriminated unions, narrowing & never","text":"A discriminated union represents valid alternatives with a shared literal field. Narrowing refines the type through control flow. never represents an impossible value and can enforce exhaustive handling as the union evolves.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-77f7ff18a62e","heading":"Discriminated unions, narrowing & never","text":"type Result = | { status: 'success'; value: string } | { status: 'error'; message: string }; function assertNever(value: never): never { throw new Error('Unhandled result'); } function describe(result: Result): string { switch (result.status) { case 'success': return result.value; case 'error': return result.message; default: return assertNever(result); } }","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-15221962bda8","heading":"Discriminated unions, narrowing & never","text":"Use: Async outcomes, reducer actions, parser results, and component props with mutually exclusive modes. This avoids optional fields that permit impossible combinations. See the state-machine union.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-2e2a9e585757","heading":"Discriminated unions, narrowing & never","text":"Alternatives: A boolean is enough for one independent toggle. Avoid a large union for unrelated data; separate responsibilities. Narrow unknown inputs with checks before relying on the discriminant.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-generics","heading":"Generics, constraints & reusable APIs","text":"Generics, constraints & reusable APIs","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-generics-definition","heading":"Generics, constraints & reusable APIs","text":"Generics preserve relationships between types. A useful generic says how an input type relates to an output or another input; it is more than a placeholder for any.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-dd72fb45296e","heading":"Generics, constraints & reusable APIs","text":"function byId\u003cT extends { id: string }>(items: readonly T[], id: string): T | undefined { return items.find(item => item.id === id); } const user = byId([{ id: '42', name: 'Ada' }], '42'); // user is { id: string; name: string } | undefined; the name field is preserved.","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-838d4eba848d","heading":"Generics, constraints & reusable APIs","text":"Use: Generic collections, typed component items, and adapters that preserve a domain model. Constrain only what the implementation needs; allow inference instead of requiring many explicit type arguments.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-7adf17c5fb31","heading":"Generics, constraints & reusable APIs","text":"Tradeoffs: Deep conditional types and broad generic component APIs can make errors inscrutable. If two inputs need no type relationship, a concrete interface or unknown is often clearer. Avoid a “generic” response helper that simply casts unvalidated JSON to T.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-2ec7488712e5","heading":"Generics, constraints & reusable APIs","text":"Comparison: Use unions for known alternatives, overloads for distinct call signatures where inference benefits, and generics for a relationship that varies across calls. These choices complement reusable component contracts.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-utilities","heading":"satisfies, const assertions & utility types","text":"satisfies, const assertions & utility types","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-utilities-definition","heading":"satisfies, const assertions & utility types","text":"satisfies checks assignability without replacing the expression’s inferred type with the target type. as const preserves literal types and makes literal object/array members readonly at the type level; neither freezes an object at runtime.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-24de2ec73ac4","heading":"satisfies, const assertions & utility types","text":"const routes = { home: '/', profile: '/profile' } as const satisfies Record\u003cstring, `/${string}`>; type RouteName = keyof typeof routes; // 'home' | 'profile' type User = { id: string; name: string; email: string }; type UserSummary = Pick\u003cUser, 'id' | 'name'>; type EditableUser = Omit\u003cUser, 'id'>;","kind":"Code"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-94e749fe2e8c","heading":"satisfies, const assertions & utility types","text":"Use utilities: Pick/Omit define projections; Record describes keyed values; Partial makes fields optional; ReturnType/Awaited extract related types. Partial is shallow and is not automatically a valid PATCH schema—some field combinations may be forbidden.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"search-e12dd8f2c012","heading":"satisfies, const assertions & utility types","text":"Choose deliberately: Use an annotation when callers should see an abstract contract, satisfies to check a configuration while retaining its useful inferred shape, and an assertion only when external evidence justifies it. Prefer an explicit domain type over a long chain of utility transformations that hides business meaning.","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-review","heading":"Interview review: types express guarantees you can defend","text":"Interview review: types express guarantees you can defend","kind":"Notes"},{"page":"typescript.html","topic":"TypeScript","anchor":"ts-review-definition","heading":"Interview review: types express guarantees you can defend","text":"Show how types eliminate invalid states, preserve input/output relationships, and expose null/error paths. Then identify where runtime validation is still necessary. A well-typed API should be easier to use correctly, not simply impressive to read. Connect contracts to server validation and generated GraphQL types.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"web-security-title","heading":"","text":"Web Security & Authentication","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-b233b83661e5","heading":"","text":"Establish identity and resource permissions, manage sessions and credentials, then examine browser vulnerabilities and API defenses.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fcde8723064a","heading":"","text":"Secure applications protect against browser attacks, verify identity, enforce permissions, and defend API endpoints. Each layer addresses a different risk.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d20082617724","heading":"","text":"Authentication & authorization","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-18398ff73632","heading":"","text":"Session lifecycle: establish, renew & expire","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-423392b8b00a","heading":"","text":"Object-level authorization: enforce access per resource","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-df4e351a0461","heading":"","text":"Web vulnerabilities","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d26ad62f895e","heading":"","text":"API security","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-884397c1e592","heading":"","text":"Interview-ready answer","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-auth","heading":"Authentication & authorization","text":"Authentication & authorization","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6d83b6ece1d4","heading":"Authentication & authorization","text":"Authentication verifies who the user is. Authorization determines what that user may do. For example, signing in establishes identity; checking whether that user can delete a project enforces permissions. Enforce authorization on the server for every protected operation. Scope caches to the correct user or tenant so performance optimizations do not bypass data isolation.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-af03e751f76c","heading":"Authentication & authorization","text":"OAuth 2.0: A framework for delegated authorization using access tokens, such as allowing an app to access a user’s calendar without sharing their password. OAuth itself is not a login protocol; OpenID Connect (OIDC) adds an identity layer. Browser and mobile apps commonly use the Authorization Code flow with PKCE (Proof Key for Code Exchange), which binds authorization-code redemption to the client that initiated the flow.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-042271bf5ec1","heading":"Authentication & authorization","text":"JWT · JSON Web Token: A token format containing claims, commonly signed and used in authentication and authorization systems. A signed JWT provides integrity, not confidentiality: its payload is readable, so do not put secrets in it. Verify the signature and permitted algorithm, then validate claims including issuer (iss), audience (aud), expiration (exp), and not-before (nbf, when present). JWT is a format; OAuth is a framework, and OAuth access tokens do not have to be JWTs.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-cc8a1a177642","heading":"Authentication & authorization","text":"RBAC · Role-Based Access Control: Assign permissions to roles such as admin, editor, and viewer, then assign roles to users. Also enforce object-level authorization for resource ownership and tenant isolation. Missing these checks can cause IDOR (Insecure Direct Object Reference), also called BOLA (Broken Object Level Authorization) in API security.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-sessions","heading":"Session lifecycle: establish, renew & expire","text":"Session lifecycle: establish, renew & expire","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7aaf8435ef29","heading":"Session lifecycle: establish, renew & expire","text":"A session links subsequent requests to an authenticated identity. A server-side session commonly uses an opaque cookie identifier; token-based APIs may use short-lived access tokens and longer-lived refresh credentials. Both designs need expiration, revocation, and server-side authorization.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-2018ae2d3681","heading":"Session lifecycle: establish, renew & expire","text":"Establish: Verify credentials or complete OIDC, then rotate the session identifier after login or privilege changes to prevent session fixation. Set appropriate cookie attributes and return only the user data the UI needs.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-f85bc33d6473","heading":"Session lifecycle: establish, renew & expire","text":"Use: Validate the session or token on protected requests. Apply idle and absolute timeouts appropriate to the application. A frontend timer is a UX hint; the server enforces expiration.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-8c3e4a414f46","heading":"Session lifecycle: establish, renew & expire","text":"Renew: Refresh through the intended protocol or session endpoint. Coordinate concurrent renewal attempts and retry the original request at most under a bounded policy. Avoid recursive refresh loops; an unauthenticated 401 differs from a permission-denied 403.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5579c1c7ffd3","heading":"Session lifecycle: establish, renew & expire","text":"End: Invalidate the relevant server session or refresh credential and clear identity-scoped client data. Require reauthentication for sensitive actions when the risk warrants it.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-token-storage","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"Token storage: model XSS and CSRF separately","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7cd4bc156446","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"ChoiceBenefitExposure and mitigation","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-0cb5584e6bbc","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"HttpOnly session cookie / BFFJavaScript cannot read the credential; a backend-for-frontend can keep upstream tokens server-side.Cookies are sent automatically: apply CSRF protection. XSS can still issue authenticated actions. Adds server-side session/proxy responsibilities.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-f095b0f2d93c","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"In-memory access tokenNo persistent token remains in web storage after the page is gone.Reload requires a renewal/login path. Injected JavaScript can still steal or use a token during execution; memory is not an XSS boundary.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7d3aeddce7a5","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"localStorage / sessionStorage tokenConvenient client access; localStorage survives restarts, sessionStorage supports tab-lifetime persistence.Readable by same-origin JavaScript and exposed to XSS. Avoid persistent high-value credentials where a safer architecture fits. Encrypting with a key available to the same JavaScript does not fix this exposure.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-51eaf7611407","heading":"Session lifecycle: establish, renew & expire › Token storage: model XSS and CSRF separately","text":"Cookie configuration: Use Secure, HttpOnly, an appropriate SameSite policy, and narrow scope. A __Host- cookie requires Secure, Path=/, and no Domain attribute, reducing domain-scoping mistakes. Cross-site cookie flows may require SameSite=None; Secure and can still face browser restrictions. Cookie storage does not replace XSS prevention.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-refresh-rotation","heading":"Session lifecycle: establish, renew & expire › Refresh-token rotation & replay detection","text":"Refresh-token rotation & replay detection","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-389bc4d9a177","heading":"Session lifecycle: establish, renew & expire › Refresh-token rotation & replay detection","text":"With refresh-token rotation, the authorization server issues a replacement refresh token and invalidates the previous one on successful redemption. Reuse of an invalidated token can indicate theft; the server can revoke the affected token family and require reauthentication according to its policy. Short access-token lifetimes limit exposure but do not make already-issued tokens immediately revocable.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e1569b3ae7eb","heading":"Session lifecycle: establish, renew & expire › Refresh-token rotation & replay detection","text":"Concurrency trap: Two tabs redeeming the same refresh token can look like replay. Coordinate renewal through a shared owner/BFF or a suitable coordination mechanism; a promise shared within one tab does not coordinate other tabs. Follow the identity provider’s rotation and reuse policy, and avoid storing refresh tokens in ordinary web storage. BroadcastChannel can distribute session-change notifications without distributing credentials.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-logout","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Logout, revocation & cache cleanup","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-71d5527d11fb","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Server boundary: Invalidate the session or revoke refresh credentials through a protected endpoint. Clear cookies with matching name, path, and domain scope. Local token deletion alone does not invalidate a stolen token.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-5531ca7d8d26","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Access-token limits: A self-contained JWT can remain valid until expiry unless resource servers consult revocation/introspection or another server-side policy. Local app logout and identity-provider logout are distinct operations.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-192a00b86c0c","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Client boundary: Clear user/tenant query caches, stores, and sensitive persisted drafts; close real-time subscriptions. Cancel reads and prevent already-started responses from repopulating the previous user’s cache. Notify other tabs and revalidate on resume.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-b37f51a1efa7","heading":"Session lifecycle: establish, renew & expire › Logout, revocation & cache cleanup","text":"Failure behavior: If server invalidation fails, report that logout was not fully confirmed; clearing the local UI does not prove remote revocation. Personalized responses also need appropriate HTTP caching policies.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-object-authorization","heading":"Object-level authorization: enforce access per resource","text":"Object-level authorization: enforce access per resource","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-12b987a9717a","heading":"Object-level authorization: enforce access per resource","text":"BOLA / IDOR occurs when an API accepts a resource identifier without checking whether the authenticated principal may perform the requested action on that specific object. A valid login and an “editor” role are insufficient if the object belongs to another tenant.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-edbc78dcf8eb","heading":"Object-level authorization: enforce access per resource","text":"Example: For PATCH /api/projects/42, derive identity and tenant membership from the validated session; load project 42 within an authorized tenant/ownership scope; verify edit permission; allowlist editable fields; then write. Do not trust a client-supplied tenant ID, hidden button, or unguessable UUID as authorization. Apply equivalent checks to reads, downloads, list queries, batch endpoints, and real-time subscriptions.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7a0d3ba5ca92","heading":"Object-level authorization: enforce access per resource","text":"Implementation and tradeoff: Centralize policy checks so every handler enforces the same rules, while keeping resource-specific decisions explicit. Recheck permissions when membership changes and deny by default. Cache isolation and UI permission checks improve correctness and UX but never replace this server enforcement; see identity-scoped query lifecycles.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-vulnerabilities","heading":"Web vulnerabilities","text":"Web vulnerabilities","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-xss","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"XSS · Cross-Site Scripting","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-4a9e74ec91cf","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"What happens: An attacker injects malicious JavaScript that runs in the context of your website, potentially reading page data or acting as the user.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d8e4a959fb55","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"Prevent it: treat user input as text, not executable code.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-91a8070a19af","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"Output encoding (escaping): React escapes text interpolated as {comment}. When accepting children or render props, distinguish text nodes from intentionally supplied markup. For plain DOM code, element.textContent = comment is a safe DOM sink: it inserts text without parsing HTML. Encoding must match the output context; HTML escaping alone does not make arbitrary URLs or JavaScript safe.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-da763f17778b","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"HTML sanitisation: Sanitise rich HTML with a trusted library such as DOMPurify to remove unsafe elements, attributes, and URL schemes while keeping permitted markup. Never send raw user input to innerHTML or dangerouslySetInnerHTML.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-a484225d2cc9","heading":"Web vulnerabilities › XSS · Cross-Site Scripting","text":"Content Security Policy (CSP) — defense in depth: Restrict script execution with script-src, using nonces or hashes for approved scripts. CSP supplements output encoding and sanitisation. These protections remain necessary with both CSR and SSR.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-csrf","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"CSRF · Cross-Site Request Forgery","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fc37491ff638","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"What happens: An attacker tricks an authenticated browser into sending an unwanted request, such as changing an email address. The attack relies on credentials the browser sends automatically, typically session cookies.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-7a087277eb10","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"Prevent it: a login cookie alone should not approve a sensitive action.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6143ee23b85e","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"CSRF token validation: With the synchronizer token pattern, include an unpredictable, session-bound token in state-changing requests. The server validates it; the browser’s same-origin policy prevents an attacker’s site from reading it, assuming no XSS or permissive cross-origin access.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-e2d695a097fe","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"SameSite cookie policy: Use SameSite=Lax or Strict where your flow allows it. This restricts when cookies accompany requests from other sites.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-75ccb929f4f0","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"Origin validation & safe HTTP methods: Validate the Origin header against trusted origins, with a Referer check where appropriate. Client-side default-action cancellation does not protect a server endpoint from CSRF. GET must have read-only semantics; use state-changing methods such as POST with CSRF protection.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-8fece37a59e0","heading":"Web vulnerabilities › CSRF · Cross-Site Request Forgery","text":"Key distinction: XSS runs attacker code inside your site. CSRF exploits the browser’s existing authentication to send requests. HttpOnly cookies prevent JavaScript from reading the cookie, but do not stop injected code from making authenticated requests.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-2cc493d4ad31","heading":"Web vulnerabilities › SQL injection","text":"SQL injection","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-16be3789f24a","heading":"Web vulnerabilities › SQL injection","text":"The trap: User input becomes part of a SQL command.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1c3bf7f5e140","heading":"Web vulnerabilities › SQL injection","text":"Prevent it: parameterized queries (parameter binding). Keep SQL structure separate from values by binding input to placeholders. The database treats bound values as data, even if they look like SQL. Dynamic table names, column names, and sort directions require an allowlist; value placeholders do not cover SQL identifiers.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-97514c555808","heading":"Web vulnerabilities › SQL injection","text":"// Parameterized query (placeholder syntax depends on your DB driver) db.query('SELECT * FROM users WHERE email = ?', [email]);","kind":"Code"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-b4926080257c","heading":"Web vulnerabilities › Clickjacking","text":"Clickjacking","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-1aa53d7d8492","heading":"Web vulnerabilities › Clickjacking","text":"The trap: An attacker hides your page inside an iframe and tricks a user into clicking its buttons.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-79243c331b6a","heading":"Web vulnerabilities › Clickjacking","text":"Prevent it: anti-framing with CSP frame-ancestors. This prevents UI redressing through framing. Send this HTTP response header to block all framing:","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-cb4565cce61e","heading":"Web vulnerabilities › Clickjacking","text":"Content-Security-Policy: frame-ancestors 'none'","kind":"Code"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-32018449cee2","heading":"Web vulnerabilities › Clickjacking","text":"Use 'self' if your own site needs to embed it. X-Frame-Options: DENY is a legacy alternative for blocking frames.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-be1ae355109f","heading":"Web vulnerabilities › Open redirects","text":"Open redirects","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-26d5d7c67782","heading":"Web vulnerabilities › Open redirects","text":"The trap: A trusted-looking link to your app forwards the user to an attacker’s site.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-121ec6457477","heading":"Web vulnerabilities › Open redirects","text":"Prevent it: redirect destination validation using an allowlist.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d03c1fc8a793","heading":"Web vulnerabilities › Open redirects","text":"Server-side route mapping: Accept a destination key such as next=dashboard and map it to a fixed route such as /dashboard.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-4f085e19c44a","heading":"Web vulnerabilities › Open redirects","text":"URL parsing & origin validation: Resolve the URL with a standard parser, then validate its scheme and origin against an explicit allowlist. Checking that it starts with / is insufficient: //evil.example points to another site.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-api","heading":"API security","text":"API security","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-c94071c9efdb","heading":"API security","text":"Rate limiting: Restrict request frequency to reduce abuse, brute-force attempts, and resource exhaustion. Apply limits by user, API key, or IP as appropriate; Common algorithms include token bucket (allows controlled bursts) and sliding window (limits requests over a rolling interval). Return 429 Too Many Requests, optionally with Retry-After, when limits are exceeded.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-6ef3c4cc3526","heading":"API security","text":"HTTPS / TLS (Transport Layer Security): Provides confidentiality and integrity in transit, plus server authentication through certificate validation. TLS does not replace input validation or access checks.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-d7bcf7588fd2","heading":"API security","text":"CORS · Cross-Origin Resource Sharing: Browser-enforced rules controlling whether JavaScript from another origin can read a response. CORS builds on the same-origin policy (SOP); an origin is the scheme, host, and port. Configure Access-Control-Allow-Origin for trusted origins. Cookie-based credentialed requests also require Access-Control-Allow-Credentials: true and cannot use a wildcard allowed origin. For requests requiring a preflight, the browser sends OPTIONS to check permission before the actual request. CORS does not stop every cross-origin request or restrict non-browser clients, so it cannot replace authentication, authorization, or CSRF protection.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-fdb947d04a1a","heading":"API security","text":"For GraphQL, a single request may select substantial work. Apply operation cost limits and field/resource authorization alongside the HTTP and identity protections here.","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"security-review","heading":"Interview-ready answer","text":"Interview-ready answer","kind":"Notes"},{"page":"web-security.html","topic":"Web Security & Authentication","anchor":"search-98f6f890bb60","heading":"Interview-ready answer","text":"I separate identity, permissions, and attack prevention. Authentication establishes who the user is; server-side authorization checks what they can do. I prevent XSS with context-appropriate output encoding and HTML sanitisation, CSRF with token validation and SameSite cookie policies, and SQL injection with parameterized queries. For APIs, I use TLS, validate tokens, enforce access checks and rate limits, and configure CORS for the intended browser origins. OAuth delegates access, while JWT is one possible token format.","kind":"Notes"}];
